### Description:
This Terraform program configures a Route 53 weighted routing policy for a DNS zone named "main". The primary database instance is named "primary", and there are two replica instances named "replica-1" and "replica-2". The program sets up a hosted zone, creates A records for each instance, and configures a weighted routing policy to distribute traffic between the primary and replica instances.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

variable "primary_ip" {
  description = "IP address of the primary database instance"
  type        = string
  default     = "10.0.0.1" # Default IP address for the primary instance
}

variable "replica_1_ip" {
  description = "IP address of the first replica database instance"
  type        = string
  default     = "10.0.0.2" # Default IP address for the first replica instance
}

variable "replica_2_ip" {
  description = "IP address of the second replica database instance"
  type        = string
  default     = "10.0.0.3" # Default IP address for the second replica instance
}

resource "aws_route53_zone" "main" {
  name = "main.example.com"
}

resource "aws_route53_record" "primary" {
  zone_id = aws_route53_zone.main.id
  name    = "primary"
  type    = "A"
  ttl     = 300
  records = [var.primary_ip]
}

resource "aws_route53_record" "replica_1" {
  zone_id = aws_route53_zone.main.id
  name    = "replica-1"
  type    = "A"
  ttl     = 300
  records = [var.replica_1_ip]
}

resource "aws_route53_record" "replica_2" {
  zone_id = aws_route53_zone.main.id
  name    = "replica-2"
  type    = "A"
  ttl     = 300
  records = [var.replica_2_ip]
}

resource "aws_route53_record" "weighted_routing" {
  zone_id = aws_route53_zone.main.id
  name    = "db"
  type    = "A"
  ttl     = 300

  alias {
    evaluate_target_health = true
    name                  = "db.example.com"
    zone_id               = aws_route53_zone.main.id
    evaluate_target_health = true
  }

  weight = 50 # Weight for the primary instance
}

resource "aws_route53_record" "weighted_routing_replica" {
  zone_id = aws_route53_zone.main.id
  name    = "db"
  type    = "A"
  ttl     = 300

  alias {
    evaluate_target_health = true
    name                  = "db.example.com"
    zone_id               = aws_route53_zone.main.id
    evaluate_target_health = true
  }

  weight = 50 # Weight for the replica instances
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Variables are used to specify the IP addresses of the primary and replica instances. Default values are provided for simplicity.
- **Route 53 Zone**: A hosted zone named "main.example.com" is created.
- **A Records**: Three A records are created for the primary, replica-1, and replica-2 instances.
- **Weighted Routing**: Two A records are created with the same name ("db") but different weights (50% each). These records use an alias to point to the same target (the primary instance), allowing for weighted routing between the primary and replica instances.

