### Description:
This Terraform program configures a Blue/Green deployment using AWS Elastic Beanstalk and Route53. It sets up two Elastic Beanstalk environments named "blue" and "green". The program uses a weighted routing policy in Route53 to distribute traffic between these two environments based on predefined weights.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# Define variables with default values
variable "blue_environment_name" {
  default = "blue"
}

variable "green_environment_name" {
  default = "green"
}

variable "blue_weight" {
  default = 60
}

variable "green_weight" {
  default = 40
}

# Create an Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name        = var.blue_environment_name
  description = "Blue environment"
}

resource "aws_elastic_beanstalk_application" "app_green" {
  name        = var.green_environment_name
  description = "Green environment"
}

# Create Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "env" {
  application     = aws_elastic_beanstalk_application.app.name
  environment_name = var.blue_environment_name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_type = "t2.micro"
}

resource "aws_elastic_beanstalk_environment" "env_green" {
  application     = aws_elastic_beanstalk_application.app_green.name
  environment_name = var.green_environment_name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_type = "t2.micro"
}

# Create Route53 Hosted Zone
resource "aws_route53_zone" "example" {
  name = "example.com"
}

# Create Route53 Record Set for Blue Environment
resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.example.id
  name    = "blue.example.com"
  type    = "A"
  ttl     = 300

  alias {
    evaluate_target_health = true
    name                  = aws_elastic_beanstalk_environment.env.cname
    zone_id               = aws_elastic_beanstalk_environment.env.elastic_beanstalk_domain_name
  }
}

# Create Route53 Record Set for Green Environment
resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.example.id
  name    = "green.example.com"
  type    = "A"
  ttl     = 300

  alias {
    evaluate_target_health = true
    name                  = aws_elastic_beanstalk_environment.env_green.cname
    zone_id               = aws_elastic_beanstalk_environment.env_green.elastic_beanstalk_domain_name
  }
}

# Create IAM Role for Route53 DNS Management
resource "aws_iam_role" "route53_dns_management" {
  name = "route53-dns-management"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# Attach Managed Policies to IAM Role
resource "aws_iam_role_policy_attachment" "route53_dns_management_policy" {
  role       = aws_iam_role.route53_dns_management.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRoute53DNSManagement"
}

# Create IAM Role for Elastic Beanstalk Deployment
resource "aws_iam_role" "elastic_beanstalk_deployment" {
  name = "elastic-beanstalk-deployment"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# Attach Managed Policies to IAM Role
resource "aws_iam_role_policy_attachment" "elastic_beanstalk_deployment_policy" {
  role       = aws_iam_role.elastic_beanstalk_deployment.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBeanstalkServiceRole"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Variables are defined with default values for environment names and weights.
- **Elastic Beanstalk Applications**: Two Elastic Beanstalk applications are created, one for each environment.
- **Elastic Beanstalk Environments**: Two Elastic Beanstalk environments are set up, each with a specific solution stack and instance type.
- **Route53 Hosted Zone**: A Route53 hosted zone is created for the domain "example.com".
- **Route53 Record Sets**: Two Route53 record sets are created for the blue and green environments, using aliases to point to the CNAMEs of the Elastic Beanstalk environments.
- **IAM Roles**: Two IAM roles are created for Route53 DNS management and Elastic Beanstalk deployment, with the necessary permissions attached.

This configuration ensures that traffic is evenly distributed between the "blue" and "green" environments using a weighted routing policy in Route53.

