### Description:
This Terraform program sets up an Elastic Beanstalk environment linked to a relational database instance. The database instance is named "default," and the instance profile for the EC2 instances running the Elastic Beanstalk application is named "eb_ec2_profile." The program includes necessary IAM roles and configurations to ensure secure and efficient deployment.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Elastic Beanstalk EC2 Instances
resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role Policy Attachment
resource "aws_iam_role_policy_attachment" "eb_ec2_profile_policy" {
  role       = aws_iam_role.eb_ec2_profile.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
}

# RDS Database Instance
resource "aws_db_instance" "default" {
  allocated_storage  = 20
  engine            = "mysql"
  engine_version     = "5.7"
  instance_class     = "db.t2.micro"
  name              = "default"
  username          = "admin"
  password          = "securepassword123"
  parameter_group_name = "default.mysql5.7"
  publicly_accessible = false

  tags = {
    Name = "default-db-instance"
  }
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "example" {
  name = "example-app"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "example" {
  application         = aws_elastic_beanstalk_application.example.name
  name                = "example-env"
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_type       = "t2.micro"
  vpc_id             = aws_vpc.default.id
  security_groups     = [aws_security_group.default.id]

  option_settings = [
    {
      namespace = "aws:elasticbeanstalk:container:python"
      option_name = "WSGIPath"
      value       = "wsgi.py"
    },
    {
      namespace = "aws:rds:database"
      option_name = "DBName"
      value       = aws_db_instance.default.name
    },
    {
      namespace = "aws:rds:database"
      option_name = "DBUser"
      value       = aws_db_instance.default.username
    },
    {
      namespace = "aws:rds:database"
      option_name = "DBPassword"
      value       = aws_db_instance.default.password
    },
    {
      namespace = "aws:rds:database"
      option_name = "DBInstanceIdentifier"
      value       = aws_db_instance.default.name
    },
    {
      namespace = "aws:rds:database"
      option_name = "DBInstanceClass"
      value       = aws_db_instance.default.instance_class
    },
    {
      namespace = "aws:rds:database"
      option_name = "AllocatedStorage"
      value       = aws_db_instance.default.allocated_storage
    },
    {
      namespace = "aws:rds:database"
      option_name = "Engine"
      value       = aws_db_instance.default.engine
    },
    {
      namespace = "aws:rds:database"
      option_name = "EngineVersion"
      value       = aws_db_instance.default.engine_version
    },
    {
      namespace = "aws:rds:database"
      option_name = "PubliclyAccessible"
      value       = aws_db_instance.default.publicly_accessible
    },
  ]

  depends_on = [aws_db_instance.default]
}

# VPC Configuration
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "default-vpc"
  }
}

# Security Group Configuration
resource "aws_security_group" "default" {
  name        = "default-sg"
  description = "Default security group for Elastic Beanstalk"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "default-sg"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Roles**: Two IAM roles are created: one for the EC2 instances (`eb_ec2_profile`) and another for the RDS database (`default-db-instance`). The EC2 role allows Elastic Beanstalk to assume it, while the RDS role grants access to the database.
- **RDS Database Instance**: A MySQL database instance is created with default settings.
- **Elastic Beanstalk Application**: An Elastic Beanstalk application is defined.
- **Elastic Beanstalk Environment**: An environment is created linked to the application, using the RDS database instance. The environment is configured with the necessary option settings to connect to the database.
- **VPC and Security Group**: A VPC and security group are set up to manage network traffic for the Elastic Beanstalk environment.

This configuration ensures that the Elastic Beanstalk environment is securely connected to a relational database instance, leveraging AWS services effectively.

