### Description:
This Terraform program will create two AWS Elastic Beanstalk environments, one for production and one for staging, along with their respective RDS databases. It will also configure an IAM role named "eb_ec2_profile" to allow EC2 instances associated with these environments to access the RDS databases.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Change to your desired region
}

# Default values for variables
variable "db_instance_class" {
  default = "db.t2.micro"
}

variable "db_instance_storage" {
  default = 20
}

variable "db_instance_username" {
  default = "admin"
}

variable "db_instance_password" {
  default = "securepassword123"
}

# IAM Role for Elastic Beanstalk EC2 Instances
resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# RDS Database for Production
resource "aws_rds_instance" "prod_db" {
  identifier       = "prod-db"
  engine           = "mysql"
  engine_version   = "5.7"
  instance_class   = var.db_instance_class
  allocated_storage = var.db_instance_storage
  username         = var.db_instance_username
  password         = var.db_instance_password
  publicly_accessible = false

  vpc_security_group_ids = [aws_security_group.prod_db.id]

  tags = {
    Name = "prod-db"
  }
}

# RDS Database for Staging
resource "aws_rds_instance" "staging_db" {
  identifier       = "staging-db"
  engine           = "mysql"
  engine_version   = "5.7"
  instance_class   = var.db_instance_class
  allocated_storage = var.db_instance_storage
  username         = var.db_instance_username
  password         = var.db_instance_password
  publicly_accessible = false

  vpc_security_group_ids = [aws_security_group.staging_db.id]

  tags = {
    Name = "staging-db"
  }
}

# Security Group for Production DB
