### Description of the Terraform Program

This Terraform program will create an AWS VPC with an internet gateway, two public subnets, a security group, and a route table associated with the public subnets. It will also set up two Elastic Beanstalk environments, each connected to a shared RDS database. The VPC, subnets, security group, and route table will be named as specified: "eb_vpc", "eb_subnet_public_1", "eb_subnet_public_2", and "eb_env_sg". The Elastic Beanstalk environments will be named "env1" and "env2", and they will be connected to the shared RDS database named "shared_rds".

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create an Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.eb_vpc.id
}

# Create a Route Table for the Public Subnets
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.eb_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

# Create Public Subnets
resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id     = aws_vpc.eb_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id     = aws_vpc.eb_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"

  tags = {
    Name = "eb_subnet_public_2"
  }
}

# Associate the Route Table with the Public Subnets
resource "aws_route_table_association" "public_rt_assoc_1" {
  subnet_id      = aws_subnet.eb_subnet_public_1.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table_association" "public_rt_assoc_2" {
  subnet_id      = aws_subnet.eb_subnet_public_2.id
  route_table_id = aws_route_table.public_rt.id
}

# Create a Security Group for Elastic Beanstalk Environments
resource "aws_security_group" "eb_env_sg" {
  name        = "eb_env_sg"
  description = "Security group for Elastic Beanstalk environments"
  vpc_id       = aws_vpc.eb_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Shared RDS Database
resource "aws_db_instance" "shared_rds" {
  engine              = "mysql"
  engine_version      = "8.0.23"
  instance_class      = "db.t2.micro"
  allocated_storage   = 20
  username           = "admin"
  password           = "password123"
  db_name            = "shared_rds"
  publicly_accessible = true
  vpc_security_groups = [aws_security_group.eb_env_sg.id]

  tags = {
    Name = "shared_rds"
  }
}

# Create Elastic Beanstalk Environment 1
resource "aws_elastic_beanstalk_application" "app1" {
  name = "app1"
}

resource "aws_elastic_beanstalk_environment" "env1" {
  application_name = aws_elastic_beanstalk_application.app1.name
  environment_name = "env1"
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_type = "t2.micro"
  vpc_id = aws_vpc.eb_vpc.id
  subnet_ids = [aws_subnet.eb_subnet_public_1.id]
  security_groups = [aws_security_group.eb_env_sg.id]
  rds_instance_identifier = aws_db_instance.shared_rds.id
}

# Create Elastic Beanstalk Environment 2
resource "aws_elastic_beanstalk_application" "app2" {
  name = "app2"
}

resource "aws_elastic_beanstalk_environment" "env2" {
  application_name = aws_elastic_beanstalk_application.app2.name
  environment_name = "env2"
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_type = "t2.micro"
  vpc_id = aws_vpc.eb_vpc.id
  subnet_ids = [aws_subnet.eb_subnet_public_2.id]
  security_groups = [aws_security_group.eb_env_sg.id]
  rds_instance_identifier = aws_db_instance.shared_rds.id
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Internet Gateway**: An internet gateway is created and associated with the VPC.
- **Route Table**: A route table is created and associated with the public subnets, allowing traffic to the internet.
- **Subnets**: Two public subnets are created in different availability zones.
- **Security Group**: A security group is created to allow SSH, HTTP, and HTTPS access to the Elastic Beanstalk environments.
- **RDS Database**: A shared RDS database is created and linked to the subnets.
- **Elastic Beanstalk Environments**: Two Elastic Beanstalk environments are created, each connected to the shared RDS database and the appropriate subnet and security group.

This configuration ensures that all resources are properly deployed and interconnected according to the specified requirements.

