### Description of the Terraform Program

This Terraform program sets up a blue/green deployment architecture using AWS services. It includes the following components:

1. **VPC**: A virtual private cloud to isolate the infrastructure.
2. **Subnets**: Public and private subnets for EC2 instances.
3. **Route 53**: To manage DNS records for the blue and green environments.
4. **EC2 Instances**: Two instances for the blue and green environments.
5. **RDS Database**: A shared database for both environments.
6. **IAM Roles**: For EC2 instances to access the RDS database.
7. **Health Checks**: To monitor the availability of the EC2 instances.
8. **Failover Routing Policy**: To route traffic to the healthy environment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "db_name" {
  default = "myapp_db"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  default = "10.0.2.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.private_subnet_cidr_block
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_security_group" "web" {
  name        = "web-sg"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "blue" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.instance_type
  key_name       = "your-key-pair-name" # Replace with your key pair name
  security_groups = [aws_security_group.web.id]
  subnet_id      = aws_subnet.public.id

  tags = {
    Name = "blue-env"
  }
}

resource "aws_instance" "green" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.instance_type
  key_name       = "your-key-pair-name" # Replace with your key pair name
  security_groups = [aws_security_group.web.id]
  subnet_id      = aws_subnet.public.id

  tags = {
    Name = "green-env"
  }
}

resource "aws_rds_instance" "db" {
  engine              = "mysql"
  engine_version      = "5.7.22"
  instance_class      = "db.t2.micro"
  allocated_storage   = 20
  db_name            = var.db_name
  username           = "admin"
  password           = "password123"
  publicly_accessible = false
  vpc_security_group_ids = [aws_security_group.web.id]

  tags = {
    Name = "myapp-db"
  }
}

resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "db_access" {
  role       = aws_iam_role.eb_ec2_profile.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSReadOnlyAccess"
}

resource "aws_route53_zone" "example" {
  name = "example.com"
}

resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.example.zone_id
  name    = "blue.example.com"
  type    = "A"
  ttl     = 300
  records = [aws_instance.blue.public_ip_address]
}

resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.example.zone_id
  name    = "green.example.com"
  type    = "A"
  ttl     = 300
  records = [aws_instance.green.public_ip_address]
}

resource "aws_route53_health_check" "blue" {
  fqdn = "blue.example.com"
  port = 80
  type = "HTTP"
  resource_path = "/"
}

resource "aws_route53_health_check" "green" {
  fqdn = "green.example.com"
  port = 80
  type = "HTTP"
  resource_path = "/"
}

resource "aws_route53_record" "blue_failover" {
  zone_id = aws_route53_zone.example.zone_id
  name    = "example.com"
  type    = "CNAME"
  ttl     = 300
  records = ["blue.example.com"]
  alias {
    evaluate_target_health = true
    name                  = aws_route53_health_check.blue.fqdn
    zone_id               = aws_route53_zone.example.zone_id
  }
}

resource "aws_route53_record" "green_failover" {
  zone_id = aws_route53_zone.example.zone_id
  name    = "example.com"
  type    = "CNAME"
  ttl     = 300
  records = ["green.example.com"]
  alias {
    evaluate_target_health = true
    name                  = aws_route53_health_check.green.fqdn
    zone_id               = aws_route53_zone.example.zone_id
  }
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **Variables**: Variables are defined for the database name, instance type, VPC CIDR block, public subnet CIDR block, and private subnet CIDR block.
- **VPC and Subnets**: A VPC and two subnets are created, one public and one private.
- **Route 53**: A Route 53 zone is created, and DNS records are set up for the blue and green environments.
- **EC2 Instances**: Two EC2 instances are created in the public subnet, each with a security group allowing HTTP and HTTPS traffic.
- **RDS Database**: A MySQL RDS instance is created in the private subnet, accessible only from the EC2 instances.
- **IAM Role**: An IAM role is created for EC2 instances to access the RDS database.
- **Health Checks**: Health checks are set up for each environment to monitor their availability.
- **Failover Routing Policy**: CNAME records are set up to route traffic to the healthy environment based on the health check results.

