### Description:
This Terraform program creates an AWS Elastic Beanstalk application that runs a version of Go. It includes a VPC, subnets, security groups, an Elastic Load Balancer, an Auto Scaling group, and an Elastic Beanstalk environment. The program also sets up IAM roles for the necessary services.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Change to your desired region
}

# Default values for variables
variable "go_version" {
  default = "1.16"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "environment_name" {
  default = "go-app-env"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "GoAppVPC"
  }
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "PublicSubnet${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block     = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index + 2]

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "PrivateSubnet${count.index + 3}"
  }
}

# Security Group Configuration
resource "aws_security_group" "web" {
  name        = "WebSG"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "WebSG"
  }
}

resource "aws_security_group" "app" {
  name        = "AppSG"
  description = "Allow SSH and HTTP traffic"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AppSG"
  }
}

# Elastic Load Balancer Configuration
resource "aws_elb" "load_balancer" {
  name               = "GoAppELB"
  subnets            = aws_subnet.public[*].id
  security_groups      = [aws_security_group.web.id]
  internal           = false
  cross_zone_load_balancing = true

  health_check {
    target = "HTTP:80/"
    interval = 30
    timeout = 5
    healthy_threshold = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "GoAppELB"
  }
}

# Auto Scaling Group Configuration
resource "aws_autoscaling_group" "app" {
  name                 = "GoAppASG"
  launch_configuration = aws_launch_configuration.app.id
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2

  vpc_zone_identifier = aws_subnet.private[*].id

  health_check_type = "EC2"
  health_check_grace_period = 300

  tags = {
    Name = "GoAppASG"
  }
}

# Launch Configuration Configuration
resource "aws_launch_configuration" "app" {
  image_id                  = "ami-0c55b159cbfafe1f0" # Change to your desired AMI
  instance_type              = var.instance_type
  key_name                  = "your-key-pair-name" # Change to your key pair name
  security_groups           = [aws_security_group.app.id]
  user_data                = <<-EOF
    #!/bin/bash
    sudo apt-get update
    sudo apt-get install -y wget unzip
    wget https://dl.google.com/go/${var.go_version}.linux-amd64.tar.gz
    tar -C /usr/local -xzf go${var.go_version}.linux-amd64.tar.gz
    export PATH=$PATH:/usr/local/go/bin
    EOF

  associate_public_ip_address = true

  tags = {
    Name = "GoAppLaunchConfig"
  }
}

# Elastic Beanstalk Application Configuration
resource "aws_elastic_beanstalk_application" "go_app" {
  name = var.environment_name

  tags = {
    Name = "GoAppApplication"
  }
}

# Elastic Beanstalk Environment Configuration
resource "aws_elastic_beanstalk_environment" "go_env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.go_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Go 1.16"
  instance_type       = var.instance_type
  vpc_id              = aws_vpc.main.id
  subnet_ids          = aws_subnet.private[*].id
  security_groups      = [aws_security_group.web.id]

  tags = {
    Name = "GoAppEnvironment"
  }
}
```

### Explanation:
- **Provider Configuration**: Sets the AWS region to `us-west-2`.
- **Variables**: Define default values for Go version, instance type, and environment name.
- **VPC**: Creates a VPC with two public and two private subnets.
- **Security Groups**: Define security groups for web and app traffic.
- **Elastic Load Balancer**: Configures an ELB to distribute traffic across instances.
- **Auto Scaling Group**: Manages the number of instances based on load.
- **Launch Configuration**: Defines the AMI, instance type, and user data script to install Go.
- **Elastic Beanstalk Application**: Creates an application.
- **Elastic Beanstalk Environment**: Deploys the application to the environment using the specified solution stack.

Make sure to replace placeholders like `your-key-pair-name` and `ami-0c55b159cbfafe1f0` with your actual key pair name and AMI ID. Also, ensure that the solution stack name matches the version of Go you want to use.

