### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "app_name" {
  default = "my-web-app"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "db_instance_class" {
  default = "db.t2.micro"
}

