  default = "password123"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = ["10.0.1.0/24", "10.0.2.0/24"]
  vpc_id         = aws_vpc.main.id
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block     = ["10.0.3.0/24", "10.0.4.0/24"]
  vpc_id         = aws_vpc.main.id
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${var.app_name}-web-sg"
  description = "Security group for the web application"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "db" {
  name        = "${var.app_name}-db-sg"
  description = "Security group for the database"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.instance_type
  key_name       = "my-key-pair"          # Replace with your key pair name
  security_groups = [aws_security_group.web.id]
  subnet_id      = aws_subnet.public[0].id

  tags = {
    Name = "${var.app_name}-web"
  }
}

resource "aws_db_instance" "db" {
  engine              = "mysql"
  engine_version      = "5.7"
  instance_class      = var.db_instance_class
  username            = var.db_username
  password            = var.db_password
  allocated_storage   = 20
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]

  tags = {
    Name = "${var.app_name}-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.app_name}-db-subnet-group"
  subnet_ids = [aws_subnet.private[0].id, aws_subnet.private[1].id]
}

resource "aws_elb" "web" {
  name               = "${var.app_name}-elb"
  subnets             = aws_subnet.public[*].id
  security_groups     = [aws_security_group.web.id]
  listeners {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout            = 3
    interval           = 30
  }

  tags = {
    Name = "${var.app_name}-elb"
  }
}

resource "aws_elb_attachment" "web" {
  elb_id      = aws_elb.web.id
  instance_id = aws_instance.web.id
}
```

