### Description:
This Terraform program creates a basic AWS CodeBuild project with an IAM role and a GitHub source. The IAM role is configured to allow CodeBuild to access the necessary AWS services and repositories. The GitHub source is set up to trigger the build when changes are pushed to the specified repository.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define the IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
  role       = aws_iam_role.codebuild_role.name
}

# Define the CodeBuild project
resource "aws_codebuild_project" "example" {
  name         = "example-codebuild-project"
  description = "Example CodeBuild project"

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:4.0"
    type        = "LINUX_CONTAINER"
  }

  service_role = aws_iam_role.codebuild_role.arn

  source {
    type        = "GITHUB"
    location    = "https://github.com/example-user/example-repo.git"
    git_clone_depth = 1
  }

  triggers {
    type = "GITHUB_WEBHOOK"
    branch_filter = "*"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **IAM Role**: An IAM role named `codebuild-role` is created with permissions to assume the role from CodeBuild. It also attaches the `AWSCodeBuildServiceRolePolicy` to grant necessary permissions.
- **CodeBuild Project**: A CodeBuild project named `example-codebuild-project` is defined. It uses a standard Linux container image (`aws/codebuild/standard:4.0`) and sets up a GitHub source with the specified repository URL. The project does not produce any artifacts and is triggered by GitHub webhooks on any branch change.

