### Description:
This Terraform program creates an AWS Lex Bot with multiple slots. The bot is designed to handle user interactions and process data based on predefined slots. The program includes IAM roles for the Lambda function and the Lex Bot, as well as a default region configuration.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Function
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Function
resource "aws_iam_policy" "lambda_execution_policy" {
  name = "lambda_execution_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "lambda_execution_policy_attachment" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_execution_policy.arn
}

# Lambda Function
resource "aws_lambda_function" "lex_bot_handler" {
  filename      = "path/to/your/handler.zip"
  function_name = "lex_bot_handler"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  environment {
    variables = {
      AWS_REGION = aws_provider.aws.region.name
    }
  }

  source_code_hash = filebase64sha256("path/to/your/handler.zip")
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex_bot_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name = "lex_bot_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lex:GetBot",
          "lex:GetIntent",
          "lex:GetSlotType",
          "lex:PutBotAlias",
          "lex:PutBotLocale",
          "lex:PutIntent",
          "lex:PutSlotType"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# Lex Bot
resource "aws_lex_bot" "example_bot" {
  name                = "example-bot"
  description         = "Example Lex Bot"
  intents             = ["example-intent"]
  voice_id            = "Joanna"
  child_directed      = false
  locale              = "en-US"
  abort_statement     = "I'm sorry, I didn't understand that."
  clarification_prompt = "Could you please rephrase your question?"

  slot_types {
    name           = "example-slot-type"
    description   = "Example Slot Type"
    value_selection_strategy = "ORIGINAL_VALUE"
    values         = [
      { name = "value1" },
      { name = "value2" }
    ]
  }

  intents {
    name = "example-intent"
    sample utterances = [
      "What is the weather today?",
      "Tell me about the weather tomorrow."
    ]

    slots {
      name           = "example-slot"
      description   = "Example Slot"
      slot_type_name = aws_lex_slot_type.example_slot_type.name
      value_selection_strategy = "ORIGINAL_VALUE"
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **IAM Roles**: Two IAM roles are created: one for the Lambda function (`lambda_execution_role`) and another for the Lex Bot (`lex_bot_role`). Each role has an associated policy that allows the necessary permissions for their respective services.
- **Lambda Function**: A Lambda function is defined with a Python handler. It uses the `aws_lambda_function` resource and includes environment variables for the AWS region.
- **Lex Bot**: A Lex Bot is created with a name, description, intents, voice ID, and slot types. The bot includes a sample utterance for each intent and a slot for each intent.

This configuration ensures that the Lambda function and Lex Bot have the necessary permissions to interact with AWS services and manage the bot's intents and slot types.

