  name        = var.intent_name
  description = "Intent to order pizza"

  sample utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order me a pizza",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "order_details_intent" {
  name        = var.followup_intent_name
  description = "Intent to gather additional details about the order"

  sample utterances = [
    "What size do you want the pizza?",
    "Do you want pepperoni on it?",
    "Can you tell me more about the toppings?",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}
```

