### Description:
The Terraform program will create an AWS Lex Bot named "TripBookingBot" for booking a trip. The bot will have intents, slots, utterances, and other necessary components to handle user requests for booking flights, hotels, and activities. It will also include IAM roles and policies to ensure proper access control.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "LexBotRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name = "LexBotPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "lambda:InvokeFunction"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# AWS Lex Bot
resource "aws_lex_bot" "trip_booking_bot" {
  name                  = "TripBookingBot"
  description           = "A bot to help users book trips."
  intents               = ["BookFlightIntent", "BookHotelIntent", "BookActivityIntent"]
  voice_id              = "Joanna"
  child_directed         = false
  abort_statement       = "I'm sorry, I didn't understand that. Can you please try again?"
  clarification_prompt = {
    messages = [
      {
        type = "PlainText"
        content = "I'm sorry, I didn't understand that. Can you please try again?"
      }
    ]
    max_attempts = 2
  }
  follow_up_prompt = {
    messages = [
      {
        type = "PlainText"
        content = "I'm sorry, I didn't understand that. Can you please try again?"
      }
    ]
    max_attempts = 2
  }
  output_contexts = [
    {
      name = "TravelContext"
      time_to_live = {
        seconds = 300
      }
      turns_to_live = 5
    }
  ]
  slot_types = [
    {
      name = "DestinationType"
      value_set = {
        values = [
          { name = "New York" },
          { name = "Los Angeles" },
          { name = "Chicago" }
        ]
      }
    },
    {
      name = "TravelDateType"
      value_set = {
        values = [
          { name = "2024-01-01" },
          { name = "2024-02-01" },
          { name = "2024-03-01" }
        ]
      }
    }
  ]
  intents = [
    {
      intent_name = "BookFlightIntent"
      sample_utterances = [
        "Book a flight to New York on January 1st.",
        "I want to book a flight to Los Angeles for February 1st."
      ]
      slots = [
        {
          name = "Destination"
          slot_type_name = "DestinationType"
          value_selection_strategy = "TOP_RESOLUTION"
        },
        {
          name = "TravelDate"
          slot_type_name = "TravelDateType"
          value_selection_strategy = "TOP_RESOLUTION"
        }
      ]
    },
    {
