      slots = [
        {
          name = "Destination"
          slot_type_name = "DestinationType"
          value_selection_strategy = "TOP_RESOLUTION"
        },
        {
          name = "TravelDate"
          slot_type_name = "TravelDateType"
          value_selection_strategy = "TOP_RESOLUTION"
        }
      ]
    },
    {
      intent_name = "BookActivityIntent"
      sample_utterances = [
        "Book a tour in New York for January 1st.",
        "I want to book a tour in Los Angeles for February 1st."
      ]
      slots = [
        {
          name = "Destination"
          slot_type_name = "DestinationType"
