  description = "A bot to order pizzas"

  intents = var.intent_names

  voice_id = "Joanna"  # You can choose any available voice ID

  child_directed = false
}

resource "aws_lex_intent" "place_order" {
  name        = "PlaceOrder"
  description = "Intent to place an order for a pizza"

  sample utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order a pizza please"
  ]

  slots = [
    {
      name          = "PizzaSize"
      slot_type_arn = aws_lex_slot_type.pizza_size.slot_type_arn
      value_selection_strategy = "TOP_RESOLUTION"
    }
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "cancel_order" {
  name        = "CancelOrder"
  description = "Intent to cancel an order for a pizza"

  sample utterances = [
    "I want to cancel my order",
    "Can I cancel my order?",
    "Cancel my order please"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "check_status" {
  name        = "CheckStatus"
  description = "Intent to check the status of an order for a pizza"

  sample utterances = [
    "What's the status of my order?",
    "Check the status of my order",
    "What's the status of my pizza order?"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "add_toppings" {
  name        = "AddToppings"
  description = "Intent to add toppings to an existing order for a pizza"

  sample utterances = [
    "Add toppings to my order",
    "Add toppings to my pizza",
    "Add more toppings to my order"
  ]

  slots = [
    {
      name          = "Topping"
      slot_type_arn = aws_lex_slot_type.topping.slot_type_arn
      value_selection_strategy = "TOP_RESOLUTION"
    }
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "remove_toppings" {
  name        = "RemoveToppings"
  description = "Intent to remove toppings from an existing order for a pizza"

  sample utterances = [
