    "Remove toppings from my pizza",
    "Remove some toppings from my order"
  ]

  slots = [
    {
      name          = "Topping"
      slot_type_arn = aws_lex_slot_type.topping.slot_type_arn
      value_selection_strategy = "TOP_RESOLUTION"
    }
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_slot_type" "pizza_size" {
