### Description:
This Terraform program creates an AWS Lex Bot named "PizzaOrderBot" that can handle user requests to order pizzas. It includes a Lambda function that processes the bot's responses and sends them back to the user.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# Define the IAM role for the Lambda function
resource "aws_iam_role" "lambda_execution_role" {
  name = "LambdaExecutionRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach necessary policies to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Define the Lambda function
resource "aws_lambda_function" "pizza_order_lambda" {
  filename      = "pizza_order_lambda.zip"  # Path to your Lambda function code
  function_name = "PizzaOrderLambda"
  handler       = "index.handler"
  runtime       = "python3.8"
  role           = aws_iam_role.lambda_execution_role.arn

  source_code_hash = filebase64sha256("pizza_order_lambda.zip")

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }
}

# Define the AWS Lex Bot
resource "aws_lex_bot" "pizza_order_bot" {
  name                = "PizzaOrderBot"
  description         = "A bot to order pizzas"
  intents             = ["PizzaOrderIntent"]
  voice_id            = "Joanna"
  child_directed      = false
  abort_statement     = "I'm sorry, I didn't understand that."
  clarification_prompt = {
    messages = [
      {
        type = "PlainText"
        content = "Could you please rephrase your request?"
      },
    ]
  }
  follow_up_prompt = {
    messages = [
      {
        type = "PlainText"
        content = "Would you like to place another order?"
      },
    ]
    max_retries = 2
  }
  output_contexts = [
    {
      name = "PizzaOrderContext"
      time_to_live = {
        minutes = 30
      }
      turns_to_live = 5
    },
  ]

  # Associate the Lambda function with the bot
  intents {
    intent_name = "PizzaOrderIntent"
    sample utterances = [
      "I want to order a pizza",
      "Can I order a pizza?",
      "Order a pizza for me",
    ]
    fulfillment_activity = {
      type = "Lambda"
      lambda_arn = aws_lambda_function.pizza_order_lambda.arn
    }
  }
}
```

