        }
      }
    ]
  })
}

# Define IAM role for the Lambda function
resource "aws_iam_role" "lambda_function_role" {
  name = "lambda-function-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the roles
resource "aws_iam_role_policy_attachment" "bot_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLexV2BotExecutionRolePolicy"
  role       = aws_iam_role.lex_bot_role.name
}

resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_function_role.name
}

# Define the Lex v2 bot
resource "aws_lexv2models_bot" "example_bot" {
  name             = "example-bot"
  description     = "Example Lex v2 bot"
  locale           = "en-US"
  child_directed   = false
  idle_session_ttl_seconds = 300

  intents = [
    {
      intent_name = "GreetingIntent"
      sample utterances = [
        "Hello",
        "Hi there",
        "What's up?"
      ]
    },
