### Description:
This Terraform program defines a basic Amazon Kinesis Analytics application that processes data from an existing Kinesis stream. The application uses a SQL query to transform the incoming data and outputs it to another Kinesis stream.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "kinesis_stream_name" {
  description = "The name of the Kinesis stream to read from"
  type        = string
  default     = "my-kinesis-stream"
}

variable "output_kinesis_stream_name" {
  description = "The name of the Kinesis stream to write to"
  type        = string
  default     = "my-output-stream"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy_attachment" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisAnalyticsServiceRole"
}

resource "aws_kinesis_analytics_application" "example" {
  name = "my-kinesis-analytics-app"

  inputs {
    name = "my-input-stream"

    schema {
      record_format {
        record_format_type = "JSON"
        json_schema = jsonencode({
          RecordColumns = [
            {
              Name = "column1"
              SqlType = "VARCHAR(255)"
            },
            {
              Name = "column2"
              SqlType = "VARCHAR(255)"
            }
          ]
        })
      }

      record_encoding = "UTF-8"
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.my_input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  outputs {
    name = "my-output-stream"

    schema {
      record_format {
        record_format_type = "JSON"
        json_schema = jsonencode({
          RecordColumns = [
            {
              Name = "transformed_column1"
              SqlType = "VARCHAR(255)"
            },
            {
              Name = "transformed_column2"
              SqlType = "VARCHAR(255)"
            }
          ]
        })
      }

      record_encoding = "UTF-8"
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.my_output_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  query_configuration {
    sql_query = "SELECT column1, column2 FROM 'my-input-stream' OUTPUT TO 'my-output-stream'"
  }
}

resource "aws_kinesis_stream" "my_input_stream" {
  name = var.kinesis_stream_name
  shard_count = 1
