              mapping = "$.column2"
              sql_type = "STRING"
            }
          ]
        })
      }
    }
  }

  outputs {
    name = "OutputName"

    destination_configuration {
      s3_destination_configuration {
        bucket_arn = aws_s3_bucket.kda_output_bucket.arn
        prefix     = "output/"
      }
    }
  }
}

# Create an S3 bucket for output
