### Description:
This Terraform program defines a Kinesis Firehose Delivery Stream that sends data to an S3 bucket with dynamic partitioning enabled. The delivery stream uses AWS Lambda functions for processing the data before it is written to S3. The program includes IAM roles and a default S3 bucket for storing the data.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Default S3 bucket for storing data
resource "aws_s3_bucket" "firehose_data" {
  bucket = "my-firehose-data-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# IAM role for Lambda function
resource "aws_iam_role" "firehose_lambda_role" {
  name = "firehose-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for Lambda function
resource "aws_iam_policy" "firehose_lambda_policy" {
  name = "firehose-lambda-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect = "Allow"
        Resource = aws_s3_bucket.firehose_data.arn
      }
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "firehose_lambda_policy_attachment" {
  role       = aws_iam_role.firehose_lambda_role.name
  policy_arn = aws_iam_policy.firehose_lambda_policy.arn
}

# Lambda function for processing data
resource "aws_lambda_function" "firehose_processor" {
  filename      = "firehose_processor.zip"
  function_name = "firehose-processor"
  role          = aws_iam_role.firehose_lambda_role.arn
  handler       = "index.handler"

  runtime = "nodejs14.x"

  source_code_hash = filebase64sha256("firehose_processor.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.firehose_data.bucket
    }
  }
}

# Kinesis Firehose Delivery Stream with dynamic partitioning
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name = "my-firehose-stream"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.firehose_data.arn
      role_arn   = aws_iam_role.firehose_lambda_role.arn

      prefix = "${aws_lambda_function.firehose_processor.function_name}/"

      dynamic "processing_configuration" {
        for_each = var.processing_configurations

        content {
          enabled = processing_configuration.enabled

          processor {
            type     = processing_configuration.type
            parameters {
              parameter_name = processing_configuration.parameter_name
              parameter_value = processing_configuration.parameter_value
            }
          }
        }
      }

      dynamic "extended_s3_configuration" {
        for_each = var.extended_s3_configurations

        bucket_arn = extended_s3_configuration.bucket_arn
        role_arn   = extended_s3_configuration.role_arn

        prefix = extended_s3_configuration.prefix

        dynamic "dynamic_partitioning_configuration" {
          for_each = extended_s3_configuration.dynamic_partitioning_configurations

          enabled = dynamic_partitioning_configuration.enabled

          record_writer_type = dynamic_partitioning_configuration.record_writer_type
        }
      }
    }
  }
}

variable "processing_configurations" {
  type = list(object({
    enabled     = bool
    type         = string
    parameter_name = string
    parameter_value = string
  }))
  default = []
}

variable "extended_s3_configurations" {
  type = list(object({
    bucket_arn = string
    role_arn   = string
    prefix     = string

    dynamic_partitioning_configurations = list(object({
      enabled                 = bool
      record_writer_type       = string
    }))
  }))
  default = []
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **S3 Bucket**: A default S3 bucket named `my-firehose-data-bucket` is created with versioning enabled.
- **IAM Roles**: Two IAM roles are defined: one for the Lambda function (`firehose_lambda_role`) and another for the Kinesis Firehose delivery stream (`firehose_delivery_stream_role`).
- **Lambda Function**: A Node.js Lambda function named `firehose-processor` is created to process the data before writing it to S3. It uses the IAM role `firehose_lambda_role`.
- **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream named `my-firehose-stream` is created with an S3 destination. The S3 destination uses the IAM role `firehose_delivery_stream_role`. Dynamic partitioning is enabled using the `extended_s3_configuration` block.
- **Variables**: Variables `processing_configurations` and `extended_s3_configurations` allow for dynamic configuration of additional processing steps and S3 configurations, respectively. They have default values that can be overridden when applying the Terraform configuration.

