resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "firehose_delivery_stream_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# Create an S3 bucket
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.s3_bucket_name

  versioning {
    enabled = true
  }

  lifecycle_rule {
    id      = "delete-old-objects"
    prefix  = ""
    status = "Enabled"

    expiration {
      days = 30
    }
  }
}

# Create a Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name = "my-firehose-stream"

  destination {
    elasticsearch {
      domain_arn = var.elasticsearch_domain_arn
      index_name = "my-index"
      role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    }
  }

  buffering_options {
    interval_length_in_seconds = 60
    size_in_megabytes         = 5
  }

  compression_format = "GZIP"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Two variables are defined: `elasticsearch_domain_arn` and `s3_bucket_name`. These are used to specify the Elasticsearch domain ARN and the S3 bucket name, respectively.
- **IAM Role**: An IAM role named `firehose_delivery_stream_role` is created with permissions to assume the role required by the Firehose delivery stream.
- **S3 Bucket**: An S3 bucket is created with versioning enabled and a lifecycle rule to delete old objects after 30 days.
- **Kinesis Firehose Delivery Stream**: A Firehose delivery stream is created with an Elasticsearch destination. The stream uses GZIP compression and buffers data for 60 seconds with a buffer size of 5 MB.

