### Description:
This Terraform program defines a Kinesis Firehose Delivery Stream that sends data to a Splunk destination. The delivery stream will use AWS Lambda functions for processing the data before it is sent to Splunk. The program includes IAM roles and permissions necessary for both the Lambda function and the Firehose delivery stream.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lambda Function
resource "aws_iam_role" "lambda_firehose_processor" {
  name = "lambda_firehose_processor"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Function
resource "aws_iam_policy" "lambda_firehose_processor_policy" {
  name = "lambda_firehose_processor_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "lambda_firehose_processor_policy_attachment" {
  role       = aws_iam_role.lambda_firehose_processor.name
  policy_arn = aws_iam_policy.lambda_firehose_processor_policy.arn
}

# Lambda Function for Processing Data
resource "aws_lambda_function" "firehose_processor" {
  filename      = "lambda_function_payload.zip"
  function_name = "firehose_processor"
  role          = aws_iam_role.lambda_firehose_processor.arn
  handler       = "index.handler"

  runtime = "python3.8"

  source_code_hash = filebase64sha256("lambda_function_payload.zip")

  environment = {
    variables = {
      SPLUNK_HOST = "your_splunk_host"
      SPLUNK_PORT = "your_splunk_port"
      SPLUNK_TOKEN = "your_splunk_token"
    }
  }
}

# Lambda Permission for Firehose Delivery Stream
resource "aws_lambda_permission" "firehose_processor_permission" {
  statement_id   = "AllowFirehoseToInvokeFunction"
  action         = "lambda:InvokeFunction"
  function_name = aws_lambda_function.firehose_processor.function_name
  principal     = "firehose.amazonaws.com"
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name = "example-firehose-stream"

  destination {
    splunk {
      endpoint_url = "https://${aws_s3_bucket.splunk_logs.bucket}.s3.amazonaws.com"
      region       = "us-west-2"
      access_key    = aws_s3_bucket.splunk_logs.bucket_owner_access_key
      secret_key   = aws_s3_bucket.splunk_logs.bucket_owner_secret_key
      log_format    = "json"
      log_prefix    = "firehose/"
      index_name    = "your_splunk_index"
      sourcetype    = "your_sourcetype"
    }
  }

  processing_configuration {
    enabled = true

    processor {
      type           = "Lambda"
      parameters {
        parameter_name = "LambdaArn"
        parameter_value = aws_lambda_function.firehose_processor.arn
      }
    }
  }
}

# S3 Bucket for Splunk Logs
resource "aws_s3_bucket" "splunk_logs" {
  bucket = "your-splunk-logs-bucket"

  acl = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **IAM Roles and Policies**: Two IAM roles are created: one for the Lambda function (`lambda_firehose_processor`) and another for the Firehose delivery stream (`lambda_firehose_processor_policy`). The policies allow the Lambda function to write to Kinesis Firehose and to write logs to CloudWatch.
- **Lambda Function**: A Python Lambda function named `firehose_processor` is defined. It processes incoming data and sends it to Splunk using the provided credentials.
- **Lambda Permission**: A permission is attached to the Lambda function to allow the Firehose delivery stream to invoke it.
- **Kinesis Firehose Delivery Stream**: The delivery stream is configured to send data to a Splunk endpoint. It uses a Lambda function for processing the data before sending it to Splunk.
- **S3 Bucket**: An S3 bucket is created to store the logs from the Firehose delivery stream. The bucket is configured with server-side encryption to protect the logs.

Make sure to replace placeholders like `your_splunk_host`, `your_splunk_port`, `your_splunk_token`, `your_splunk_index`, `your_sourcetype`, and `your-splunk-logs-bucket` with your actual Splunk and S3 configurations.

