          "es:*",
          "logs:GetLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "firehose_elasticsearch_policy_attachment" {
  role       = aws_iam_role.firehose_elasticsearch_role.name
  policy_arn = aws_iam_policy.firehose_elasticsearch_policy.arn
}

# VPC Configuration
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example-vpc"
  }
}

# Subnet Configuration
resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "example-subnet"
  }
}

# Security Group Configuration
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow inbound traffic on port 443"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-sg"
  }
}

# Elasticsearch Domain Configuration
resource "aws_elasticsearch_domain" "example" {
  domain_name = "example-domain"

  elasticsearch_version = "7.10"

  cluster_config {
    instance_type = "t2.micro.elasticsearch"
    instance_count = 1
  }

  vpc_options {
    subnet_ids = [aws_subnet.example.id]
    security_group_ids = [aws_security_group.example.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  tags = {
    Name = "example-domain"
  }
}

# Elasticsearch Endpoint
data "aws_elasticsearch_domain_endpoint" "example" {
  domain_name = aws_elasticsearch_domain.example.domain_name
}

# Kinesis Firehose Delivery Stream Configuration
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name = "example-firehose-stream"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.example.arn
      role_arn   = aws_iam_role.firehose_elasticsearch_role.arn
    }
  }

  delivery_stream_encryption_configuration {
    kms_encryption_configuration {
      key_arn = aws_kms_key.example.arn
    }
  }

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.example.arn
    role_arn   = aws_iam_role.firehose_elasticsearch_role.arn
  }

  tags = {
    Name = "example-firehose-stream"
  }
}

# S3 Bucket Configuration
resource "aws_s3_bucket" "example" {
  bucket = "example-bucket"

  tags = {
    Name = "example-bucket"
  }
}

# KMS Key Configuration
resource "aws_kms_key" "example" {
  description = "Example KMS Key"

  tags = {
    Name = "example-kms-key"
  }
}
```

### Explanation:
- **Provider Configuration**: Sets the AWS region to `us-west-2`.
- **IAM Roles**: Creates an IAM role (`firehose_elasticsearch_role`) and policy (`firehose_elasticsearch_policy`) for Firehose to access Elasticsearch.
- **VPC Configuration**: Defines a VPC, subnet, and security group.
- **Elasticsearch Domain**: Configures an Elasticsearch domain within the VPC.
- **Kinesis Firehose Delivery Stream**: Sets up a delivery stream that sends data to an S3 bucket and then to Elasticsearch.
- **S3 Bucket and KMS Key**: Provides storage for the data and encryption for the data in transit.

This configuration ensures that the data is securely transferred between Kinesis Firehose, S3, and Elasticsearch, leveraging the power of AWS services.

