### Description:
This Terraform program defines a Kinesis Firehose Delivery Stream that sends data to a specified HTTP endpoint, such as New Relic. The program includes IAM roles for the Firehose delivery stream and the Lambda function that processes the data before sending it to the HTTP endpoint. It also sets up a VPC and subnets for the Lambda function to ensure it has access to the internet.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for the Firehose Delivery Stream
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for the Lambda Function
resource "aws_iam_role" "lambda_function_role" {
  name = "lambda_function_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Lambda Function to process data
resource "aws_lambda_function" "process_data" {
  filename      = "process_data.zip"
  function_name = "process_data"
  role          = aws_iam_role.lambda_function_role.arn
  handler       = "index.handler"

  runtime = "nodejs14.x"

  source_code_hash = filebase64sha256("process_data.zip")

  environment = {
    variables = {
      NEW_RELIC_LICENSE_KEY = var.new_relic_license_key
    }
  }

  timeout = 30

  vpc_config = {
    subnet_ids = [aws_subnet.subnet.id]
    security_group_ids = [aws_security_group.lambda_sg.id]
  }
}

# Lambda Function Code (process_data.zip)
resource "local_file" "process_data_zip" {
  content_base64 = base64encode(file("process_data.zip"))
  filename      = "process_data.zip"
}

# Lambda Function Handler (index.js)
resource "local_file" "process_data_handler" {
  content = <<EOF
const newrelic = require('newrelic');

exports.handler = async (event) => {
  const records = event.Records;
  for (let record of records) {
    const payload = JSON.parse(record.kinesis.data);
    // Process the payload here
    console.log(payload);
    newrelic.noticeError(new Error(`Processing error for ${payload.id}`));
  }
};
EOF
  filename = "index.js"
}

# Security Group for Lambda Function
resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Subnet for Lambda Function
resource "aws_subnet" "subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id      = aws_vpc.vpc.id
  availability_zone = "us-east-1a"
}

# VPC for Lambda Function
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name = "firehose_stream"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.firehose_bucket.arn
      role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    }
  }

  processing_configuration {
    enabled = true
    processors {
      type = "Lambda"
      parameters {
        parameter_name  = "LambdaArn"
        parameter_value = aws_lambda_function.process_data.arn
      }
    }
  }
}

# S3 Bucket for Firehose Delivery Stream
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "firehose-bucket-${var.environment}"
  acl    = "private"
}
```

### Variables:
- `new_relic_license_key`: The New Relic license key for the Lambda function to use.
- `environment`: The environment name for the S3 bucket, e.g., `dev`, `staging`, `prod`.

### Notes:
- Ensure that the `process_data.zip` file contains the `index.js` file and any other necessary dependencies.
- Replace `"process_data.zip"` with the actual path to your Lambda function code.
- Adjust the `availability_zone` and `cidr_block` as needed for your specific use case.

