### Description:
This Terraform program creates a Kinesis Firehose Delivery Stream that sends data to an Amazon OpenSearch Service (ES) cluster. The delivery stream is configured to use a VPC for enhanced security and network isolation.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

variable "es_domain_name" {
  description = "The name of the OpenSearch domain"
  default     = "my-opensearch-domain"
}

variable "es_cluster_endpoint" {
  description = "The endpoint of the OpenSearch cluster"
  default     = "https://my-opensearch-domain.us-west-2.es.amazonaws.com"
}

variable "es_access_key_id" {
  description = "The AWS access key ID for the OpenSearch domain"
  default     = ""
}

variable "es_secret_access_key" {
  description = "The AWS secret access key for the OpenSearch domain"
  default     = ""
}

variable "vpc_id" {
  description = "The ID of the VPC where the delivery stream will be deployed"
  default     = ""
}

variable "subnet_ids" {
  description = "A list of subnet IDs within the VPC"
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "A list of security group IDs associated with the VPC"
  type        = list(string)
  default     = []
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name = "my-firehose-stream"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.firehose_bucket.arn
      role_arn   = aws_iam_role.firehose_role.arn
    }
  }

  tags = {
    Name = "MyFirehoseStream"
  }
}

resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "my-firehose-bucket"

  tags = {
    Name = "MyFirehoseBucket"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "main" {
  count = length(var.subnet_ids)

  vpc_id     = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "MySubnet${count.index + 1}"
  }
}

resource "aws_security_group" "main" {
  name        = "MySecurityGroup"
  description = "Security group for the delivery stream"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "MySecurityGroup"
  }
}

resource "aws_security_group_rule" "ingress_firehose" {
  security_group_id = aws_security_group.main.id
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.es_cluster_endpoint]
}

resource "aws_security_group_rule" "egress_firehose" {
  security_group_id = aws_security_group.main.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.es_cluster_endpoint]
}

resource "aws_opensearch_domain" "main" {
  domain_name = var.es_domain_name

  cluster_config {
    instance_type = "t2.micro.elasticsearch"
    instance_count = 1
  }

  vpc_options {
    subnet_ids = var.subnet_ids
    security_group_ids = var.security_group_ids
  }

  engine_version = "OpenSearch_1.3"

  tags = {
    Name = "MyOpenSearchDomain"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Variables are defined for the OpenSearch domain name, endpoint, access keys, VPC details, and security group IDs.
- **IAM Role**: An IAM role is created for the Firehose delivery stream to assume.
- **Firehose Delivery Stream**: A Kinesis Firehose delivery stream is set up to send data to an S3 bucket. The S3 bucket is also configured with the same IAM role.
- **S3 Bucket**: An S3 bucket is created to store the data before it is sent to OpenSearch.
- **VPC and Subnets**: A VPC and subnets are created to isolate the delivery stream within a secure environment.
- **Security Groups**: Security groups are created to allow traffic between the delivery stream and the OpenSearch domain.
- **OpenSearch Domain**: An OpenSearch domain is created with the specified configuration, including VPC options and security group IDs.

This configuration ensures that the delivery stream is securely deployed within a VPC and can communicate with the OpenSearch domain.

