variable "kinesis_video_stream_name" {
  description = "Name of the Kinesis Video Stream"
  default     = "my-kinesis-video-stream"
}

variable "encryption_key_arn" {
  description = "ARN of the KMS key for encryption"
  default     = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"
}

resource "aws_kinesis_video_stream" "example" {
  name           = var.kinesis_video_stream_name
  encryption_type = "KMS"
  kms_key_arn    = var.encryption_key_arn
  retention_period_hours = 24

  tags = {
    Name = var.kinesis_video_stream_name
  }
}

resource "aws_iam_role" "kinesis_video_stream_role" {
  name = "${var.kinesis_video_stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisvideo.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_video_stream_policy_attachment" {
  role       = aws_iam_role.kinesis_video_stream_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSKinesisVideoStreamAccess"
}

resource "aws_lambda_function" "process_video" {
  filename      = "process_video.zip"
  function_name = "process_video_function"
  handler       = "index.handler"
  runtime       = "python3.8"

  role = aws_iam_role.kinesis_video_stream_role.arn

  environment = {
    variables = {
      KINESIS_VIDEO_STREAM_NAME = var.kinesis_video_stream_name
    }
  }

  source_code_hash = filebase64sha256("process_video.zip")
}

resource "aws_lambda_permission" "allow_kinesis_video_stream" {
  statement_id  = "AllowExecutionFromKinesisVideoStream"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.process_video.function_name
  principal     = "kinesisvideo.amazonaws.com"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Two variables are defined: `kinesis_video_stream_name` and `encryption_key_arn`. Default values are provided for these variables.
- **Kinesis Video Stream**: A `aws_kinesis_video_stream` resource is created with the specified name, encryption type, KMS key ARN, and retention period.
- **IAM Roles**: Two IAM roles are created: one for the Kinesis Video Stream (`kinesis_video_stream_role`) and another for the Lambda function (`process_video_function`). The Lambda function assumes the role of the Kinesis Video Stream.
- **Lambda Function**: A `aws_lambda_function` resource is defined to process the video data. It uses the Kinesis Video Stream name as an environment variable.
- **Lambda Permission**: A `aws_lambda_permission` resource allows the Kinesis Video Stream to invoke the Lambda function.

This configuration ensures that the Kinesis Video Stream is properly set up with encryption and a Lambda function to process the video data.

