### Description:
This Terraform program defines a Kinesis Firehose Delivery Stream that sends data to an S3 bucket. The delivery stream includes additional configurations such as buffering, compression, and retry settings. It also sets up IAM roles for the necessary AWS services.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket where data will be stored."
  default     = "my-kinesis-firehose-bucket"
}

variable "firehose_buffering_interval" {
  description = "The interval in seconds between buffer flushes."
  default     = 60
}

variable "firehose_buffering_size" {
  description = "The size of the buffer in MB before it is flushed."
  default     = 5
}

variable "firehose_compression_format" {
  description = "The compression format for the data."
  default     = "GZIP"
}

variable "firehose_retry_attempts" {
  description = "The number of times to retry failed records."
  default     = 3
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_delivery_stream_policy_attachment" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
}

resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_kinesis_firehose_delivery_stream" "example" {
  name = "my-kinesis-firehose-stream"

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.firehose_bucket.arn
      role_arn   = aws_iam_role.firehose_delivery_stream_role.arn

      buffering_configuration {
        interval_in_seconds = var.firehose_buffering_interval
        size_in_megabytes   = var.firehose_buffering_size
      }

      compression_format = var.firehose_compression_format

      retry_options {
        duration_in_seconds = var.firehose_retry_attempts
      }
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Several variables are defined to allow customization of the S3 bucket name, buffering settings, compression format, and retry attempts.
- **IAM Role**: An IAM role named `firehose_delivery_stream_role` is created with permissions to assume the `AWSFirehoseDeliveryServiceRolePolicy`.
- **S3 Bucket**: An S3 bucket is created with the specified name and ACL.
- **Kinesis Firehose Delivery Stream**: A delivery stream is created with an S3 destination. The destination configuration includes buffering, compression, and retry options based on the provided variables.

