### Description:
This Terraform program defines a basic Amazon Kinesis Analytics application along with a CloudWatch log stream. The application processes data from a Kinesis Data Stream and writes logs to a CloudWatch log group. The configuration includes IAM roles for the Kinesis Analytics application and CloudWatch log stream, as well as default values for variables.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "kinesis_stream_name" {
  description = "The name of the Kinesis Data Stream"
  default     = "my-kinesis-stream"
}

variable "log_group_name" {
  description = "The name of the CloudWatch Log Group"
  default     = "my-kinesis-analytics-log-group"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy_attachment" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisAnalyticsServiceRole"
}

resource "aws_kinesis_analytics_application" "example" {
  name = "my-kinesis-analytics-app"

  inputs {
    name             = "InputName"
    input_schema {
      record_format {
        record_format_type = "JSON"
        json_serde {
          type = "SimpleJsonSerde"
        }
      }
      record_column {
        name = "column1"
        mapping = "$.column1"
        sql_type = "VARCHAR(256)"
      }
      record_column {
        name = "column2"
        mapping = "$.column2"
        sql_type = "VARCHAR(256)"
      }
    }
    kinesis_stream {
      resource_arn = aws_kinesis_stream.example.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  output_logs {
    destination = "CloudWatchLogs"
    log_group_name = aws_cloudwatch_log_group.example.name
    log_stream_name = aws_cloudwatch_log_stream.example.name
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = var.log_group_name
}

resource "aws_cloudwatch_log_stream" "example" {
  name   = var.log_group_name
  group  = aws_cloudwatch_log_group.example.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **Variables**: Two variables are defined: `kinesis_stream_name` and `log_group_name`, with default values.
