### Description:
This Terraform program configures an Active-Passive failover policy using AWS Route 53. It sets up a primary and secondary DNS record for a given FQDN, with a health check to determine which record should be used. The program includes IAM roles for necessary permissions and uses default values where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Route 53
resource "aws_iam_role" "route53_role" {
  name = "route53_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Route 53
resource "aws_iam_policy" "route53_policy" {
  name = "route53_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "route53:GetHealthCheck",
          "route53:ListHealthChecks",
          "route53:UpdateHealthCheck",
          "route53:CreateHealthCheck",
          "route53:DeleteHealthCheck"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "route53_policy_attachment" {
  role       = aws_iam_role.route53_role.name
  policy_arn = aws_iam_policy.route53_policy.arn
}

# Primary Health Check
resource "aws_route53_health_check" "primary_health_check" {
  name                  = "primary_health_check"
  type                  = "HTTP"
  port                  = 80
  resource_path         = "/"
  request_interval     = 30
  failure_threshold   = 3
  healthy_threshold   = 2
  unhealthy_threshold = 2

  tags = {
    Name = "Primary Health Check"
  }
}

# Primary DNS Record
resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.primary.id
  name     = "example.com"
  type     = "A"
  ttl      = 60

  alias {
    evaluate_target_health = true
    name                  = aws_route53_record.secondary_record.fqdn
    zone_id               = aws_route53_zone.secondary.id
    evaluate_target_health = true
  }

  depends_on = [aws_route53_health_check.primary_health_check]
}

# Secondary DNS Record
resource "aws_route53_record" "secondary_record" {
  zone_id = aws_route53_zone.primary.id
  name     = "example.com"
  type     = "A"
  ttl      = 60

  target_resource {
    value = "192.168.1.100"
  }

  depends_on = [aws_route53_health_check.primary_health_check]
}

# Route 53 Zone
resource "aws_route53_zone" "primary" {
  name = "example.com"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **IAM Roles**: Two IAM roles are created: one for the Route 53 service (`route53_role`) and another for managing the health check (`route53_policy`). Both roles have the necessary permissions to interact with Route 53.
- **Health Check**: A basic HTTP health check is set up to monitor the primary DNS record.
- **DNS Records**: Two DNS records are created: one for the primary and one for the secondary. The primary record uses an alias to point to the secondary record, and the secondary record points to a static IP address.
- **Tags**: Tags are added to the health check and DNS records for easier management.

This configuration ensures that the DNS system is set up to handle failover scenarios effectively.

