### Description:
This Terraform program creates a custom Virtual Private Cloud (VPC) with a CIDR block of `10.0.0.0/16`. It then sets up two subnets in the `us-east-1a` and `us-east-1b` availability zones. Each subnet is associated with a route table that allows internet access. Finally, it provisions an EC2 instance in each subnet using the latest Amazon Linux 2 AMI, with a `t2.micro` instance type and an attached EBS volume of 50 GB.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC with CIDR block 10.0.0.0/16
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Create subnets in us-east-1a and us-east-1b
resource "aws_subnet" "subnet_a" {
  vpc_id     = aws_vpc.example_vpc.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id     = aws_vpc.example_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1b"
}

# Create a route table for the VPC
resource "aws_route_table" "example_route_table" {
  vpc_id = aws_vpc.example_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.example_internet_gateway.id
  }
}

# Associate the route table with the subnets
resource "aws_route_table_association" "subnet_a_association" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.example_route_table.id
}

resource "aws_route_table_association" "subnet_b_association" {
  subnet_id      = aws_subnet.subnet_b.id
  route_table_id = aws_route_table.example_route_table.id
}

# Create an Internet Gateway
resource "aws_internet_gateway" "example_internet_gateway" {
  vpc_id = aws_vpc.example_vpc.id
}

# Create an EBS volume
resource "aws_ebs_volume" "example_volume" {
  size           = 50
  availability_zone = aws_subnet.subnet_a.availability_zone
}

# Attach the EBS volume to an EC2 instance in subnet A
resource "aws_instance" "example_instance_a" {
  ami           = "ami-0c55b159cbfafe1f0" # Latest Amazon Linux 2 AMI
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_a.id
  key_name       = "your_key_pair_name" # Replace with your key pair name

  root_block_device {
    volume_size = 50
    volume_type = "gp2"
  }

  ebs_block_device {
    device_name = "/dev/sdb"
    volume_size = 50
    volume_type = "gp2"
    ephemeral = false
  }
}

# Attach the EBS volume to an EC2 instance in subnet B
resource "aws_instance" "example_instance_b" {
  ami           = "ami-0c55b159cbfafe1f0" # Latest Amazon Linux 2 AMI
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_b.id
  key_name       = "your_key_pair_name" # Replace with your key pair name

  root_block_device {
    volume_size = 50
    volume_type = "gp2"
  }

  ebs_block_device {
    device_name = "/dev/sdb"
    volume_size = 50
    volume_type = "gp2"
    ephemeral = false
  }
}
```

### Notes:
- Replace `"your_key_pair_name"` with the name of your existing EC2 key pair.
- Ensure that the AWS provider version is set to `~> 5.75` and Terraform version is set to `~> 1.9.8`.
- This configuration assumes that you have an existing key pair named `"your_key_pair_name"` in your AWS account. If not, you will need to create one before running this Terraform script.

