### Description:
This Terraform program creates a VPC with a public and private subnet. It also sets up an EC2 Fleet using Launch Templates to deploy a combination of 5 On-Demand and 4 Spot Instances on the newest AWS Linux 2 AMI. The configuration ensures consistency in instance configurations across both On-Demand and Spot instances.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create a VPC with a public and private subnet
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "ExampleVPC"
  }
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.2.0/24"

  tags = {
    Name = "PrivateSubnet"
  }
}

# Create an Internet Gateway and attach it to the VPC
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id

  tags = {
    Name = "ExampleInternetGateway"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.example.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.example.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Create a NAT Gateway in the public subnet
resource "aws_nat_gateway" "example" {
  subnet_id = aws_subnet.public.id

  tags = {
    Name = "ExampleNATGateway"
  }
}

# Create a security group for the EC2 instances
resource "aws_security_group" "example" {
  name        = "ExampleSecurityGroup"
  description = "Allow SSH and HTTP access"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ExampleSecurityGroup"
  }
}

# Create a Launch Template for On-Demand Instances
resource "aws_launch_template" "ondemand" {
  name_prefix = "OnDemandInstance"
  image_id     = "ami-0c55b159cbfafe1f0"  # Latest AWS Linux 2 AMI
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"  # Replace with your key pair name
  security_groups = [aws_security_group.example.id]

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y httpd
    sudo systemctl start httpd
    sudo systemctl enable httpd
  EOF

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_size = 8
      volume_type = "gp2"
    }
  }
}

# Create a Launch Template for Spot Instances
resource "aws_launch_template" "spot" {
  name_prefix = "SpotInstance"
  image_id     = "ami-0c55b159cbfafe1f0"  # Latest AWS Linux 2 AMI
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"  # Replace with your key pair name
  security_groups = [aws_security_group.example.id]

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y httpd
    sudo systemctl start httpd
    sudo systemctl enable httpd
  EOF

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_size = 8
      volume_type = "gp2"
    }
  }

  spot_price = "0.01"  # Adjust the spot price as needed
}

# Create an EC2 Fleet with a combination of On-Demand and Spot Instances
resource "aws_ec2_fleet" "example" {
  launch_template_configs {
    launch_template_specification {
      launch_template_id = aws_launch_template.ondemand.id
      version           = aws_launch_template.ondemand.latest_version
    }

    target_capacity_specification {
      total_target_capacity = 5
      on_demand_target_capacity = 5
    }
  }

  launch_template_configs {
    launch_template_specification {
      launch_template_id = aws_launch_template.spot.id
      version           = aws_launch_template.spot.latest_version
    }

    target_capacity_specification {
      total_target_capacity = 4
      spot_target_capacity = 4
    }
  }

  allocation_strategy = "lowest-price"

  iam_fleet_role = aws_iam_role.ec2_fleet_role.arn

  tags = {
    Name = "ExampleEC2Fleet"
  }
}

# Create an IAM Role for the EC2 Fleet
resource "aws_iam_role" "ec2_fleet_role" {
  name = "ExampleEC2FleetRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Instance Profile for the EC2 Fleet
resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ExampleEC2FleetInstanceProfile"
  role = aws_iam_role.ec2_fleet_role.name
}

# Attach the IAM Instance Profile to the EC2 Fleet
