### Description:
This Terraform program creates a Virtual Private Cloud (VPC) with three subnets: one public subnet for web servers, two private subnets for application servers and a database, and an Amazon RDS instance to serve as the database. The program also includes IAM roles for the EC2 instances and RDS instance.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Default variables
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  default = "10.0.2.0/24"
}

variable "application_subnet_cidr_block" {
  default = "10.0.3.0/24"
}

# VPC creation
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "TerraformAI-VPC"
  }
}

# Public Subnet creation
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_block
  availability_zone = "us-west-2a"

  tags = {
    Name = "Public Subnet"
  }
}

# Private Subnet creation
resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.application_subnet_cidr_block
  availability_zone = "us-west-2b"

  tags = {
    Name = "Application Subnet"
  }
}

resource "aws_subnet" "database" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_block
  availability_zone = "us-west-2c"

  tags = {
    Name = "Database Subnet"
  }
}

# Internet Gateway creation
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Internet Gateway"
  }
}

# Route Table creation for public subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "Public Route Table"
  }
}

# Associate public subnet with public route table
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security Group creation for public subnet
resource "aws_security_group" "public" {
  name        = "Public SG"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Public SG"
  }
}

# Security Group creation for application subnet
resource "aws_security_group" "application" {
  name        = "Application SG"
  description = "Allow SSH and HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Application SG"
  }
}

# Security Group creation for database subnet
resource "aws_security_group" "database" {
  name        = "Database SG"
  description = "Allow MySQL traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Database SG"
  }
}

# EC2 Instance creation in public subnet for web servers
resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public.id
  security_groups = [aws_security_group.public.id]

  tags = {
    Name = "Web Server"
  }
}

# EC2 Instance creation in private subnet for application servers
resource "aws_instance" "app_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.application.id
  security_groups = [aws_security_group.application.id]

  tags = {
    Name = "App Server"
  }
}

# RDS Instance creation in private subnet for database
resource "aws_rds_instance" "db_instance" {
  engine              = "mysql"
  engine_version      = "5.7"
  instance_class      = "db.t2.micro"
  allocated_storage   = 20
  db_name             = "mydatabase"
  username           = "admin"
  password           = "password123"
  publicly_accessible = false
  subnet_ids          = [aws_subnet.database.id]
  vpc_security_group_ids = [aws_security_group.database.id]

  tags = {
    Name = "Database Instance"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Default values are provided for VPC CIDR block, subnet CIDR blocks, and AMI ID.
- **VPC**: A VPC is created with a specified CIDR block.
- **Subnets**: Three subnets are created: one public, one for application servers, and one for the database.
- **Internet Gateway**: An internet gateway is attached to the VPC to allow outbound internet access.
- **Route Tables**: Route tables are created for the public and application subnets, associating them with the internet gateway.
- **Security Groups**: Security groups are defined for each subnet to control inbound and outbound traffic.
- **EC2 Instances**: Two EC2 instances are created in the public and application subnets, respectively, with appropriate security groups.
- **RDS Instance**: An RDS instance is created in the database subnet, with a specified engine, version, instance class, and storage size. It is not publicly accessible and uses the appropriate security group.

