### Description:
This Terraform program creates a Virtual Private Cloud (VPC) with two private subnets. It also sets up two new AWS Linux 2 EC2 instances in these private subnets, mounting an Amazon Elastic File System (EFS) file system for shared storage.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "private_subnet_cidr_blocks" {
  default = [
    "10.0.1.0/24",
    "10.0.2.0/24"
  ]
}

variable "instance_type" {
  default = "t2.micro"
}

variable "ami_id" {
  default = "ami-0c55b159cbfafe1f0"  # Latest AWS Linux 2 AMI ID
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "TerraformVPC"
  }
}

resource "aws_subnet" "private" {
  count          = length(var.private_subnet_cidr_blocks)
  cidr_block     = var.private_subnet_cidr_blocks[count.index]
  vpc_id         = aws_vpc.main.id
  availability_zone = "us-west-2a"  # Adjust based on your availability zones

  tags = {
    Name = "PrivateSubnet${count.index + 1}"
  }
}

resource "aws_efs_file_system" "main" {
  tags = {
    Name = "TerraformEFS"
  }
}

resource "aws_efs_mount_target" "private" {
  count          = length(aws_subnet.private)
  file_system_id = aws_efs_file_system.main.id
  subnet_id      = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.main.id]

  tags = {
    Name = "EFSMountTarget${count.index + 1}"
  }
}

resource "aws_security_group" "main" {
  name        = "TerraformSecurityGroup"
  description = "Allow SSH and HTTP access"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "TerraformSecurityGroup"
  }
}

resource "aws_instance" "web_server" {
  count          = 2
  ami             = var.ami_id
  instance_type = var.instance_type
  key_name        = "your-key-pair-name"  # Replace with your key pair name
  vpc_security_group_ids = [aws_security_group.main.id]
  subnet_id       = aws_subnet.private[count.index].id

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y httpd
    sudo systemctl start httpd
    sudo systemctl enable httpd
    sudo echo "<html><body><h1>Welcome to Terraform</h1></body></html>" > /var/www/html/index.html
    EOF

  root_block_device {
    volume_size = 8
    volume_type = "gp2"
  }

  ebs_block_device {
    device_name = "/dev/sdb"
    volume_size = 10
    volume_type = "gp2"
    encrypted = true
  }

  mount_point {
    device_name = "/mnt/efs"
    efs_id      = aws_efs_file_system.main.id
    nfs_mount_options = {
      nfsvers = "4.1"
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Variables are defined for the VPC CIDR block, private subnet CIDR blocks, instance type, and AMI ID. Default values are provided.
- **VPC**: A VPC is created with a specified CIDR block.
- **Subnets**: Two private subnets are created within the VPC, each in a different availability zone.
- **EFS**: An EFS file system is created for shared storage.
- **Security Group**: A security group allows SSH and HTTP access.
- **EC2 Instances**: Two AWS Linux 2 EC2 instances are created in the private subnets. Each instance mounts the EFS file system and runs a simple web server to demonstrate shared storage.

Make sure to replace `"your-key-pair-name"` with the actual name of your AWS key pair. This configuration is designed to be deployed with Terraform version ~> 1.9.8 and hashicorp/aws ~> 5.75.

