### Description:
This Terraform program creates an ElastiCache Redis user with specific permissions. It includes a provider configuration for AWS, IAM roles for access control, and a user resource with necessary permissions.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for ElastiCache User
resource "aws_iam_role" "elasticache_user_role" {
  name = "elasticache_user_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for ElastiCache User
resource "aws_iam_policy" "elasticache_user_policy" {
  name = "elasticache_user_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:DescribeCacheClusters",
          "elasticache:DescribeCacheParameterGroups",
          "elasticache:DescribeCacheParameters",
          "elasticache:DescribeCacheSecurityGroups",
          "elasticache:DescribeEngineDefaultParameters",
          "elasticache:DescribeEvents",
          "elasticache:DescribeReplicationGroups",
          "elasticache:DescribeReservedCacheNodes",
          "elasticache:DescribeSnapshots",
          "elasticache:ModifyCacheCluster",
          "elasticache:ModifyCacheParameterGroup",
          "elasticache:ModifyCacheSecurityGroup",
          "elasticache:ModifyReplicationGroup",
          "elasticache:RebootCacheCluster",
          "elasticache:ResetCacheParameterGroup",
          "elasticache:RestoreFromSnapshot",
          "elasticache:TagResource",
          "elasticache:UntagResource"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "elasticache_user_policy_attachment" {
  role       = aws_iam_role.elasticache_user_role.name
  policy_arn = aws_iam_policy.elasticache_user_policy.arn
}

# ElastiCache User
resource "aws_elasticache_user" "elasticache_user" {
  user_name = "my_redis_user"

  authentication_mode {
    type = "password"
    passwords = ["MySecurePassword123"]
  }

  engine = "redis"

  user_group_ids = ["default"]

  tags = {
    Name = "MyElastiCacheUser"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **IAM Role**: An IAM role named `elasticache_user_role` is created with permissions to interact with ElastiCache.
- **IAM Policy**: An IAM policy named `elasticache_user_policy` is defined with permissions to perform various operations on ElastiCache resources.
- **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
- **ElastiCache User**: An ElastiCache user named `my_redis_user` is created with a password and assigned to the `default` user group. The user has full access to Redis operations.

