  cluster_identifier       = "example-redshift-cluster"
  node_type               = "dc2.large"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  iam_roles                = [aws_iam_role.redshift_cluster_role.arn]
  cluster_parameter_group_name = "default.redshift-1.0"
  vpc_security_group_ids   = ["sg-12345678"] # Replace with your VPC security group ID
