### Description:
This Terraform program creates a 2-node Redshift cluster and sets up an endpoint authorization for a specified AWS account ID. The program includes necessary IAM roles and configurations to ensure secure access to the Redshift cluster.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier      = "my-redshift-cluster"
  node_type              = "dc2.large"
  master_username        = "admin"
  master_password        = "SecurePassword123!"
  db_name                = "mydatabase"
  cluster_parameter_group_name = "default.redshift-1.x"
  iam_roles               = [aws_iam_role.redshift_role.arn]
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]

  cluster_subnet_group_name = aws_redshift_subnet_group.redshift_subnet_group.name

  skip_final_snapshot = true
}

# Define the Redshift subnet group
resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "my-redshift-subnet-group"
  description = "Subnet group for Redshift cluster"

  subnet_ids = [
    aws_subnet.subnet1.id,
    aws_subnet.subnet2.id,
  ]
}

# Define the Redshift security group
resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Define the Redshift IAM role
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "redshift_policy_attachment" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRedshiftClusterServiceRole"
}

# Define the Redshift endpoint authorization
resource "aws_redshift_endpoint_authorization" "redshift_endpoint_authorization" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  account_id         = "012345678910"
  status             = "active"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Redshift Cluster**: A 2-node Redshift cluster is created with the specified parameters, including the master username, password, database name, and IAM roles.
- **Subnet Group**: A subnet group is defined to specify the subnets where the Redshift cluster will be deployed.
- **Security Group**: A security group is created to allow inbound traffic on port 5439 (the default Redshift port).
- **IAM Role**: An IAM role is created with permissions to assume the Redshift service role and attach the necessary policies.
- **Endpoint Authorization**: The `aws_redshift_endpoint_authorization` resource allows the specified AWS account to connect to the Redshift cluster.

This configuration ensures that the Redshift cluster is securely set up and accessible from the specified account.

