### Description:
This Terraform program creates a single-node Amazon Redshift cluster and sets up a scheduled snapshot to be taken every 12 hours. It includes IAM roles for managing access to Redshift and S3, as well as a default VPC and subnet group.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Change to your desired AWS region
}

# IAM Role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-snapshot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift
resource "aws_iam_policy" "redshift_policy" {
  name = "redshift-snapshot-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:CreateBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:AbortMultipartUpload"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "redshift_policy_attachment" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = aws_iam_policy.redshift_policy.arn
}

# VPC and Subnet Group
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  count           = 2
  cidr_block      = ["10.0.1.0/24", "10.0.2.0/24"]
  vpc_id          = aws_vpc.main.id
  availability_zone = ["us-west-2a", "us-west-2b"]
}

resource "aws_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.main[*].id
}

# Redshift Cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier     = "my-redshift-cluster"
  node_type             = "dc2.large"
  master_username       = "admin"
  master_password       = "SecurePassword123!"
  cluster_parameter_group_name = "default.redshift-1.x"
  cluster_subnet_group_name = aws_subnet_group.redshift_subnet_group.name
  iam_roles              = [aws_iam_role.redshift_role.arn]
  automated_snapshot_retention_period = 1
  preferred_maintenance_window = "sun:07:00-sun:07:30"
}

# Scheduled Snapshot
resource "aws_scheduled_snapshots" "redshift_snapshot" {
  cluster_identifier = aws_redshift_cluster.main.cluster_identifier
  schedule_expression = "cron(0 12 * * ? *)"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Roles**: Two IAM roles are created: one for Redshift (`redshift_role`) and another for S3 (`redshift_policy`). The Redshift role assumes the Redshift service role, while the S3 role allows Redshift to write snapshots to an S3 bucket.
- **VPC and Subnet Group**: A basic VPC and subnet group are created to host the Redshift cluster.
- **Redshift Cluster**: A single-node Redshift cluster is set up with the specified parameters, including IAM roles for access control.
- **Scheduled Snapshot**: A scheduled snapshot is created to take a snapshot every 12 hours using a cron expression.

This configuration ensures that the Redshift cluster is properly set up with necessary IAM permissions and that snapshots are automatically created at regular intervals.

