### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define IAM role for Redshift cluster
resource "aws_iam_role" "redshift_cluster_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policy to the IAM role
resource "aws_iam_role_policy_attachment" "redshift_cluster_policy_attachment" {
  role       = aws_iam_role.redshift_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRedshiftClusterServiceRole"
}

# Create Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier     = "example-redshift-cluster"
  node_type             = "dc2.large"
  master_username       = "admin"
  master_password       = "SecurePassword123!"
  cluster_parameter_group_name = "default.redshift-6.x"
  cluster_subnet_group_name = "example-subnet-group"
  publicly_accessible   = true

  iam_roles = [aws_iam_role.redshift_cluster_role.arn]

  vpc_security_group_ids = ["sg-12345678"]  # Replace with your VPC security group ID

  tags = {
    Name = "Example Redshift Cluster"
  }
}

# Create endpoint access for the Redshift cluster
