### Description:
This Terraform program creates an AWS Lambda function along with its associated IAM role, policy, and deployment package. The Lambda function is configured to run on the Node.js 18 runtime, has a specific handler, and uses a "lambda.js" file as the source code. The IAM role allows the Lambda function to assume itself, which is necessary for certain configurations.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1" # Specify your desired AWS region
}

variable "lambda_handler" {
  default = "index.handler"
}

variable "lambda_code_path" {
  default = "./lambda.js"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name = "lambda_execution_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "my-nodejs-lambda"
  role          = aws_iam_role.lambda_role.arn
  handler       = var.lambda_handler
  runtime       = "nodejs18.x"
  timeout       = 30

  source_code_hash = filebase64sha256(var.lambda_code_path)

  environment {
    variables = {
      # Add any environment variables here
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Two variables are defined: `lambda_handler` and `lambda_code_path`. These specify the handler for the Lambda function and the path to the source code file, respectively.
- **IAM Role**: An IAM role named `lambda_execution_role` is created with a trust policy that allows the Lambda service to assume it.
- **IAM Policy**: An IAM policy named `lambda_execution_policy` is created to allow the Lambda function to write logs to CloudWatch Logs.
- **IAM Role Policy Attachment**: The policy is attached to the role.
- **Lambda Function**: The `aws_lambda_function` resource is created with the specified properties, including the handler, runtime, timeout, and source code hash. The environment variables can be added as needed.

This configuration ensures that the Lambda function is properly set up with the required permissions and can be deployed using Terraform.

