### Description:
The Terraform program will create a Kinesis Data Stream and configure it to send data to a specific DynamoDB table. The program will also set up necessary IAM roles and permissions to ensure secure communication between the Kinesis Data Stream and the DynamoDB table.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# Define the Kinesis Data Stream
resource "aws_kinesis_stream" "example_stream" {
  name        = "example-stream"
  retention_period_hours = 24
  shard_count    = 1

  tags = {
    Name = "Example-Kinesis-Stream"
  }
}

# Define the IAM role for the Kinesis Data Stream
resource "aws_iam_role" "kinesis_stream_role" {
  name = "kinesis-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "kinesis_stream_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisDataStreamsFullAccess"
  role       = aws_iam_role.kinesis_stream_role.name
}

# Define the IAM role for the DynamoDB table
resource "aws_iam_role" "dynamodb_role" {
  name = "dynamodb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "dynamodb_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDynamoDBFullAccess"
  role       = aws_iam_role.dynamodb_role.name
}

# Define the DynamoDB table
resource "aws_dynamodb_table" "example_table" {
  name           = "example-table"
  billing_mode   = "PAY_PER_REQUEST"
  attribute_definitions = [
    {
      attribute_name = "id"
      attribute_type = "S"
    }
  ]
  key_schema = [
    {
      attribute_name = "id"
      key_type       = "HASH"
    }
  ]

  tags = {
    Name = "Example-DynamoDB-Table"
  }
}

# Define the Kinesis Data Stream to DynamoDB stream configuration
resource "aws_kinesis_stream_to_dynamodb" "example_stream_to_dynamodb" {
  stream_arn = aws_kinesis_stream.example_stream.arn
  table_name = aws_dynamodb_table.example_table.name

  on_record_written_configuration {
    record_dynamodb_stream_view_type = "NEW_AND_OLD_IMAGES"
  }

  destination_config = {
    dynamodb_stream_output = {
      stream_arn = aws_dynamodb_table.example_table.stream_arn
    }
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Kinesis Data Stream**: A Kinesis Data Stream named `example-stream` is created with a retention period of 24 hours and 1 shard.
- **IAM Roles**: Two IAM roles, `kinesis-stream-role` and `dynamodb-role`, are created to allow the Kinesis Data Stream and DynamoDB table to communicate securely.
- **DynamoDB Table**: A DynamoDB table named `example-table` is created with a primary key `id`.
- **Kinesis Data Stream to DynamoDB Stream Configuration**: The `aws_kinesis_stream_to_dynamodb` resource configures the Kinesis Data Stream to send data to the DynamoDB table, specifying the stream view type and destination configuration.

This configuration ensures that the Kinesis Data Stream can receive data from other sources and store it in the specified DynamoDB table, with appropriate security measures in place.

