The Terraform program will create a SageMaker Domain resource, which is a collection of resources that enable users to collaborate on machine learning projects. The domain includes a SageMaker Studio notebook instance, a JupyterLab environment, and other related services.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "domain_name" {
  description = "The name of the SageMaker Domain"
  default     = "my-sagemaker-domain"
}

variable "default_user_settings" {
  description = "Default user settings for the SageMaker Domain"
  type        = object({
    execution_role = string
    jupyter_server_app_settings = object({
      default_instance_type = string
      kernel_spec = object({
        name = string
        display_name = string
      })
    })
  })
  default = {
    execution_role = "arn:aws:iam::123456789012:role/service-role/AmazonSageMaker-ExecutionRole"
    jupyter_server_app_settings = {
      default_instance_type = "ml.t2.medium"
      kernel_spec = {
        name = "python3"
        display_name = "Python 3"
      }
    }
  }
}

resource "aws_sagemaker_domain" "example" {
  domain_name = var.domain_name

  auth_mode = "IAM"

  default_user_settings = var.default_user_settings

  tags = {
    Name = var.domain_name
  }
}
```

