### Description:
The Terraform program will create a SageMaker Pipeline using the AWS provider. The pipeline will include a step to train a machine learning model using Amazon SageMaker's built-in algorithms. It will also include a step to deploy the trained model to an endpoint for real-time inference.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "sagemaker_role_arn" {
  description = "ARN of the IAM role to assume for SageMaker operations"
  default     = ""
}

variable "sagemaker_instance_type" {
  description = "Type of SageMaker instance to use for training"
  default     = "ml.m5.large"
}

variable "sagemaker_instance_count" {
  description = "Number of instances to use for training"
  default     = 1
}

variable "sagemaker_bucket" {
  description = "S3 bucket name for storing training data and artifacts"
  default     = ""
}

variable "sagemaker_job_name" {
  description = "Name of the SageMaker training job"
  default     = ""
}

resource "aws_sagemaker_pipeline" "example_pipeline" {
  name        = "example-pipeline"
  role_arn   = var.sagemaker_role_arn
  display_name = "Example SageMaker Pipeline"

  steps {
    name = "train-step"
    type = "TrainingStep"

    training_specification {
      algorithm_specification {
        algorithm_name = "image-classification"
        image_uri       = "174016031716.dkr.ecr.us-west-2.amazonaws.com/sagemaker-image-classification:latest"
      }

      input_data_config {
        s3_input {
          s3_uri = "s3://${var.sagemaker_bucket}/training-data"
          data_type = "S3Prefix"
          s3_data_distribution_type = "FullyReplicated"
        }
      }

      output_data_config {
        s3_output_location = "s3://${var.sagemaker_bucket}/output-data"
      }

      resource_config {
        instance_count = var.sagemaker_instance_count
        instance_type = var.sagemaker_instance_type
        volume_size_in_gb = 50
      }

      stopping_condition {
        max_runtime_in_seconds = 3600
      }
    }
  }

  steps {
    name = "deploy-step"
    type = "DeployStep"

    endpoint_config_name = aws_sagemaker_endpoint_config.example_endpoint_config.name

    endpoint_specification {
      endpoint_name = aws_sagemaker_endpoint.example_endpoint.name
      instance_type = var.sagemaker_instance_type
      initial_instance_count = 1
    }
  }
}

resource "aws_sagemaker_endpoint_config" "example_endpoint_config" {
  name = "example-endpoint-config"

  production_variants {
    variant_name = "variant-1"
    model_name   = aws_sagemaker_model.example_model.name
    initial_instance_count = 1
    instance_type = var.sagemaker_instance_type
  }
}

resource "aws_sagemaker_model" "example_model" {
  name = "example-model"

  primary_container {
    image = "174016031716.dkr.ecr.us-west-2.amazonaws.com/sagemaker-image-classification:latest"
    environment = {
      "SAGEMAKER_PROGRAM" = "train.py"
      "SAGEMAKER_SUBMIT_DIRECTORY" = "s3://${var.sagemaker_bucket}/training-data"
      "SAGEMAKER_ROLE" = var.sagemaker_role_arn
    }
  }
}

resource "aws_sagemaker_endpoint" "example_endpoint" {
  name = "example-endpoint"

  endpoint_config_name = aws_sagemaker_endpoint_config.example_endpoint_config.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Several variables are defined to allow customization of the pipeline, such as the role ARN, instance type, and bucket name.
- **SageMaker Pipeline**: A pipeline named `example-pipeline` is created with two steps:
  - **Train Step**: Trains a model using the `image-classification` algorithm.
  - **Deploy Step**: Deploys the trained model to an endpoint for real-time inference.
- **Endpoint Configuration**: An endpoint configuration is created to specify the instance type and number of instances for the endpoint.
- **Model**: A SageMaker model is created with the necessary environment variables for training.
- **Endpoint**: An endpoint is created using the endpoint configuration and model.

This configuration assumes that the necessary IAM permissions are already set up in the specified role ARN.

