### Description:
This Terraform program defines an AWS Lambda function that is triggered by an API Gateway. The Lambda function uses the Node.js 18 runtime and is configured with a source code file named `lambda.js` and a handler function named `index.js`. The function is deployed in a specific AWS region and uses IAM roles for authentication and authorization.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_execution_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Create an S3 bucket to store the Lambda function code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "my-lambda-code-bucket-${var.environment}"
  acl    = "private"
}

# Upload the Lambda function code to the S3 bucket
resource "aws_s3_object" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda.js"
  source = "lambda.js"
}

# Create the Lambda function
resource "aws_lambda_function" "lambda_function" {
  function_name = "my-lambda-function-${var.environment}"
  role         = aws_iam_role.lambda_execution_role.arn
  handler      = "index.handler"
  runtime     = "nodejs18.x"
  memory_size = 128
  timeout     = 3

  environment {
    variables = {
      ENVIRONMENT = var.environment
    }
  }

  source_code_hash = filebase64sha256("lambda.js")

  s3_bucket = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key    = "lambda.js"
}

# Create an API Gateway REST API
resource "aws_api_gateway_rest_api" "api" {
  name = "my-lambda-api-${var.environment}"
}

# Create an API Gateway resource
resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "my-lambda-endpoint"
}

# Create an API Gateway method
resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"

  authorization = "NONE"
}

# Create an API Gateway integration
resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method

  type             = "AWS_PROXY"
  integration_http_method = "POST"
  uri              = "arn:aws:apigateway:${var.region}:lambda:path/2015-03-31/functions/${aws_lambda_function.lambda_function.arn}/invocations"
}

# Create an API Gateway deployment
resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  stage_name = "prod"
}

# Output the API Gateway endpoint URL
output "api_endpoint" {
  value = "https://${aws_api_gateway_deployment.deployment.invoke_url}/my-lambda-endpoint"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Role**: An IAM role is created with the necessary permissions to execute Lambda functions.
- **S3 Bucket**: An S3 bucket is created to store the Lambda function code.
- **Lambda Function**: The Lambda function is defined with the specified runtime, handler, and environment variables.
- **API Gateway**: An API Gateway REST API is created, along with a resource and method to trigger the Lambda function.
- **Deployment**: The API Gateway is deployed to a stage, and the endpoint URL is outputted.

### Variables:
- `environment`: A variable to specify the environment (e.g., dev, prod). Default value is "dev".

This configuration ensures that the Lambda function is securely deployed and can be triggered via an API Gateway endpoint.

