### Description:
This Terraform program creates two subnets in the `us-east-1a` and `us-east-1b` availability zones within the AWS region. It also provisions an EC2 instance in each subnet using the latest Amazon Linux 2 AMI with a `t2.micro` instance type and attaches an EBS volume of 50 GB.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Create Subnets
resource "aws_subnet" "subnet_a" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

# Create Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.example.id
}

# Create Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.example.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

# Associate Public Route Table with Subnets
resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "subnet_b" {
  subnet_id      = aws_subnet.subnet_b.id
  route_table_id = aws_route_table.public.id
}

# Create Security Group
resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow all inbound traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create EBS Volume
resource "aws_ebs_volume" "example" {
  availability_zone = aws_subnet.subnet_a.availability_zone
  size              = 50
}

# Attach EBS Volume to Instance
resource "aws_instance" "instance_a" {
  ami           = data.aws_ami.latest_amazon_linux.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_a.id
  security_groups = [aws_security_group.allow_all.id]

  root_block_device {
    volume_size = 8
  }

  ebs_block_device {
    device_name = "/dev/sdb"
    volume_size = 50
    volume_type = "gp2"
  }
}

resource "aws_instance" "instance_b" {
  ami           = data.aws_ami.latest_amazon_linux.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_b.id
  security_groups = [aws_security_group.allow_all.id]

  root_block_device {
    volume_size = 8
  }

  ebs_block_device {
    device_name = "/dev/sdb"
    volume_size = 50
    volume_type = "gp2"
  }
}

# Data Source for Latest Amazon Linux AMI
data "aws_ami" "latest_amazon_linux" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **VPC Creation**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Subnets**: Two subnets, `subnet_a` and `subnet_b`, are created in `us-east-1a` and `us-east-1b` respectively.
- **Internet Gateway**: An internet gateway is created to allow outbound traffic.
- **Route Table**: A public route table is created and associated with both subnets to route traffic to the internet.
- **Security Group**: A security group allows all inbound and outbound traffic.
- **EBS Volume**: An EBS volume of 50 GB is created and attached to each instance.
- **Instances**: Two EC2 instances are created in each subnet using the latest Amazon Linux 2 AMI with a `t2.micro` instance type. Each instance has an EBS volume of 50 GB attached.

This configuration ensures that the instances have access to the internet and can communicate with each other within their respective subnets.

