### Description:
This Terraform program creates a VPC with three subnets: one public subnet for hosting a web server and two private subnets for running an application server and a relational database. The program also sets up an Internet Gateway, a NAT Gateway, and security groups to manage network traffic.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  default = "10.0.2.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "TerraformAI-VPC"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "TerraformAI-IGW"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.main.id
  subnet_id      = aws_subnet.public.id

  tags = {
    Name = "TerraformAI-NATGW"
  }
}

resource "aws_eip" "main" {
  tags = {
    Name = "TerraformAI-EIP"
  }
}

resource "aws_subnet" "public" {
  cidr_block          = var.public_subnet_cidr_block
  vpc_id              = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Name = "TerraformAI-PublicSubnet"
  }
}

resource "aws_subnet" "private" {
  cidr_block          = var.private_subnet_cidr_block
  vpc_id              = aws_vpc.main.id

  tags = {
    Name = "TerraformAI-PrivateSubnet1"
  }
}

resource "aws_subnet" "private2" {
  cidr_block          = var.private_subnet_cidr_block
  vpc_id              = aws_vpc.main.id

  tags = {
    Name = "TerraformAI-PrivateSubnet2"
  }
}

resource "aws_security_group" "web_server_sg" {
  name        = "WebServerSG"
  description = "Security group for web server"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "TerraformAI-WebServerSG"
  }
}

resource "aws_security_group" "app_server_sg" {
  name        = "AppServerSG"
  description = "Security group for application server"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "TerraformAI-AppServerSG"
  }
}

resource "aws_security_group" "db_server_sg" {
  name        = "DBServerSG"
  description = "Security group for database server"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "TerraformAI-DBServerSG"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "TerraformAI-PublicRT"
  }
}

resource "aws_route_table_association" "public_rt_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "TerraformAI-PrivateRT"
  }
}

resource "aws_route_table_association" "private_rt_assoc1" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private_rt.id
}

resource "aws_route_table_association" "private_rt_assoc2" {
  subnet_id      = aws_subnet.private2.id
  route_table_id = aws_route_table.private_rt.id
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **Variables**: Default values are provided for the VPC CIDR block, public subnet CIDR block, and private subnet CIDR block.
- **VPC**: A VPC is created with a specified CIDR block.
- **Internet Gateway**: An Internet Gateway is attached to the VPC to allow internet access to the public subnet.
- **NAT Gateway**: A NAT Gateway is created in the public subnet to enable outbound internet access for private subnets.
- **Elastic IP**: An Elastic IP is allocated for the NAT Gateway.
- **Subnets**: Two public subnets and two private subnets are created, each with its own CIDR block.
- **Security Groups**: Security groups are defined for the web server, application server, and database server, allowing specific inbound and outbound traffic.
- **Route Tables**: Route tables are created to route traffic between subnets and the internet/NAT Gateway.
- **Route Table Associations**: Subnets are associated with the appropriate route tables to ensure proper routing.

