### Description:
This Terraform program creates an Amazon ElastiCache cluster and authenticates a user using AWS Identity and Access Management (IAM). The program includes a VPC, subnets, security groups, ElastiCache cluster, and IAM role for authentication.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  default = "my-elasticache-cluster"
}

variable "subnet_ids" {
  default = ["subnet-12345678", "subnet-23456789"]
}

variable "security_group_ids" {
  default = ["sg-12345678"]
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  count        = length(var.subnet_ids)
  cidr_block   = element(var.subnet_ids, count.index)
  vpc_id       = aws_vpc.main.id
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

resource "aws_security_group" "main" {
  name        = "elasticache-sg"
  description = "Security group for Elasticache"

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elasticache_cluster" "main" {
  cluster_identifier = var.cluster_name
  engine            = "redis"
  engine_version    = "6.x"
  node_type         = "cache.t2.micro"
  num_cache_nodes   = 1
  subnet_group_name = aws_elasticache_subnet_group.main.name

  security_group_ids = var.security_group_ids
}

resource "aws_elasticache_subnet_group" "main" {
  name       = "${var.cluster_name}-subnet-group"
  description = "Subnet group for Elasticache"

  subnet_ids = var.subnet_ids
}

resource "aws_iam_role" "elasticache_user" {
  name = "elasticache-user-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "elasticache_user_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElastiCacheForRedisReadOnlyAccess"
  role       = aws_iam_role.elasticache_user.name
}
```

### Explanation:
