### Description:
This Terraform program creates an Amazon DynamoDB Accelerator (DAX) cluster using the `aws_dax_cluster` resource. The cluster will have one node of type `dax.r4.large` and a replication factor of 1.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_name" {
  default = "my-dax-cluster"
}

variable "subnet_ids" {
  default = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
}

resource "aws_dax_cluster" "example" {
  cluster_name          = var.cluster_name
  replication_factor    = 1
  node_type            = "dax.r4.large"
  subnet_group_name     = aws_dax_subnet_group.example.name
  iam_role_arns         = [aws_iam_role.dax_role.arn]
  security_group_ids   = [aws_security_group.dax_sg.id]

  tags = {
    Name = var.cluster_name
  }
}

resource "aws_dax_subnet_group" "example" {
  name       = var.cluster_name
  subnet_ids = var.subnet_ids

  tags = {
    Name = var.cluster_name
  }
}

resource "aws_iam_role" "dax_role" {
  name = "dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dax_policy_attachment" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXServiceRole"
}

resource "aws_security_group" "dax_sg" {
  name        = "dax-sg"
  description = "Security group for DAX cluster"

  ingress {
    from_port   = 8100
    to_port     = 8100
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: 
  - `cluster_name`: The name of the DAX cluster.
  - `subnet_ids`: A list of subnet IDs where the DAX nodes will be deployed.
- **Resources**:
  - **aws_dax_cluster**: Creates the DAX cluster with the specified node type, replication factor, and IAM role.
  - **aws_dax_subnet_group**: Defines the subnets in which the DAX cluster will be deployed.
  - **aws_iam_role**: Creates an IAM role with permissions for the DAX service.
  - **aws_iam_role_policy_attachment**: Attaches the necessary policy to the IAM role.
  - **aws_security_group**: Configures a security group to allow traffic on port 8100 (the DAX port).

Make sure to replace the `subnet_ids` with your actual subnet IDs and adjust the region as needed. This configuration is compatible with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

