LLM Output #0:
### Description:
This Terraform program creates a managed Apache Kafka (MSK) cluster in the `us-east-1` region, with logging enabled to an S3 bucket. The program includes necessary IAM roles and configurations to ensure proper access and permissions.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Define the S3 bucket for logging
resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-bucket"

  # Enable versioning for the S3 bucket
  versioning {
    enabled = true
  }

  # Set the bucket policy to allow MSK to write logs
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.msk_logs.arn}/*",
          "${aws_s3_bucket.msk_logs.arn}"
        ]
      }
    ]
  })
}

# Define the IAM role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the S3 bucket policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_role_policy_attachment" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_s3_bucket_policy.msk_logs.arn
}

# Define the MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster"

  kafka_version = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "m5.large"
    broker_azs     = ["us-east-1a", "us-east-1b", "us-east-1c"]

    ebs_storage_info {
      volume_size = 20
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = false
      }
      s3_logs {
        enabled = true
        bucket = aws_s3_bucket.msk_logs.bucket
        prefix = "msk-logs/"
      }
      firehose_logs {
        enabled = false
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **S3 Bucket**: An S3 bucket named `msk-logs-bucket` is created with versioning enabled. The bucket policy allows the MSK service to write logs to it.
- **IAM Role**: An IAM role named `msk-role` is created with permissions to assume the role from the MSK service.
- **IAM Role Policy Attachment**: The S3 bucket policy is attached to the IAM role.
- **MSK Cluster**: A managed MSK cluster is created with 3 broker nodes using `m5.large` instances in three Availability Zones (`us-east-1a`, `us-east-1b`, `us-east-1c`). Logging is enabled to the S3 bucket specified in the `msk_logs` resource.

