LLM Output #0:
### Description:
This Terraform program creates a managed Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log its data to a Kinesis Firehose delivery stream. The program includes IAM roles for the MSK broker nodes and the Kinesis Firehose delivery stream, as well as necessary provider configurations.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Define IAM role for MSK broker nodes
resource "aws_iam_role" "msk_broker_role" {
  name = "msk-broker-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the MSK broker role
resource "aws_iam_role_policy_attachment" "msk_broker_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMQBrokerServiceRole"
  role       = aws_iam_role.msk_broker_role.name
}

# Define IAM role for Kinesis Firehose delivery stream
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the Kinesis Firehose delivery stream role
resource "aws_iam_role_policy_attachment" "firehose_delivery_stream_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRole"
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# Create a VPC for the MSK cluster
resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create subnets for the MSK cluster
resource "aws_subnet" "msk_subnet_1" {
  vpc_id     = aws_vpc.msk_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "msk_subnet_2" {
  vpc_id     = aws_vpc.msk_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_logs" {
  name        = "msk-logs"
  destination = "s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.msk_logs.arn
    role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
  }

  tags = {
    Name = "msk-logs"
  }
}

# Create an S3 bucket for the Kinesis Firehose delivery stream
resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-bucket-${var.account_id}"
  acl    = "private"

  tags = {
    Name = "msk-logs-bucket"
  }
}

# Create the MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster"
  kafka_version = "2.8.2"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "m5.large"
    instance_count = 3
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/msk-cluster/logs"
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **IAM Roles**: Two IAM roles are created: one for the MSK broker nodes and another for the Kinesis Firehose delivery stream. These roles are attached to the respective resources.
- **VPC and Subnets**: A VPC and two subnets are created in the `us-east-1` region.
- **Security Group**: A security group is created to allow traffic on port 9092 (Kafka).
- **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream is created to send logs to an S3 bucket.
- **S3 Bucket**: An S3 bucket is created to store the logs.
- **MSK Cluster**: The MSK cluster is created with three broker nodes, each using `m5.large` instances with 100GB EBS storage. Logs are sent to CloudWatch Logs.

