### Description:
This Terraform program creates a managed Apache Kafka (MSK) cluster with JMX Exporter and Node Exporter enabled. It includes necessary IAM roles and configurations to ensure proper access and monitoring.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_cluster_size" {
  description = "Number of brokers in the MSK cluster"
  default     = 3
}

variable "jmx_exporter_enabled" {
  description = "Enable JMX Exporter on the brokers"
  default     = true
}

variable "node_exporter_enabled" {
  description = "Enable Node Exporter on the brokers"
  default     = true
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "${var.msk_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_policy_attachment" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMQManagedKafkaBrokerAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  number_of_broker_nodes = var.msk_cluster_size

  broker_node_group_info {
    instance_type = "m5.large"
    instance_count = var.msk_cluster_size

    ebs_storage_info {
      volume_size = 20
    }

    broker_azs = ["us-west-2a", "us-west-2b", "us-west-2c"]
  }

  broker_logs {
    cloudwatch_logs {
      enabled = true
      log_group_prefix = "${var.msk_cluster_name}-logs"
    }
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_msk_broker_configuration" "jmx_exporter_config" {
  name = "${var.msk_cluster_name}-jmx-exporter-config"

  kafka_version = "2.13.1"
  server_properties = <<EOF
# Enable JMX Exporter
export KAFKA_JMX_OPTS="-Dcom.sun.management.jmxremote -Dcom.sun.management.jmxremote.authenticate=false -Dcom.sun.management.jmxremote.ssl=false -Dcom.sun.management.jmxremote.port=9999"
EOF
}

