### Description:
This Terraform program creates a serverless Apache Kafka (MSK) cluster in the `us-east1` region. The cluster will be configured with a single broker and will use managed encryption for data at rest and in transit. The program includes IAM roles for the MSK cluster and a VPC with necessary security groups.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_broker_count" {
  description = "Number of brokers in the MSK cluster"
  default     = 1
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "msk_subnet_1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "msk-subnet-1"
  }
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_kafka_cluster" "msk_cluster" {
  cluster_name          = var.msk_cluster_name
  number_of_broker_nodes = var.msk_broker_count
  kafka_version         = "3.4.0"
  enhanced_monitoring = "DEFAULT"

  client_authentication {
    sasl {
      iam = {}
    }
  }

  encryption_info {
    encryption_at_rest {
      data_volume_kms_key_arn = aws_kms_key.msk_kms_key.arn
    }

    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }

  vpc_config {
    subnet_ids = [aws_subnet.msk_subnet_1.id]
    security_groups = [aws_security_group.msk_sg.id]
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_kms_key" "msk_kms_key" {
  description = "KMS key for MSK cluster encryption"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **Variables**: Two variables are defined: `msk_cluster_name` and `msk_broker_count`. Default values are provided for these variables.
- **VPC and Subnet**: A VPC and a subnet are created in the `us-east-1a` availability zone.
- **Security Group**: A security group is created to allow inbound traffic on port 9092 (Kafka).
- **MSK Cluster**: An MSK cluster is created with the specified number of brokers, using IAM authentication and managed encryption. The cluster is placed in the VPC and subnet created earlier.
- **KMS Key**: A KMS key is created for encryption at rest.

This configuration ensures that the MSK cluster is deployed securely and efficiently in the specified AWS region.

