### Description:
This Terraform program creates a Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes, encrypts data at rest using AWS Key Management Service (KMS), enables open monitoring, and outputs logs to a CloudWatch log group. Additionally, it sets up an S3 bucket and a Kinesis Firehose delivery stream to handle the output of the MSK logs.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "msk_kms_key_id" {
  default = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id" # Replace with your KMS key ARN
}

variable "s3_bucket_name" {
  default = "my-msk-logs-bucket"
}

variable "firehose_delivery_stream_name" {
  default = "my-msk-logs-firehose"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name

  broker_info {
    instance_type = "m5.large"
    number_of_instances = 3
  }

  encryption_info {
    encryption_at_rest {
      data_encryption_key_provider = "CUSTOMER_MANAGED_KMS"
      customer_managed_kms_key_arn = var.msk_kms_key_id
    }
  }

  monitoring_info {
    enhanced_monitoring = "DEFAULT"
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  tags = {
    Name = var.s3_bucket_name
  }
}

resource "aws_s3_bucket_policy" "msk_logs_bucket_policy" {
  bucket = aws_s3_bucket.msk_logs_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.msk_logs_bucket.arn}",
          "${aws_s3_bucket.msk_logs_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name = var.firehose_delivery_stream_name

  destination {
    s3 {
      bucket_arn = aws_s3_bucket.msk_logs_bucket.arn
      role_arn   = aws_iam_role.msk_logs_firehose_role.arn
    }
  }

  tags = {
    Name = var.firehose_delivery_stream_name
  }
}

resource "aws_iam_role" "msk_logs_firehose_role" {
  name = "msk_logs_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRole"
  ]
}

resource "aws_cloudwatch_log_group" "msk_logs_log_group" {
  name = "/aws/msk/${var.msk_cluster_name}/broker-logs"
  retention_in_days = 30

  tags = {
    Name = "/aws/msk/${var.msk_cluster_name}/broker-logs"
  }
}

resource "aws_cloudwatch_log_stream" "msk_logs_log_stream" {
  log_group_name = aws_cloudwatch_log_group.msk_logs_log_group.name
  name           = "broker-logs"
}

resource "aws_kinesis_firehose_delivery_stream_logging_configuration" "msk_logs_delivery_stream_logging" {
  delivery_stream_name = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name

  cloud_watch_logging_options {
    enabled = true
    log_group_name = aws_cloudwatch_log_group.msk_logs_log_group.name
    log_stream_name = aws_cloudwatch_log_stream.msk_logs_log_stream.name
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Variables are defined for the MSK cluster name, KMS key ID, S3 bucket name, and Firehose delivery stream name. Default values are provided.
- **MSK Cluster**: An MSK cluster is created with three broker nodes, encryption at rest using a KMS key, and open monitoring.
- **S3 Bucket**: An S3 bucket is created to store the MSK logs.
- **S3 Bucket Policy**: A policy is attached to the S3 bucket to allow access from the Firehose delivery stream.
- **Kinesis Firehose Delivery Stream**: A delivery stream is set up to send logs to the S3 bucket.
- **IAM Role**: An IAM role is created for the Firehose delivery stream to assume the necessary permissions.
- **CloudWatch Log Group and Stream**: A CloudWatch log group and stream are created to capture the MSK broker logs.
- **Logging Configuration**: Logging is enabled for the Firehose delivery stream to output logs to the CloudWatch log group.

