### Description:
This Terraform program creates a Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes, outputs logs to a CloudWatch log group, stores data in an S3 bucket, and uses Kinesis Firehose to deliver the data to the S3 bucket. It also includes an MSK Connect custom plugin and a connector that uses this plugin to connect to the MSK cluster.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Change to your desired AWS region
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "msk_connect_plugin_name" {
  default = "debezium-plugin"
}

variable "msk_connect_connector_name" {
  default = "debezium-connector"
}

resource "aws_kms_key" "msk_cluster_encryption_key" {
  description = "KMS key for MSK cluster encryption at rest"
}

resource "aws_kms_alias" "msk_cluster_encryption_alias" {
  name          = "alias/msk-cluster-encryption-key"
  target_key_id = aws_kms_key.msk_cluster_encryption_key.id
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version         = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "m5.large"
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    security_groups = ["sg-12345678"]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest {
      data_volume_kms_key_id = aws_kms_key.msk_cluster_encryption_key.arn
    }
  }

  monitoring_info {
    enhanced_monitoring = "DEFAULT"
  }
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "${var.msk_cluster_name}-logs"
}

resource "aws_s3_bucket" "msk_data" {
  bucket = "${var.msk_cluster_name}-data"
  acl    = "private"
}

resource "aws_s3_bucket_policy" "msk_data_policy" {
  bucket = aws_s3_bucket.msk_data.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.msk_data.bucket}/*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name        = "${var.msk_cluster_name}-firehose"
  destination = "s3"

  s3_destination_configuration {
    bucket_arn = aws_s3_bucket.msk_data.arn
    role_arn   = aws_iam_role.msk_firehose_role.arn
  }
}

resource "aws_iam_role" "msk_firehose_role" {
  name = "${var.msk_cluster_name}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  policies = [
    jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = [
            "s3:PutObject",
            "s3:GetObject"
          ]
          Resource = "arn:aws:s3:::${aws_s3_bucket.msk_data.bucket}/*"
        }
      ]
    })
  ]
}

resource "aws_msk_connect_custom_plugin" "debezium_plugin" {
  name              = var.msk_connect_plugin_name
  version           = "1.0.0"
  archive           = "s3://path/to/debezium.zip"
  description       = "Debezium plugin for MSK Connect"
  connector_config = jsonencode({
    "name": "debezium-connector",
    "config": {
      "connector.class": "io.debezium.connector.mysql.MySqlConnector",
      "tasks.max": "1",
      "database.hostname": "your-mysql-instance-endpoint",
      "database.port": "3306",
      "database.user": "your-mysql-user",
      "database.password": "your-mysql-password",
      "database.server.id": "18446744073709551615",
      "database.server.name": "your-mysql-server-name",
      "database.whitelist": "your-mysql-database",
      "database.history.kafka.bootstrap.servers": "${aws_msk_cluster.msk_cluster.broker_nodes[0].broker_endpoint}",
      "database.history.kafka.topic": "debezium-history-topic"
    }
  })
}

resource "aws_msk_connect_connector" "debezium_connector" {
  name              = var.msk_connect_connector_name
  cluster_arn       = aws_msk_cluster.msk_cluster.arn
  custom_plugin_name = var.msk_connect_plugin_name
  type              = "custom"
  config             = jsonencode({
    "name": "debezium-connector",
    "config": {
      "connector.class": "io.debezium.connector.mysql.MySqlConnector",
      "tasks.max": "1",
      "database.hostname": "your-mysql-instance-endpoint",
      "database.port": "3306",
      "database.user": "your-mysql-user",
      "database.password": "your-mysql-password",
      "database.server.id": "18446744073709551615",
      "database.server.name": "your-mysql-server-name",
      "database.whitelist": "your-mysql-database",
      "database.history.kafka.bootstrap.servers": "${aws_msk_cluster.msk_cluster.broker_nodes[0].broker_endpoint}",
      "database.history.kafka.topic": "debezium-history-topic"
    }
  })
}
```

### Explanation:
- **AWS Provider Configuration**: Sets the AWS region where the resources will be created.
- **Variables**: Define default values for the MSK cluster name, plugin name, and connector name.
- **KMS Key**: Creates a KMS key for encrypting the MSK cluster data at rest.
- **MSK Cluster**: Configures the MSK cluster with three broker nodes, encryption at rest, and enhanced monitoring.
- **CloudWatch Log Group**: Outputs logs from the MSK cluster to a CloudWatch log group.
- **S3 Bucket**: Stores the data delivered by Kinesis Firehose.
- **Kinesis Firehose Delivery Stream**: Sends data from the S3 bucket to Kinesis Firehose.
- **IAM Role**: Provides permissions for the Kinesis Firehose role to access the S3 bucket.
- **MSK Connect Custom Plugin**: Uploads a custom plugin (debezium.zip) to S3 and configures it for use with the MSK cluster.
- **MSK Connect Connector**: Uses the custom plugin to connect to the MSK cluster and process data from a MySQL database.

