### Description:
This Terraform program creates a DynamoDB table named `my_dynamodb_table` with replicas in the `us-east-2` and `us-west-2` regions. The table will have a primary key consisting of a partition key and a sort key. It includes necessary IAM roles for DynamoDB access and ensures that the table is properly configured with replicas.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for DynamoDB Access
resource "aws_iam_role" "dynamodb_access_role" {
  name = "dynamodb_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for DynamoDB Access
resource "aws_iam_policy" "dynamodb_access_policy" {
  name = "dynamodb_access_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:CreateTable",
          "dynamodb:DeleteItem",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:UpdateItem"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "dynamodb_access_policy_attachment" {
  role       = aws_iam_role.dynamodb_access_role.name
  policy_arn = aws_iam_policy.dynamodb_access_policy.arn
}

# DynamoDB Table with Replicas
resource "aws_dynamodb_table" "my_dynamodb_table" {
  name           = "my_dynamodb_table"
  billing_mode   = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  attribute {
    name = "timestamp"
    type = "N"
  }
  key_schema {
    attribute_name = "id"
    key_type       = "HASH"
  }
  key_schema {
    attribute_name = "timestamp"
    key_type       = "RANGE"
  }
  global_secondary_index {
    index_name = "timestamp_index"
    key_schema {
      attribute_name = "timestamp"
      key_type       = "HASH"
    }
    projection {
      projection_type = "ALL"
    }
  }
  provisioner "local-exec" {
    command = "echo 'DynamoDB table created with replicas in us-east-2 and us-west-2'"
  }

  # Enable replication to us-east-2
  replica {
    region = "us-east-2"
  }

  # Enable replication to us-west-2
  replica {
    region = "us-west-2"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured to use the `us-east-1` region.
- **IAM Roles**: Two IAM roles are created: one for DynamoDB access (`dynamodb_access_role`) and another for attaching policies (`dynamodb_access_policy`). The policy allows full access to DynamoDB operations.
- **DynamoDB Table**: A table named `my_dynamodb_table` is created with a primary key (`id` and `timestamp`) and a global secondary index (`timestamp_index`). The table uses `PAY_PER_REQUEST` billing mode.
- **Replication**: The table is configured to replicate to `us-east-2` and `us-west-2` regions using the `replica` block.
- **Local Execution**: A `local-exec` provisioner is used to print a message indicating that the table has been created with replicas.

