### Description:
This Terraform program creates an AWS Virtual Private Cloud (VPC) with an Egress-Only Internet Gateway (EIGW). The EIGW allows instances within the VPC to communicate with the internet but not vice versa, enhancing security by preventing direct internet access from instances.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  default     = [
    "10.0.1.0/24",
    "10.0.2.0/24"
  ]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "public" {
  count          = length(var.subnet_cidr_blocks)
  cidr_block      = var.subnet_cidr_blocks[count.index]
  vpc_id         = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MyInternetGateway"
  }
}

resource "aws_eip" "eip" {
  vpc = true
}

resource "aws_network_interface" "public" {
  subnet_id       = aws_subnet.public[0].id
  private_ip      = "10.0.1.100"
  associate_public_ip_address = true
  security_groups = [aws_security_group.allow_all.id]

  tags = {
    Name = "PublicNetworkInterface"
  }
}

resource "aws_network_interface_attachment" "public" {
  instance_id   = aws_instance.web.id
  network_interface_id = aws_network_interface.public.id
  device_index = 0
}

resource "aws_security_group" "allow_all" {
  name        = "AllowAllIngress"
  description = "Allows all inbound traffic"

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AllowAllSecurityGroup"
  }
}

resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"  # Use an appropriate AMI
  instance_type = "t2.micro"
  key_name      = "my-key-pair"            # Ensure this key pair exists

  vpc_security_group_ids = [aws_security_group.allow_all.id]

  subnet_id = aws_subnet.public[0].id

  tags = {
    Name = "WebInstance"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: Two variables are defined: `vpc_cidr_block` and `subnet_cidr_blocks`. Default values are provided for these variables.
- **VPC**: An AWS VPC is created with the specified CIDR block.
- **Subnets**: Two public subnets are created within the VPC, each with its own CIDR block.
- **Internet Gateway**: An Egress-Only Internet Gateway is attached to the VPC.
- **EIP**: An Elastic IP address is allocated for the EIGW.
- **Network Interface**: A public network interface is created in one of the subnets, associated with the EIP, and attached to an instance.
- **Security Group**: A security group is created to allow all inbound and outbound traffic.
- **Instance**: A web server instance is launched in one of the subnets, using the specified AMI and key pair.

This configuration ensures that instances within the VPC can communicate with the internet but not vice versa, enhancing security.

