### Description:
This Terraform program creates two AWS VPCs and establishes a peering connection between them. The VPCs are configured in different regions for demonstration purposes. The program includes IAM roles for managing the VPC peering connection and sets up necessary security groups to allow traffic between the VPCs.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to any valid AWS region
}

# Define the first VPC
resource "aws_vpc" "vpc1" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "VPC1"
  }
}

# Define the second VPC
resource "aws_vpc" "vpc2" {
  cidr_block = "10.1.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "VPC2"
  }
}

# Define the peering connection
resource "aws_vpc_peering_connection" "peering" {
  vpc_id      = aws_vpc.vpc1.id
  peer_vpc_id = aws_vpc.vpc2.id
  peer_region = "us-west-2"  # Change this to the region of the second VPC

  tags = {
    Name = "VPC Peering Connection"
  }
}

# Create an IAM role for managing the VPC peering connection
resource "aws_iam_role" "vpc_peering_role" {
  name = "VPCPeeringRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the VPC peering role to the VPCs
resource "aws_iam_role_policy_attachment" "vpc_peering_role_attachment_vpc1" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSVMImportExportService"
  role       = aws_iam_role.vpc_peering_role.name
}

resource "aws_iam_role_policy_attachment" "vpc_peering_role_attachment_vpc2" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSVMImportExportService"
  role       = aws_iam_role.vpc_peering_role.name
}

# Create security groups for the VPCs
resource "aws_security_group" "vpc1_sg" {
  name        = "VPC1-SG"
  description = "Security group for VPC1"
  vpc_id      = aws_vpc.vpc1.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "vpc2_sg" {
  name        = "VPC2-SG"
  description = "Security group for VPC2"
  vpc_id      = aws_vpc.vpc2.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Allow traffic between the VPCs through the peering connection
resource "aws_network_acl" "vpc1_acl" {
  vpc_id = aws_vpc.vpc1.id

  ingress {
    rule_number = 100
    action     = "allow"
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
    cidr_blocks = [aws_vpc_peering_connection.peering.peer_cidr_block]
  }

  egress {
    rule_number = 100
    action     = "allow"
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
    cidr_blocks = [aws_vpc_peering_connection.peering.cidr_block]
  }
}

resource "aws_network_acl" "vpc2_acl" {
  vpc_id = aws_vpc.vpc2.id

  ingress {
    rule_number = 100
    action     = "allow"
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
    cidr_blocks = [aws_vpc_peering_connection.peering.cidr_block]
  }

  egress {
    rule_number = 100
    action     = "allow"
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
    cidr_blocks = [aws_vpc_peering_connection.peering.cidr_block]
  }
}

# Associate the security groups and network ACLs with the subnets
resource "aws_subnet" "subnet1" {
  cidr_block          = "10.0.1.0/24"
