### Description:
This Terraform program sets up a basic AWS Neptune cluster with a custom parameter group and an instance within that cluster using a custom parameter group. The instance is configured to allow connections only from a specified example subnet.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define a VPC and subnet for Neptune
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a Neptune DB Parameter Group
resource "aws_neptune_parameter_group" "example" {
  name        = "neptune-custom-param-group"
  family      = "neptune1"
  description = "Custom Neptune parameter group"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "query_timeout"
    value = "300"
  }
}

# Create a Neptune DB Cluster
resource "aws_neptune_cluster" "example" {
  cluster_identifier = "neptune-cluster-example"
  engine_version    = "1.2.0.1"
  db_subnet_group_name = aws_neptune_subnet_group.example.name

  parameter_group_name = aws_neptune_parameter_group.example.name

  cluster_members {
    db_instance_identifier = aws_neptune_instance.example.id
  }
}

# Create a Neptune DB Subnet Group
resource "aws_neptune_subnet_group" "example" {
  name       = "neptune-subnet-group-example"
  description = "Subnet group for Neptune cluster"

  subnet_ids = [aws_subnet.example.id]
}

# Create a Neptune DB Instance
resource "aws_neptune_instance" "example" {
  identifier          = "neptune-instance-example"
  engine_version    = "1.2.0.1"
  db_subnet_group_name = aws_neptune_subnet_group.example.name
  parameter_group_name = aws_neptune_parameter_group.example.name

  publicly_accessible = false
  tags = {
    Name = "neptune-instance-example"
  }
}

# Allow connections to the Neptune instance from the specified subnet
resource "aws_security_group_rule" "allow_inbound" {
  type        = "ingress"
  from_port   = 8182
  to_port     = 8182
  protocol    = "tcp"
  cidr_blocks = ["10.0.1.0/24"]  # Example subnet CIDR block
  security_group_id = aws_neptune_instance.example.security_groups[0]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **VPC and Subnet**: A VPC and a subnet are created for the Neptune cluster.
- **Neptune Parameter Group**: A custom parameter group is defined with specific parameters like `max_connections` and `query_timeout`.
- **Neptune Cluster**: A Neptune cluster is created with the specified parameter group and subnet group.
- **Neptune Subnet Group**: A subnet group is created to associate the subnet with the cluster.
- **Neptune Instance**: An instance is created within the cluster with its own custom parameter group and is set to be publicly accessible (though it's not recommended for production environments).
- **Security Group Rule**: A security group rule is added to allow inbound traffic on port 8182 from the specified subnet.

This configuration ensures that the Neptune instance is securely accessible only from the specified subnet.

