### Description:
This Terraform program creates two AWS Chime Voice Connectors, each configured with encryption, and groups them together into a single resource. The program includes necessary IAM roles and uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define IAM role for Chime Voice Connectors
resource "aws_iam_role" "chime_voice_connector_role" {
  name = "chime_voice_connector_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

# Define IAM policy for Chime Voice Connectors
resource "aws_iam_policy" "chime_voice_connector_policy" {
  name = "chime_voice_connector_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "chime:CreateVoiceConnector",
          "chime:DeleteVoiceConnector",
          "chime:UpdateVoiceConnector",
          "chime:GetVoiceConnector",
          "chime:GetVoiceConnectorTermination",
          "chime:GetVoiceConnectorLoggingConfiguration",
          "chime:PutVoiceConnectorLoggingConfiguration",
          "chime:PutVoiceConnectorTermination",
          "chime:ListVoiceConnectors",
          "chime:ListVoiceConnectorTerminations",
          "chime:ListVoiceConnectorLoggingConfigurations"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "chime_voice_connector_policy_attachment" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = aws_iam_policy.chime_voice_connector_policy.arn
}

# Create the first Chime Voice Connector
resource "aws_chime_voice_connector" "voice_connector_1" {
  name = "voice_connector_1"

  encryption {
    kms_key_id = aws_kms_key.voice_connector_1.key_id
  }

  tags = {
    Name = "voice_connector_1"
  }
}

# Create the second Chime Voice Connector
resource "aws_chime_voice_connector" "voice_connector_2" {
  name = "voice_connector_2"

  encryption {
    kms_key_id = aws_kms_key.voice_connector_2.key_id
  }

  tags = {
    Name = "voice_connector_2"
  }
}

# Create KMS keys for encryption
resource "aws_kms_key" "voice_connector_1" {
  description = "KMS key for voice connector 1"
}

resource "aws_kms_key" "voice_connector_2" {
  description = "KMS key for voice connector 2"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **IAM Roles and Policies**: Two IAM roles (`chime_voice_connector_role`) and policies (`chime_voice_connector_policy`) are defined to allow Chime Voice Connectors to perform necessary actions.
- **Chime Voice Connectors**: Two Chime Voice Connectors (`voice_connector_1` and `voice_connector_2`) are created, each with encryption enabled using a KMS key.
- **KMS Keys**: KMS keys (`voice_connector_1` and `voice_connector_2`) are created to encrypt the data transmitted over the Chime Voice Connectors.

This configuration ensures that the Chime Voice Connectors are properly set up with encryption and can be managed using Terraform.

