### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Chime Voice Connector
resource "aws_iam_role" "chime_voice_connector_role" {
  name = "chime_voice_connector_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Chime Voice Connector
resource "aws_iam_policy" "chime_voice_connector_policy" {
  name = "chime_voice_connector_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "chime_voice_connector_policy_attachment" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = aws_iam_policy.chime_voice_connector_policy.arn
}

# Create AWS Chime Voice Connector
resource "aws_chime_voice_connector" "example" {
  name = "example-voice-connector"

  require_encryption = true

  kms_key_id = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"

  tags = {
    Name = "example-voice-connector"
  }
}

# Create Kinesis Stream
resource "aws_kinesis_stream" "example" {
  name          = "example-kinesis-stream"
  shard_count   = 1
  retention_period_hours = 24

  tags = {
    Name = "example-kinesis-stream"
  }
}

# Create Kinesis Data Stream ARN
data "aws_kinesis_stream_arn" "example" {
  name = aws_kinesis_stream.example.name
}

# Create Lambda Function to Stream Media to Kinesis
resource "aws_lambda_function" "stream_media_to_kinesis" {
  filename      = "stream_media_to_kinesis.zip"
  function_name = "stream_media_to_kinesis"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  role = aws_iam_role.chime_voice_connector_role.arn

  source_code_hash = filebase64sha256("stream_media_to_kinesis.zip")

  environment = {
    variables = {
      KINESIS_STREAM_ARN = data.aws_kinesis_stream_arn.example.arn
    }
  }

  timeout = 30
}

# Create Lambda Event Source Mapping
resource "aws_lambda_event_source_mapping" "stream_media_to_kinesis" {
  event_source_arn = aws_chime_voice_connector.example.event_stream_arn
  function_name    = aws_lambda_function.stream_media_to_kinesis.function_name
  starting_position = "TRIM_HORIZON"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **IAM Roles**: Two IAM roles are created: one for the Chime Voice Connector and another for the Lambda function. The Chime Voice Connector role allows it to assume the Chime service role, while the Lambda function role allows it to write to the Kinesis stream.
- **IAM Policies**: Two IAM policies are created: one for the Chime Voice Connector role and another for the Lambda function role. The Chime Voice Connector policy allows it to write to the Kinesis stream, and the Lambda function policy allows it to read from the Kinesis stream.
- **Chime Voice Connector**: A Chime Voice Connector is created with encryption enabled and a KMS key ID.
- **Kinesis Stream**: A Kinesis stream is created with a retention period of 24 hours.
- **Lambda Function**: A Lambda function is created to stream media to the Kinesis stream. The function is triggered by events from the Chime Voice Connector.
- **Event Source Mapping**: An event source mapping is created to map events from the Chime Voice Connector to the Lambda function.

Make sure to replace `"arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"` with your actual KMS key ARN. Also, ensure that the `stream_media_to_kinesis.zip` file is available in the same directory as your Terraform script.

