### Description:
This Terraform program creates an AWS VPC with two subnets, groups them into an AWS Redshift subnet group, and sets up a basic AWS Redshift cluster along with an endpoint access using the subnet group.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create a VPC
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Create two subnets
resource "aws_subnet" "subnet_1" {
  vpc_id     = aws_vpc.example_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id     = aws_vpc.example_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create a Redshift subnet group
resource "aws_redshift_subnet_group" "example_subnet_group" {
  name       = "example-subnet-group"
  description = "Subnet group for Redshift cluster"

  subnet_ids = [
    aws_subnet.subnet_1.id,
    aws_subnet.subnet_2.id,
  ]
}

# Create a Redshift cluster
resource "aws_redshift_cluster" "example_cluster" {
  cluster_identifier      = "example-cluster"
  node_type              = "dc2.large"
  master_username        = "admin"
  master_password        = "SecurePassword123!"
  db_name                = "mydatabase"
  cluster_subnet_group_name = aws_redshift_subnet_group.example_subnet_group.name

  iam_roles = [
    aws_iam_role.example_role.arn,
  ]

  vpc_security_group_ids = [
    aws_security_group.example_sg.id,
  ]
}

# Create an IAM role for Redshift
resource "aws_iam_role" "example_role" {
  name = "example-redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

# Attach an IAM policy to the IAM role
resource "aws_iam_policy_attachment" "example_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRedshiftReadOnlyAccess"
  role       = aws_iam_role.example_role.name
}

# Create a security group for Redshift
resource "aws_security_group" "example_sg" {
  name        = "example-redshift-sg"
  description = "Security group for Redshift cluster"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an endpoint access for the Redshift cluster
resource "aws_redshift_endpoint_access" "example_endpoint_access" {
  cluster_identifier = aws_redshift_cluster.example_cluster.cluster_identifier
  endpoint_name      = "example-endpoint-access"
  subnet_group_name = aws_redshift_subnet_group.example_subnet_group.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnets**: Two subnets are created in different availability zones (`us-west-2a` and `us-west-2b`) within the VPC.
- **Redshift Subnet Group**: A subnet group is created and associated with the two subnets.
- **Redshift Cluster**: A basic Redshift cluster is created with the specified parameters, including the subnet group, IAM roles, and security group.
- **IAM Role and Policy**: An IAM role is created with permissions for Redshift, and a policy attachment is made to allow read-only access.
- **Security Group**: A security group is created to allow inbound traffic on port 5439 (PostgreSQL) and outbound traffic on all ports.
- **Endpoint Access**: An endpoint access is created for the Redshift cluster, allowing access from any IP address.

