### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster."
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster."
  default     = "dc2.large"
}

variable "master_username" {
  description = "The master username for the Redshift cluster."
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the Redshift cluster."
  default     = "SecurePassword123!"
}

variable "vpc_id" {
  description = "The ID of the VPC where the Redshift cluster will be deployed."
  default     = "vpc-1234567890abcdef0"
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the Redshift cluster will be deployed."
  default     = ["subnet-12345678", "subnet-09876543"]
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier      = var.cluster_identifier
  node_type              = var.node_type
  master_username        = var.master_username
  master_password        = var.master_password
  vpc_id                 = var.vpc_id
  cluster_subnet_group_name = aws_redshift_subnet_group.example.name

  iam_roles = [
    aws_iam_role.redshift_reader.arn,
    aws_iam_role.redshift_writer.arn,
  ]

  publicly_accessible = true
}

resource "aws_redshift_subnet_group" "example" {
  name       = "${var.cluster_identifier}-subnet-group"
  description = "Subnet group for the Redshift cluster"

  subnet_ids = var.subnet_ids
}

resource "aws_iam_role" "redshift_reader" {
  name = "redshift-reader-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_reader_policy" {
  role       = aws_iam_role.redshift_reader.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftReadOnlyAccess"
}

resource "aws_iam_role" "redshift_writer" {
  name = "redshift-writer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_writer_policy" {
  role       = aws_iam_role.redshift_writer.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftFullAccess"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
