}

variable "node_type" {
  description = "The type of nodes to use for the cluster."
  default     = "dc2.large"
}

variable "master_username" {
  description = "The master username for the Redshift cluster."
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the Redshift cluster."
  default     = "SecurePassword123!"
}

variable "db_name" {
  description = "The name of the database to create."
  default     = "mydatabase"
}

variable "parameter_group_name" {
  description = "The name of the parameter group."
  default     = "my-parameter-group"
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier      = var.cluster_identifier
  node_type              = var.node_type
  master_username        = var.master_username
  master_password        = var.master_password
  db_name                = var.db_name
  iam_roles               = [aws_iam_role.example.arn]
  cluster_parameter_group_name = var.parameter_group_name

  # Enable notifications for parameter group changes
  enable_notifications = true
  notification_topic_arn = aws_sns_topic.example.arn
}

