### Description:
This Terraform program creates an AWS Redshift cluster, attaches an example AWS Redshift parameter group, and sets up an AWS Redshift event subscription to send events related to the parameter group to an AWS SNS topic. The configuration includes necessary IAM roles and uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define the SNS topic
resource "aws_sns_topic" "example" {
  name = "redshift-parameter-group-events"
}

# Define the SNS topic policy to allow Redshift to publish to it
resource "aws_sns_topic_policy" "example" {
  topic_arn = aws_sns_topic.example.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "SNS:Publish"
      },
    ]
  })
}

# Define the Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name       = "example-redshift-parameter-group"
  family     = "redshift-1.0"
  description = "Example Redshift parameter group"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "query_grouping"
    value = "true"
  }
}

# Define the Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier = "example-redshift-cluster"
  node_type         = "dc2.large"
  master_username   = "admin"
  master_password   = "SecurePassword123!"
  db_name           = "exampledb"
  iam_roles         = [aws_iam_role.example.arn]

  vpc_security_group_ids = [aws_security_group.example.id]

  # Attach the parameter group to the cluster
  cluster_parameter_group_name = aws_redshift_parameter_group.example.name
}

# Define the IAM role for Redshift
resource "aws_iam_role" "example" {
  name = "redshift-sns-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

# Define the IAM policy for the Redshift role
resource "aws_iam_policy" "example" {
  name = "redshift-sns-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.example.arn
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}

# Define the Redshift event subscription
resource "aws_redshift_event_subscription" "example" {
  name             = "example-redshift-event-subscription"
  sns_topic_arn    = aws_sns_topic.example.arn
  source_type      = "cluster"
  source_ids       = [aws_redshift_cluster.example.cluster_identifier]
  event_categories = ["configuration", "management", "monitoring"]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **SNS Topic**: An SNS topic named `redshift-parameter-group-events` is created.
- **SNS Topic Policy**: A policy is attached to the SNS topic to allow Redshift to publish to it.
- **Redshift Parameter Group**: A parameter group named `example-redshift-parameter-group` is defined with specific parameters.
- **Redshift Cluster**: A cluster named `example-redshift-cluster` is created, using the parameter group and IAM role.
- **IAM Role**: An IAM role named `redshift-sns-role` is created to allow Redshift to publish to the SNS topic.
- **IAM Policy**: An IAM policy named `redshift-sns-policy` is created to allow the role to publish to the SNS topic.
- **IAM Role Policy Attachment**: The policy is attached to the IAM role.
- **Redshift Event Subscription**: An event subscription is created to send events related to the parameter group to the SNS topic.

