### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "group_name" {
  default = "ExampleGroup"
}

variable "role_arn" {
  default = "arn:aws:iam::123456789012:role/ExampleRole"
}

resource "aws_iam_group" "example_group" {
  name = var.group_name
}

resource "aws_iam_policy" "example_policy" {
  name        = "ExamplePolicy"
  description = "Allows users to assume ExampleRole and access specific S3 buckets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sts:AssumeRole"]
        Principal = {
          Service = ["ec2.amazonaws.com"]
        }
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = ["arn:aws:s3:::example-bucket/*"]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "example_policy_attachment" {
  group       = aws_iam_group.example_group.name
  policy_arn = aws_iam_policy.example_policy.arn
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Two variables are defined: `group_name` and `role_arn`. Default values are provided for these variables.
- **IAM Group**: A basic IAM group named `ExampleGroup` is created.
- **IAM Policy**: A policy named `ExamplePolicy` is created that allows users to assume the `ExampleRole` and access objects in the `example-bucket`.
- **IAM Group Policy Attachment**: The policy is attached to the group, allowing the group members to assume the role and access the specified S3 bucket.

