### Description:
This Terraform program creates an AWS S3 bucket and sets up an SNS topic to receive notifications whenever a `.log` object is created in the bucket. The program includes a default region and uses IAM roles for necessary permissions.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Default region
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name        = "Example S3 Bucket"
    Environment = "Development"
  }
}

resource "aws_s3_bucket_notification_configuration" "example_notification" {
  bucket = aws_s3_bucket.example_bucket.bucket

  lambda_function_configuration {
    events = ["s3:ObjectCreated:*"]

    filter_prefix = "*.log"

    lambda_function_arn = aws_lambda_function.example_lambda.function_arn
  }
}

resource "aws_lambda_function" "example_lambda" {
  filename      = "lambda_function_payload.zip"
  function_name = "example_lambda"
  role          = aws_iam_role.example_lambda.arn
  handler       = "index.handler"

  runtime = "python3.8"

  source_code_hash = filebase64sha256("lambda_function_payload.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.example_bucket.bucket
    }
  }
}

resource "aws_iam_role" "example_lambda" {
  name = "example-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_lambda_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.example_lambda.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the default region `us-west-2`.
- **S3 Bucket**: An S3 bucket named `example-bucket-${random_string.random_suffix.result}` is created with a private ACL and tags.
- **S3 Notification Configuration**: The bucket is configured to trigger an SNS topic when a `.log` object is created. The Lambda function is set to handle these notifications.
- **Lambda Function**: A Python Lambda function named `example_lambda` is defined. It is triggered by the SNS topic and processes objects in the specified S3 bucket.
- **IAM Role**: An IAM role `example-lambda-role` is created with the necessary permissions to execute the Lambda function.
- **IAM Policy Attachment**: The Lambda function is attached to the `AWSLambdaBasicExecutionRole` policy to ensure it has basic execution permissions.

This configuration ensures that the S3 bucket is set up to notify an SNS topic when a `.log` object is created, and the Lambda function processes these notifications.

