  acl = "private"

  tags = {
    Name = "My CORS Bucket"
  }
}

resource "aws_s3_bucket_cors_configuration" "example" {
  bucket = aws_s3_bucket.example.id

  cors_rule {
    allowed_origins = ["https://example.com", "http://localhost:3000"]

    allowed_methods = [
      "GET",
      "POST",
      "PUT",
      "DELETE",
      "HEAD"
    ]

    allowed_headers = ["*"]

    expose_headers = ["ETag", "Last-Modified"]

    max_age_seconds = 3000
  }
}
```

