### Description:
This Terraform program creates two S3 buckets: one for storing server access logs and another for storing the logs in a compressed format. The logs from the first S3 bucket are configured to be automatically uploaded to the second S3 bucket.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# Define the IAM role for S3 access
resource "aws_iam_role" "s3_access_logs_role" {
  name = "s3_access_logs_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "s3_access_logs_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.s3_access_logs_role.name
}

# Create the first S3 bucket for storing server access logs
resource "aws_s3_bucket" "access_logs_bucket" {
  bucket = "server-access-logs-bucket"

  tags = {
    Name = "Server Access Logs Bucket"
  }

  # Enable versioning for the bucket
  versioning {
    enabled = true
  }

  # Enable server access logging
  server_access_logging_policy {
    target_bucket = aws_s3_bucket.access_logs_archive_bucket.bucket
    target_prefix = "logs/"

    log_format = "common"
  }
}

# Create the second S3 bucket for storing compressed logs
resource "aws_s3_bucket" "access_logs_archive_bucket" {
  bucket = "server-access-logs-archive-bucket"

  tags = {
    Name = "Server Access Logs Archive Bucket"
  }

  # Enable versioning for the bucket
  versioning {
    enabled = true
  }
}

# Output the bucket names
output "access_logs_bucket_name" {
  value = aws_s3_bucket.access_logs_bucket.bucket
}

output "access_logs_archive_bucket_name" {
  value = aws_s3_bucket.access_logs_archive_bucket.bucket
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **IAM Role**: An IAM role named `s3_access_logs_role` is created with permissions to read from S3 buckets.
- **S3 Buckets**:
  - `access_logs_bucket`: This bucket stores server access logs. It is configured to enable versioning and server access logging, which sends logs to the `access_logs_archive_bucket`.
  - `access_logs_archive_bucket`: This bucket stores the compressed logs. It is also configured to enable versioning.
- **Outputs**: The names of both buckets are outputted for easy reference.

This configuration ensures that server access logs are automatically stored in a compressed format in a separate S3 bucket, making it easier to manage and analyze logs.

