### Description of the Terraform Program

The Terraform program will set up an infrastructure for an autograder for a CS class. This infrastructure will include:

1. **AWS S3 Bucket**: To store student code and the results of the autograding process.
2. **AWS CodeBuild Project**: To build and run the student code in a specific environment.
3. **IAM Roles**: To manage access to the S3 bucket and CodeBuild project.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# Default values for variables
variable "student_code_bucket_name" {
  default = "cs-class-autograder-code"
}

variable "results_bucket_name" {
  default = "cs-class-autograder-results"
}

variable "codebuild_project_name" {
  default = "cs-class-autograder-build"
}

# IAM Role for CodeBuild to access S3
resource "aws_iam_role" "codebuild_role" {
  name = "cs-class-autograder-codebuild"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild to access S3
resource "aws_iam_policy" "codebuild_policy" {
  name = "cs-class-autograder-codebuild-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.student_code_bucket.arn}/*",
          "${aws_s3_bucket.results_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# S3 Bucket for storing student code
resource "aws_s3_bucket" "student_code_bucket" {
  bucket = var.student_code_bucket_name
  acl    = "private"
}

# S3 Bucket for storing results
resource "aws_s3_bucket" "results_bucket" {
  bucket = var.results_bucket_name
  acl    = "private"
}

# CodeBuild Project to build and run student code
resource "aws_codebuild_project" "autograder" {
  name            = var.codebuild_project_name
  description     = "Autograder for CS class"
  source {
    type        = "GitHub"
    location   = "https://github.com/your-repo-url.git"
    git_clone_depth = 1
