    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/standard:4.0"
    environment_variables = [
      {
        name  = "CODEBUILD_S3_BUCKET"
        value = aws_s3_bucket.results_bucket.bucket
      },
      {
        name  = "CODEBUILD_S3_KEY_PREFIX"
        value = "results/"
      }
    ]
  }
}
```

