### Description:
This Terraform program creates an AWS S3 bucket to store code build output, an AWS VPC with a specific CIDR block, a VPC subnet, a security group, and an AWS CodeBuild project. The security group is configured to block all inbound and outbound traffic, ensuring no internet access. The CodeBuild project is set up to use the specified S3 bucket for storing artifacts, with a general-purpose build environment, Alpine Linux image, and Linux container type. It also includes a GitHub source with a specified depth and location.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create an S3 bucket to store code build output
resource "aws_s3_bucket" "code_build_output" {
  bucket = "code-build-output-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Create a VPC with a specific CIDR block
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a VPC subnet with a specific CIDR block
resource "aws_subnet" "main" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-west-2a"  # Specify your desired availability zone
}

# Create a security group to block all inbound and outbound traffic
resource "aws_security_group" "block_all_traffic" {
  name        = "block-all-traffic"
  description = "Security group to block all inbound and outbound traffic"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Link the security group to the VPC
resource "aws_network_interface_attachment" "main" {
  device_index = 0
  network_interface_id = aws_network_interface.main.id
  instance_id = aws_instance.codebuild_instance.id
  subnet_id = aws_subnet.main.id
  security_groups = [aws_security_group.block_all_traffic.id]
}

# Create an EC2 instance to run the CodeBuild project
resource "aws_instance" "codebuild_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Use an appropriate AMI for your region
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"  # Replace with your key pair name

  vpc_security_group_ids = [aws_security_group.block_all_traffic.id]

  tags = {
    Name = "CodeBuildInstance"
  }
}

# Create an AWS CodeBuild project
resource "aws_codebuild_project" "codebuild_project" {
  name          = "student-code-build"
  description = "CodeBuild project to build student code"

  artifacts {
    type = "S3"
    location = aws_s3_bucket.code_build_output.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/alpine:latest"
    type         = "LINUX_CONTAINER"
  }

  source {
    type = "GITHUB"
    location = "https://github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id     = aws_vpc.main.id
    subnets    = [aws_subnet.main.id]
    security_group_ids = [aws_security_group.block_all_traffic.id]
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **S3 Bucket**: An S3 bucket named `code-build-output-bucket` is created with private ACL and versioning enabled.
- **VPC and Subnet**: A VPC with a CIDR block of `10.0.0.0/16` and a subnet with a CIDR block of `10.0.0.0/24` are created.
- **Security Group**: A security group named `block-all-traffic` is created to block all inbound and outbound traffic.
- **EC2 Instance**: An EC2 instance is created to run the CodeBuild project, linked to the VPC and security group.
- **CodeBuild Project**: A CodeBuild project is created with the specified artifacts, environment, source, and VPC configuration.

