  resource_id = aws_api_gateway_resource.cat_pictures_resource.id
  http_method = "POST"

  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_picture_integration" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id = aws_api_gateway_resource.cat_pictures_resource.id
  http_method = aws_api_gateway_method.upload_picture.http_method

  type             = "AWS_PROXY"
  integration_http_method = "POST"
  uri              = "arn:aws:apigateway:${var.region}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_picture_handler.arn}/invocations"
}

