### Description of the Terraform Program

The Terraform program will create the necessary AWS resources to set up a video streaming site. This includes:

1. **AWS CloudFront Origin Access Control (OAC)**: To restrict access to the S3 bucket containing the video content.
2. **AWS CloudFront Distribution**: To deliver the video content to users globally.
3. **AWS Route53 Zone**: To manage DNS records for the domain.
4. **AWS S3 Bucket**: To store the video content.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site."
  type        = string
  default     = "example.com"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store video content."
  type        = string
  default     = "video-streaming-bucket"
}

resource "aws_s3_bucket" "video_streaming_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }
}

resource "aws_s3_bucket_policy" "video_streaming_bucket_policy" {
  bucket = aws_s3_bucket.video_streaming_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.video_streaming_bucket.arn}",
          "${aws_s3_bucket.video_streaming_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_control" "video_streaming_oac" {
  origin_access_control_id = "oac-${var.domain_name}"
  comment                 = "Origin Access Control for ${var.domain_name}"

  origin_access_identity = aws_cloudfront_origin_access_identity.video_streaming_oai.id
}

resource "aws_cloudfront_origin_access_identity" "video_streaming_oai" {
  comment = "Origin Access Identity for ${var.domain_name}"
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_streaming_cname" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = var.domain_name
  type    = "CNAME"
  ttl     = 300
  records = [aws_cloudfront_distribution.video_streaming_distribution.domain_name]
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_streaming_bucket.bucket_domain_name
    origin_id   = "s3-oai-${var.domain_name}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_control.video_streaming_oac.origin_access_identity
    }
  }

  enabled             = true
  is_ipv6_enabled     = false
  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-oai-${var.domain_name}"
    viewer_protocol_policy = "allow-all"
    min_ttl            = 0
    default_ttl         = 3600
    max_ttl            = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  logging_config {
    bucket = "logs-${var.domain_name}.s3.amazonaws.com"
    prefix = "cloudfront-logs/"
  }

  tags = {
    Name = "Video Streaming Distribution"
  }
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured to use the `us-east-1` region.
- **Variables**: Two variables are defined: `domain_name` and `s3_bucket_name`. Default values are provided for these variables.
- **S3 Bucket**: An S3 bucket is created with private ACL and a website configuration for serving static files.
- **S3 Bucket Policy**: A policy is attached to the S3 bucket to allow public access to the bucket and its contents.
- **CloudFront Origin Access Control (OAC)**: An OAC is created to restrict access to the S3 bucket.
- **CloudFront Origin Access Identity (OAI)**: An OAI is created to be used with the OAC.
- **Route53 Zone**: A Route53 zone is created for the specified domain.
- **Route53 CNAME Record**: A CNAME record is created to point the domain to the CloudFront distribution.
- **CloudFront Distribution**: A CloudFront distribution is created with the S3 bucket as the origin, allowing public access via HTTPS. The distribution is configured to serve static files with caching enabled.

