### Description of the Terraform Program

The Terraform program will create a scalable video streaming site infrastructure using AWS services. It will include:

1. **AWS VPC**: A virtual private cloud to isolate the infrastructure from the public internet.
2. **AWS Subnets**: Public and private subnets to separate web traffic and internal services.
3. **AWS Route53**: A DNS service to manage domain names and route traffic to the load balancer.
4. **AWS Load Balancer**: An Application Load Balancer (ALB) to distribute incoming traffic across multiple EC2 instances.
5. **AWS EC2 Instances**: Multiple EC2 instances to host the video streaming application.
6. **IAM Roles**: IAM roles to provide necessary permissions for the EC2 instances and the load balancer.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  default = "10.0.2.0/24"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "instance_count" {
  default = 3
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  count          = 1
  vpc_id         = aws_vpc.main.id
  cidr_block     = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_subnet" "private" {
  count          = 1
  vpc_id         = aws_vpc.main.id
  cidr_block     = var.private_subnet_cidr_block
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.main.id
  subnet_id      = aws_subnet.public[0].id
}

resource "aws_eip" "main" {}

resource "aws_security_group" "web" {
  name        = "web-sg"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Allow SSH and HTTP traffic"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web" {
  count          = var.instance_count
  ami             = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.instance_type
  key_name       = "your-key-pair-name" # Replace with your key pair name
  security_groups = [aws_security_group.web.id]

  subnet_id = aws_subnet.public[0].id

  tags = {
    Name = "web-server-${count.index}"
  }
}

resource "aws_instance" "app" {
  count          = var.instance_count
  ami             = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = var.instance_type
  key_name       = "your-key-pair-name" # Replace with your key pair name
  security_groups = [aws_security_group.app.id]

  subnet_id = aws_subnet.private[0].id

  tags = {
    Name = "app-server-${count.index}"
  }
}

resource "aws_alb" "main" {
  name               = "video-streaming-alb"
  subnets            = aws_subnet.public[*].id
  security_groups     = [aws_security_group.web.id]
  internal           = false
  enable_deletion_protection = false

  listener {
    port     = 80
    protocol = "HTTP"
    default_action {
      type = "forward"
      target_group_arn = aws_lb_target_group.main.arn
    }
  }
}

resource "aws_lb_target_group" "main" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    timeout_seconds     = 30
    interval_seconds    = 30
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
  }

  target_type = "instance"
}

resource "aws_lb_target_group_attachment" "web" {
  count          = var.instance_count
  target_group_arn = aws_lb_target_group.main.arn
  target_id       = aws_instance.web[count.index].id
}

resource "aws_lb_target_group_attachment" "app" {
  count          = var.instance_count
  target_group_arn = aws_lb_target_group.main.arn
  target_id       = aws_instance.app[count.index].id
}
```

### Explanation

- **Provider Configuration**: The `provider "aws"` block specifies the AWS region where the infrastructure will be deployed.
- **Variables**: Variables are defined to allow customization of the VPC CIDR block, public and private subnet CIDR blocks, instance type, and number of instances.
- **VPC and Subnets**: The `aws_vpc` and `aws_subnet` resources create a VPC with public and private subnets.
- **Route Tables**: Route tables are configured to route traffic to the internet and a NAT gateway for private subnets.
- **Internet Gateway and NAT Gateway**: These resources provide connectivity to the internet and private subnets.
- **Security Groups**: Security groups are created to control inbound and outbound traffic for the web and app servers.
- **EC2 Instances**: Multiple EC2 instances are launched in the private subnets, each running the same AMI and configured with the appropriate security group.
- **Application Load Balancer (ALB)**: An ALB is set up to distribute traffic across the EC2 instances, with a target group that checks the health of the instances.
- **Target Group Attachments**: The ALB is attached to the target group, which manages the instances.

This configuration ensures a scalable and secure video streaming site infrastructure using AWS services.

