### Description:
This Terraform program defines an AWS VPC with a CIDR block of `10.0.0.0/16`, three subnets, a security group, a load balancer, a target group, a listener, a target group attachment, and a Route53 zone with alias records.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  default = [
    "10.0.4.0/24",
    "10.0.5.0/24",
    "10.0.6.0/24"
  ]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

resource "aws_subnet" "subnets" {
  count          = length(var.subnet_cidrs)
  vpc_id         = aws_vpc.main.id
  cidr_block     = var.subnet_cidrs[count.index]
  availability_zone = "us-east-1a" # Adjust based on your availability zones
}

resource "aws_security_group" "main" {
  name        = "allow_http"
  description = "Allow HTTP traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Allow traffic from the VPC
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]      # Allow traffic from any IP
  }
}

resource "aws_lb" "main" {
  name               = "test-video-stream-lb"
  subnets            = aws_subnet.subnets[*].id
  security_groups     = [aws_security_group.main.id]
  load_balancer_type = "application"
}

resource "aws_lb_target_group" "main" {
  name     = "test-video-stream-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol           = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_target_group_attachment" "main" {
  target_group_arn = aws_lb_target_group.main.arn
  target_id       = aws_instance.main.id
}

resource "aws_instance" "main" {
  ami           = "ami-0c55b159cbfafe1f0" # Latest Ubuntu AMI
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"    # Replace with your key pair name

  tags = {
    Name = "test-video-stream-instance"
  }
}

resource "aws_route53_zone" "main" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb_alias" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "lb.test-video-stream.com"
  type    = "A"
  alias {
    evaluate_target_health = true
    hosted_zone_id = aws_lb.main.dns_name
    name = aws_lb.main.dns_name
  }
}

resource "aws_route53_record" "domain_alias" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "test-video-stream.com"
  type    = "AAAA"
  alias {
    evaluate_target_health = true
    hosted_zone_id = aws_lb.main.dns_name
    name = aws_lb.main.dns_name
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-east-1`.
- **Variables**: Default values are provided for `vpc_cidr` and `subnet_cidrs`.
- **VPC**: A VPC is created with the specified CIDR block.
- **Subnets**: Three subnets are created within the VPC, each with a different CIDR block.
- **Security Group**: A security group allows HTTP traffic from the VPC and egress from any IP on port 80.
- **Load Balancer**: An application load balancer is created with the specified subnets and security group.
- **Target Group**: A target group is associated with the load balancer and listens on port 80.
- **Listener**: A listener forwards traffic to the target group.
- **Target Group Attachment**: An instance is attached to the target group.
- **Route53 Zone**: A Route53 zone is created for `test-video-stream.com`.
- **Alias Records**: Two alias records are created for the load balancer and the domain name, evaluating target health.

Make sure to replace `"your-key-pair-name"` with your actual AWS key pair name. Also, adjust the `availability_zone` in the `aws_subnet` resources if you have specific availability zones available in your region.

