### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "db_name" {
  default = "my_random_db"
}

variable "db_username" {
  default = "my_random_user"
}

resource "aws_db_instance" "mysql_instance" {
  engine              = "mysql"
  engine_version      = "8.0.23"
  allocated_storage   = 20
  instance_class     = "db.t2.micro"
  username           = var.db_username
  password           = random_string.mysql_password.result
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.default.id]

  tags = {
    Name = var.db_name
  }
}

resource "random_string" "mysql_password" {
  length = 16
  special = true
}

resource "aws_db_subnet_group" "default" {
  name       = "my_db_subnet_group"
  subnet_ids = aws_subnet.public.*.id

  tags = {
    Name = "my_db_subnet_group"
  }
}

resource "aws_security_group" "default" {
  name        = "my_db_security_group"
  description = "Allow inbound MySQL traffic"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my_db_security_group"
  }
}

resource "aws_subnet" "public" {
  count = 2

  cidr_block          = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

data "aws_availability_zones" "available" {}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured to use the `us-east-1` region.
- **Variables**: Two variables, `db_name` and `db_username`, are defined with default values. These will be used to name the database and user.
- **Random Password**: A `random_string` resource generates a random password for the MySQL user.
- **DB Instance**: An `aws_db_instance` resource creates the MySQL database instance. It uses the generated password and a randomly selected subnet and security group.
- **Subnet Group and Security Group**: `aws_db_subnet_group` and `aws_security_group` resources manage the subnets and security groups for the database instance.
- **Subnets**: `aws_subnet` resources create two public subnets in the `us-east-1` region.
- **Availability Zones**: `data.aws_availability_zones.available` retrieves the available availability zones in the region.

