### Description:
This Terraform program sets up a Virtual Private Cloud (VPC) with public subnets and security groups. It also creates a PostgreSQL database instance within the VPC, ensuring secure access through a designated security group.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Default variables
variable "db_instance_name" {
  default = "my-postgres-db"
}

variable "db_instance_type" {
  default = "db.t2.micro"
}

variable "db_instance_username" {
  default = "postgres"
}

variable "db_instance_password" {
  default = "SecurePassword123!"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "MyVPC"
  }
}

# Public Subnet Configuration
resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = ["10.0.${count.index + 1}.0/24", "10.0.${count.index + 2}.0/24"]
  vpc_id         = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet${count.index + 1}"
  }
}

# Internet Gateway Configuration
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "InternetGateway"
  }
}

# Route Table Configuration
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

# Associate Public Subnets with Route Table
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group Configuration for Database Access
resource "aws_security_group" "database_access" {
  name        = "DatabaseAccessSG"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Allow access from anywhere
  }

  tags = {
    Name = "DatabaseAccessSG"
  }
}

# EC2 Instance Configuration for PostgreSQL Database
resource "aws_instance" "postgres_db" {
  ami           = "ami-0c55b159cbfafe1f0"  # Use an appropriate AMI for PostgreSQL
  instance_type = var.db_instance_type
  key_name       = "my-key-pair"  # Replace with your key pair name
  vpc_security_group_ids = [aws_security_group.database_access.id]
  subnet_id         = aws_subnet.public[0].id

  root_block_device {
    volume_size = 20
  }

  user_data = <<-EOF
    #!/bin/bash
    sudo apt-get update
    sudo apt-get install -y postgresql postgresql-contrib
    sudo systemctl start postgresql
    sudo systemctl enable postgresql
    sudo -u postgres psql -c "CREATE DATABASE ${var.db_instance_name};"
    sudo -u postgres psql -c "CREATE USER ${var.db_instance_username} WITH PASSWORD '${var.db_instance_password}';"
    sudo -u postgres psql -c "GRANT ALL PRIVILEGES ON DATABASE ${var.db_instance_name} TO ${var.db_instance_username};"
    EOF

  tags = {
    Name = var.db_instance_name
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Default values are provided for the database instance name, type, username, and password.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Public Subnets**: Two public subnets are created with CIDR blocks `10.0.1.0/24` and `10.0.2.0/24`.
- **Internet Gateway**: An internet gateway is attached to the VPC to allow outbound traffic.
- **Route Table**: A route table is created to route all traffic to the internet gateway.
- **Security Group**: A security group named `DatabaseAccessSG` is created to allow inbound traffic on port 5432 from anywhere.
- **EC2 Instance**: An EC2 instance running PostgreSQL is created in one of the public subnets, using the specified AMI, instance type, and security group. The instance is configured with a root block device of size 20GB and includes user data to set up the PostgreSQL database and user.

Make sure to replace `"ami-0c55b159cbfafe1f0"` with an appropriate AMI ID for PostgreSQL in your region. Also, ensure that you have a key pair named `"my-key-pair"` available in your AWS account.

