  default = "db.t3.micro"
}

variable "db_instance_size" {
  default = "5GB"
}

variable "db_instance_version" {
  default = "17.1"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "MyVPC"
  }
}

# Create a public subnet
resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = ["10.0.${count.index + 1}.0/24", "10.0.${count.index + 3}.0/24"]
  vpc_id         = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet${count.index + 1}"
  }
}

# Create a security group for database access
resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Allow access from anywhere
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

# Attach the security group to the public subnets
resource "aws_subnet_association" "public_sg" {
  count          = 2
  subnet_id      = aws_subnet.public[*].id
  security_group_id = aws_security_group.db_sg.id
}

# Create a PostgreSQL database instance
resource "aws_db_instance" "postgres" {
  allocated_storage  = var.db_instance_size
  engine            = "postgres"
  engine_version    = var.db_instance_version
  instance_class    = var.db_instance_type
  db_name           = var.db_instance_name
  username          = "admin"
  password          = "securepassword123"
  skip_final_snapshot = true

  vpc_security_groups = [aws_security_group.db_sg.id]

  tags = {
    Name = var.db_instance_name
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: Default values are provided for the database instance name, type, size, and version.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Public Subnets**: Two public subnets are created with CIDR blocks `10.0.1.0/24` and `10.0.3.0/24`, allowing instances to have public IP addresses.
- **Security Group**: A security group named `db-sg` is created with an ingress rule allowing PostgreSQL traffic (`5432/tcp`) from anywhere (`0.0.0.0/0`). Egress rules are set to allow all traffic.
- **Subnet Association**: The security group is attached to both public subnets.
- **PostgreSQL Database Instance**: A PostgreSQL database instance is created with the specified parameters, including the security group for access.

