  name        = "db-sg"
  description = "Security group for MySQL database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Allow access from anywhere
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

