### Description:
The Terraform program will provision a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services such as RDS, subnets, and KMS for encryption. A custom parameter group is created for PostgreSQL settings, and a security group is set up to manage access. The database instance is configured with specific specifications including storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_instance_identifier" {
  description = "The identifier for the PostgreSQL database instance"
  default     = "my-postgres-db"
}

variable "db_instance_class" {
  description = "The instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "db_engine_version" {
  description = "The version of the PostgreSQL engine"
  default     = "14.6"
}

variable "db_storage_size" {
  description = "The storage size of the PostgreSQL database in GB"
  default     = 20
}

variable "db_multi_az" {
  description = "Enable multi-AZ deployment for high availability"
  default     = true
}

variable "db_kms_key_id" {
  description = "The KMS key ID for encryption"
  default     = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"
}

variable "db_subnet_group_name" {
  description = "The name of the subnet group for the database"
  default     = "my-postgres-subnet-group"
}

variable "db_security_group_name" {
  description = "The name of the security group for the database"
  default     = "my-postgres-security-group"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  vpc_id         = aws_vpc.main.id
  cidr_block      = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_subnet" "private" {
  count          = 2
  vpc_id         = aws_vpc.main.id
  cidr_block      = "10.0.${count.index + 3}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]
}

resource "aws_db_subnet_group" "main" {
  name       = var.db_subnet_group_name
  subnet_ids = [for s in aws_subnet.public : s.id] + [for s in aws_subnet.private : s.id]
}

resource "aws_security_group" "main" {
  name        = var.db_security_group_name
  description = "Security group for the PostgreSQL database"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "main" {
  description = "KMS key for encrypting the PostgreSQL database"
}

resource "aws_kms_alias" "main" {
  alias_name = "alias/my-postgres-kms-key"
  target_key_id = aws_kms_key.main.key_id
}

resource "aws_rds_cluster_parameter_group" "main" {
  name       = "my-postgres-param-group"
  family     = "postgres14"
  description = "Custom parameter group for PostgreSQL settings"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "shared_buffers"
    value = "128MB"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier = var.db_instance_identifier
  engine            = "postgres"
  engine_version    = var.db_engine_version
  master_username   = "admin"
  master_password   = "securepassword123"
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.main.id]
  kms_key_id             = aws_kms_key.main.key_id
  multi_az              = var.db_multi_az
  parameter_group_name = aws_rds_cluster_parameter_group.main.name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Various variables are defined to allow customization of the database instance, such as identifier, class, engine version, storage size, multi-AZ deployment, KMS key, subnet group, and security group.
- **VPC and Subnets**: A VPC and two subnets (public and private) are created. Public subnets are mapped to enable public IP addresses, while private subnets are used for internal communication.
- **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL).
- **KMS Key**: A KMS key is created for encryption of the database instance.
- **Parameter Group**: A custom parameter group is created to configure specific PostgreSQL settings.
- **RDS Cluster**: The RDS cluster is provisioned with the specified parameters, including the use of the custom parameter group, KMS key, and multi-AZ deployment.

