### Description:
This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. It uses AWS RDS for the database, subnets for network isolation, and KMS for encryption. A custom parameter group is created to set specific PostgreSQL settings, and a security group is configured to manage access.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_instance_identifier" {
  description = "The identifier for the PostgreSQL database instance"
  default     = "my-postgres-db"
}

variable "db_instance_class" {
  description = "The instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "db_engine_version" {
  description = "The version of the PostgreSQL engine"
  default     = "15.4"
}

variable "db_storage_size" {
  description = "The storage size of the PostgreSQL database in GB"
  default     = 50
}

variable "db_multi_az" {
  description = "Whether to enable multi-AZ deployment for high availability"
  default     = true
}

variable "db_kms_key_id" {
  description = "The ARN of the KMS key for encryption"
  default     = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block      = "10.0.${count.index + 1}.0/24"
  vpc_id         = aws_vpc.example.id
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block      = "10.0.${count.index + 3}.0/24"
  vpc_id         = aws_vpc.example.id
}

resource "aws_security_group" "postgres" {
  name        = "postgres-sg"
  description = "Security group for PostgreSQL database"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgres" {
  name        = "postgres-param-group"
  family       = "postgres15"
  description = "Custom parameter group for PostgreSQL settings"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "shared_buffers"
    value = "128MB"
  }
}

resource "aws_db_subnet_group" "postgres" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.public.*.id, aws_subnet.private.*.id]
}

resource "aws_rds_cluster" "postgres" {
  cluster_identifier = var.db_instance_identifier
  engine            = "postgres"
  engine_version    = var.db_engine_version
  master_username   = "admin"
  master_password   = "securepassword123"
  db_subnet_group_name = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  multi_az            = var.db_multi_az
  kms_key_id           = var.db_kms_key_id

  parameter_group_name = aws_db_parameter_group.postgres.name
}

output "db_endpoint" {
  value = aws_rds_cluster.postgres.endpoint
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Various variables are defined to allow customization of the database instance, such as identifier, class, engine version, storage size, multi-AZ deployment, and KMS key.
- **VPC and Subnets**: A VPC and two subnets (public and private) are created to isolate the database.
- **Security Group**: A security group allows inbound traffic on port 5432 for PostgreSQL connections.
- **Parameter Group**: A custom parameter group is created to set specific PostgreSQL settings.
- **DB Subnet Group**: A DB subnet group is associated with the subnets to ensure the database can access them.
- **RDS Cluster**: An RDS cluster is provisioned with the specified parameters, including encryption using the KMS key.
- **Output**: The endpoint of the database is output for easy access.

