This Terraform program sets up a PostgreSQL 15 database instance on AWS RDS within specific public subnets. The instance is configured with managed settings for low maintenance, and it uses a "db.t3.micro" instance type with 5 GB of allocated storage. The configuration includes IAM roles for managing access to the RDS instance.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define the VPC and subnets
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create an IAM role for RDS access
resource "aws_iam_role" "rds_access" {
  name = "rds-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
