### Description:
This Terraform program sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_instance_name" {
  default = "my-mysql-db"
}

variable "db_instance_class" {
  default = "db.t2.micro"
}

variable "db_instance_engine" {
  default = "mysql"
}

variable "db_instance_engine_version" {
  default = "5.7"
}

variable "db_instance_allocated_storage" {
  default = 20
}

variable "db_instance_username" {
  default = "admin"
}

variable "db_instance_password" {
  default = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database access"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "db_instance" {
  allocated_storage      = var.db_instance_allocated_storage
