### Description:
This Terraform program sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a 200 GB 15.3 PostgresSQL RDS instance with public accessibility, linked to the defined subnets and security group, outputting the database endpoint for connectivity.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_instance_name" {
  default = "my-postgres-db"
}

variable "db_instance_class" {
  default = "db.t4g.micro"
}

variable "db_storage_type" {
  default = "gp2"
}

variable "db_instance_size" {
  default = "200"
}

variable "db_instance_engine" {
  default = "postgres"
}

variable "db_instance_engine_version" {
  default = "15.3"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db" {
  allocated_storage  = var.db_instance_size
  engine            = var.db_instance_engine
  engine_version    = var.db_instance_engine_version
  instance_class    = var.db_instance_class
  storage_type      = var.db_storage_type
