### Description:
This Terraform program sets up a 5 GB PostgreSQL database instance in AWS, including the necessary networking resources within a custom VPC and subnet. The database instance is configured with specific parameters such as engine version, instance size, storage, and maintenance window. The program also includes IAM roles for database access and network security.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define the VPC and Subnet
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "example-subnet"
  }
}

# Create a Security Group for Database Access
resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM Role for Database Access
resource "aws_iam_role" "db_role" {
  name = "db-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach an IAM Policy to the Role
resource "aws_iam_policy" "db_policy" {
  name = "db-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "ec2:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "db_policy_attachment" {
  role       = aws_iam_role.db_role.name
  policy_arn = aws_iam_policy.db_policy.arn
}

# Create the RDS Database Instance
resource "aws_db_instance" "example" {
  allocated_storage  = 5
  engine            = "postgres"
  engine_version    = "13.6"
  instance_class    = "db.t2.micro"
  db_name           = "mydatabase"
  username          = "admin"
  password          = "securepassword123"
  vpc_security_groups = [aws_security_group.db_sg.id]
  subnet_ids         = [aws_subnet.example.id]
  backup_retention_period = 7
  maintenance_window = "mon:00:00-mon:03:00"
  skip_final_snapshot = true
}
```

