### Description:
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_name" {
  default = "my_aurora_db"
}

variable "db_username" {
  default = "admin_user"
}

variable "db_password" {
  default = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = "10.0.${count.index + 1}.0/24"
  availability_zone = aws_availability_zone.main.name[count.index]
  vpc_id         = aws_vpc.main.id
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block     = "10.0.${count.index + 3}.0/24"
  availability_zone = aws_availability_zone.main.name[count.index]
  vpc_id         = aws_vpc.main.id
}

resource "aws_security_group" "aurora" {
  name        = "aurora_sg"
  description = "Security group for Aurora DB"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "proxy" {
  name        = "proxy_sg"
  description = "Security group for Aurora Proxy"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "${var.db_name}-cluster"
  engine                 = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.07.1"
  master_username        = var.db_username
  master_password        = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  backup_retention_period = 7
  skip_final_snapshot    = true

  tags = {
    Name = "Aurora Cluster"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.db_name}-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "Aurora Subnet Group"
  }
}

resource "aws_rds_cluster_instance" "aurora_primary" {
  cluster_identifier      = aws_rds_cluster.aurora.cluster_identifier
  instance_class          = "db.r5.large"
  engine                 = aws_rds_cluster.aurora.engine
  engine_version          = aws_rds_cluster.aurora.engine_version
  master_username        = aws_rds_cluster.aurora.master_username
  master_password        = aws_rds_cluster.aurora.master_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  tags = {
    Name = "Aurora Primary Instance"
  }
}

resource "aws_rds_cluster_instance" "aurora_replica" {
  cluster_identifier      = aws_rds_cluster.aurora.cluster_identifier
  instance_class          = "db.r5.large"
  engine                 = aws_rds_cluster.aurora.engine
  engine_version          = aws_rds_cluster.aurora.engine_version
  master_username        = aws_rds_cluster.aurora.master_username
  master_password        = aws_rds_cluster.aurora.master_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  tags = {
    Name = "Aurora Replica Instance"
  }
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${var.db_name}-credentials"
  description = "Secrets Manager for Aurora DB credentials"

  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_iam_role" "aurora_proxy" {
  name = "aurora_proxy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aurora_proxy_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AuroraProxyAccess"
  role       = aws_iam_role.aurora_proxy.name
}

resource "aws_rds_proxy" "aurora_proxy" {
  name                  = "${var.db_name}-proxy"
  debug_logging_enabled = false
  vpc_subnet_ids        = aws_subnet.public[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]

  auth {
    type = "secrets_manager"
    secrets_manager_secret_arn = aws_secretsmanager_secret.db_credentials.arn
    secret_manager_username   = var.db_username
  }

  tags = {
    Name = "Aurora Proxy"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **Variables**: Default values are provided for database name, username, and password.
- **VPC and Subnets**: A VPC with two public and two private subnets is created.
- **Security Groups**: Security groups are defined for the Aurora cluster and the proxy.
- **RDS Cluster**: An Aurora cluster is set up with a primary and replica instance.
- **Secrets Manager**: Credentials are stored securely using Secrets Manager.
- **IAM Role and Policy**: An IAM role is created for the proxy to access the Secrets Manager.
- **RDS Proxy**: A proxy is set up to manage connections to the Aurora cluster using the stored credentials.

