### Description:
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The backup retention period for the RDS cluster is set to 5 days, and the preferred backup window is from 7 AM to 9 AM.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Create subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id          = aws_vpc.example.id
  cidr_block      = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count = 2
  vpc_id          = aws_vpc.example.id
  cidr_block      = "10.0.${count.index + 3}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

# Create a security group for public access
resource "aws_security_group" "public" {
  name        = "public-access-sg"
  description = "Allow inbound traffic on port 3306 for MySQL"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a security group for private access
resource "aws_security_group" "private" {
  name        = "private-access-sg"
  description = "Allow inbound traffic on port 3306 for MySQL"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.public.*.cidr_block]
  }
}

# Create an IAM role for RDS
resource "aws_iam_role" "rds" {
  name = "rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "rds_access" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSRDSDefaultServiceRole"
  role       = aws_iam_role.rds.name
}

# Create a Secrets Manager secret for database credentials
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "my-rds-db-credentials"

  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}

# Create a Secrets Manager secret version
resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}

# Create an RDS Aurora MySQL cluster
resource "aws_rds_cluster" "example" {
  cluster_identifier      = "my-rds-cluster"
  engine                 = "aurora-mysql"
  engine_version         = "5.7.mysql_aurora.2.07.1"
  master_username        = "admin"
  master_password        = var.master_password
  db_subnet_group_name   = aws_db_subnet_group.example.name
  vpc_security_group_ids = [aws_security_group.public.id, aws_security_group.private.id]
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  skip_final_snapshot    = true
}

# Create a DB subnet group
resource "aws_db_subnet_group" "example" {
  name       = "my-rds-subnet-group"
  description = "Subnet group for RDS cluster"
  subnet_ids = aws_subnet.public.*.id
}

# Create an RDS Aurora MySQL proxy
resource "aws_rds_proxy" "example" {
  name                  = "my-rds-proxy"
  engine_family         = "aurora-mysql"
  vpc_subnet_ids        = aws_subnet.public.*.id
  vpc_security_group_ids = [aws_security_group.public.id, aws_security_group.private.id]
  auth {
    username = "admin"
    secret_arn = aws_secretsmanager_secret_version.db_credentials_version.arn
  }
}
```

### Variables:
To use this Terraform program, you need to define the `master_password` variable. You can do this by adding the following to your `terraform.tfvars` file:

```hcl
master_password = "YourStrongPassword123!"
```

Replace `"YourStrongPassword123!"` with a strong password of your choice.

