### Description:
This Terraform program will create a basic Amazon Lightsail instance. The instance will be configured with a public IP address, a default security group, and a root user key pair. It will also include a basic setup for a web server using Nginx.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to any AWS region
}

variable "instance_name" {
  default = "lightsail-instance"
}

variable "key_pair_name" {
  default = "lightsail-key-pair"
}

resource "aws_key_pair" "example" {
  key_name   = var.key_pair_name
  public_key = file("~/.ssh/id_rsa.pub")  # Replace with your public key path
}

resource "aws_lightsail_instance" "example" {
  name              = var.instance_name
  availability_zone = "us-east-1a"  # You can change this to any available zone
  blueprint_id      = "ubuntu_20_04"
  bundle_id         = "nano_1_0"

  public_ip_address_enabled = true

  tags = {
    Name = var.instance_name
  }
}

resource "aws_lightsail_static_ip" "example" {
  name = "${var.instance_name}-ip"
}

resource "aws_lightsail_static_ip_attachment" "example" {
  static_ip_name = aws_lightsail_static_ip.example.name
  instance_name  = aws_lightsail_instance.example.name
}

resource "aws_security_group" "example" {
  name        = "${var.instance_name}-sg"
  description = "Allow HTTP and SSH access"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lightsail_instance_public_port" "http" {
  instance_name = aws_lightsail_instance.example.name
  port          = 80
  protocol      = "tcp"
}

resource "aws_lightsail_instance_public_port" "ssh" {
  instance_name = aws_lightsail_instance.example.name
  port          = 22
  protocol      = "tcp"
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Ubuntu 20.04 AMI
  instance_type = "t2.micro"
  key_name       = aws_key_pair.example.key_name
  vpc_security_group_ids = [aws_security_group.example.id]

  provisioner "remote-exec" {
    inline = [
      "sudo apt-get update",
      "sudo apt-get install -y nginx",
      "echo 'Hello, World!' > /var/www/html/index.html",
      "sudo systemctl restart nginx"
    ]
  }
}
```

