### Description:
This Terraform program will create an AWS Lightsail instance running MySQL, set up daily backups between 16:00 and 16:30, and schedule maintenance tasks for Tuesdays between 17:00 and 17:30.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # Change to your desired region
}

variable "lightsail_instance_name" {
  default = "mysql-instance"
}

variable "lightsail_mysql_version" {
  default = "5.7"
}

variable "lightsail_backup_window_start" {
  default = "16:00"
}

variable "lightsail_backup_window_end" {
  default = "16:30"
}

variable "lightsail_maintenance_window_start" {
  default = "17:00"
}

variable "lightsail_maintenance_window_end" {
  default = "17:30"
}

resource "aws_lightsail_instance" "mysql_instance" {
  name              = var.lightsail_instance_name
  availability_zone = "us-east-1a"  # Change to your desired Availability Zone
  blueprint_id      = "app_wordpress"
  bundle_id         = "nano_1vcpu_1gb"

  # Configure MySQL settings
  mysql_settings {
    version = var.lightsail_mysql_version
  }

  # Enable automatic backups
  auto_snapshot_enabled = true

  # Set backup window
  backup_window {
    start_time = var.lightsail_backup_window_start
    end_time   = var.lightsail_backup_window_end
  }

  # Schedule maintenance window
  maintenance_window {
    start_time = var.lightsail_maintenance_window_start
    end_time   = var.lightsail_maintenance_window_end
  }
}

# Create an IAM role for Lightsail instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# Attach an IAM policy to the role
resource "aws_iam_role_policy_attachment" "lightsail_instance_policy_attachment" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/LightsailDefaultServiceRole"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired region (`us-east-1`).
- **Variables**: Various variables are defined to allow customization of the instance name, MySQL version, backup window, and maintenance window.
- **Lightsail Instance**: An AWS Lightsail instance is created with the specified name, blueprint, and bundle. MySQL settings are configured, and automatic backups are enabled with a custom backup window.
- **IAM Role**: An IAM role is created for the Lightsail instance to manage access. The role is attached to the Lightsail instance to ensure it has the necessary permissions.

This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75. Make sure to adjust the region, Availability Zone, and other parameters as needed for your specific use case.

### Description:
This Terraform program creates an AWS Lightsail instance running PostgreSQL and sets up a final snapshot of the database upon its deletion. The program includes IAM roles for managing access to the Lightsail instance and the database.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Lightsail Instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for Database Access
resource "aws_iam_role" "database_access_role" {
  name = "database-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the roles
resource "aws_iam_role_policy_attachment" "lightsail_instance_policy" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/LightsailDefaultServiceRole"
}

resource "aws_iam_role_policy_attachment" "database_access_policy" {
  role       = aws_iam_role.database_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSReadOnlyAccess"
}

# Lightsail Instance
resource "aws_lightsail_instance" "postgres_instance" {
  name              = "postgres-instance"
  availability_zone = "us-west-2a"
  blueprint_id      = "ubuntu_20_04"
  bundle_id         = "nano_1vcpu_1gb"

  # Attach the IAM role to the instance
  tags = {
    Name = "postgres-instance"
  }

  # Enable automatic snapshots on instance deletion
  auto_snapshot_on_deletion = true

  # Security group
  security_groups = ["default"]

  # User data to install PostgreSQL
  user_data = <<-EOF
    #!/bin/bash
    sudo apt-get update
    sudo apt-get install -y postgresql postgresql-contrib
    sudo systemctl start postgresql
    sudo systemctl enable postgresql
    EOF
}

# Database
resource "aws_rds_instance" "postgres_db" {
  identifier           = "postgres-db"
  engine               = "postgres"
  engine_version       = "13.6"
  allocated_storage     = 20
  db_subnet_group_name = "default-vpc-sg"
  vpc_security_group_ids = [aws_lightsail_instance.postgres_instance.security_groups[0]]

  # Attach the IAM role for database access
  iam_database_authentication_enabled = true
  master_username                  = "admin"
  master_password                  = "SecurePassword123!"

  # Enable automated backups
  backup_retention_period = 7

  # Enable deletion protection
  deletion_protection = true

  # Final snapshot on instance deletion
  final_snapshot_identifier = "${aws_lightsail_instance.postgres_instance.name}-final-snapshot"
}

# Output the database endpoint
output "db_endpoint" {
  value = aws_rds_instance.postgres_db.endpoint
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Roles**: Two IAM roles are created: one for the Lightsail instance and another for database access. These roles are attached to the instance and the database respectively.
- **Lightsail Instance**: A Lightsail instance is created using the `ubuntu_20_04` blueprint and `nano_1vcpu_1gb` bundle. It is tagged with a name and has automatic snapshots enabled on deletion.
- **Database**: An RDS PostgreSQL instance is created with the `postgres` engine and version `13.6`. It is attached to the same VPC security group as the Lightsail instance. Automated backups and deletion protection are enabled, and a final snapshot is created on instance deletion.
- **Output**: The output provides the endpoint of the database, which can be used to connect to the database from other services or applications.

### Description:
This Terraform program will create an AWS Lightsail instance running PostgreSQL. The instance will be configured to apply changes immediately without waiting for a maintenance window, ensuring minimal downtime.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "lightsail_instance_name" {
  description = "Name of the Lightsail instance"
  default     = "postgres-instance"
}

variable "lightsail_instance_type" {
  description = "Type of Lightsail instance (e.g., micro, small)"
  default     = "micro"
}

variable "lightsail_database_name" {
  description = "Name of the PostgreSQL database"
  default     = "mydatabase"
}

variable "lightsail_database_username" {
  description = "Username for the PostgreSQL database"
  default     = "adminuser"
}

variable "lightsail_database_password" {
  description = "Password for the PostgreSQL database"
  default     = "securepassword123"
}

resource "aws_lightsail_instance" "postgres_instance" {
  name              = var.lightsail_instance_name
  availability_zone = aws_availability_zone.main.zone
  instance_type    = var.lightsail_instance_type

  # Enable immediate updates
  disable_auto_snapshot = false
}

resource "aws_lightsail_db_instance" "postgres_db" {
  name               = var.lightsail_database_name
  engine             = "postgres"
  engine_version     = "14.6"
  username           = var.lightsail_database_username
  password           = var.lightsail_database_password
  port               = 5432
  availability_zone = aws_availability_zone.main.zone
  instance_type      = var.lightsail_instance_type

  # Enable immediate updates
  disable_auto_snapshot = false
}

resource "aws_availability_zone" "main" {
  name = "us-west-2a"  # Specify your desired Availability Zone
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: Several variables are defined to allow customization of the instance name, type, database name, username, and password.
- **Lightsail Instance**: An instance is created using the specified name, type, and disables automatic snapshots to ensure immediate updates.
- **Lightsail Database**: A PostgreSQL database is created on the instance, specifying the engine version, username, password, port, and disables automatic snapshots.
- **Availability Zone**: The availability zone is specified for both the instance and the database to ensure they are colocated.

This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75. Make sure to replace the default values with your specific requirements.

