### Description:
This Terraform program creates a Lightsail instance with multiple attached disks. The instance is configured with a specific size and type, and the disks are provisioned with different sizes and types. The program also includes IAM roles for managing access to the Lightsail instance and its disks.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "disk_size_gb" {
  default = 20
}

variable "disk_count" {
  default = 3
}

resource "aws_lightsail_instance" "example" {
  name        = "lightsail-instance"
  availability_zone = "us-west-2a"
  instance_type = var.instance_type

  block_storage {
    disk_size_gb = var.disk_size_gb
    disk_type     = "gp2"
  }

  for_each = range(var.disk_count)
  block_storage {
    disk_size_gb = var.disk_size_gb
    disk_type     = "gp2"
  }
}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_instance_policy_attachment" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/LightsailDefaultServiceRole"
