### Description:
This Terraform program will create an AWS Lightsail distribution using an S3 bucket as the origin. The distribution will be configured to serve static websites and can be accessed via a custom domain if provided.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

variable "bucket_name" {
  description = "The name of the S3 bucket to use as the origin"
  default     = "my-lightsail-bucket"
}

variable "domain_name" {
  description = "The domain name for the Lightsail distribution (optional)"
  default     = ""
}

resource "aws_s3_bucket" "origin_bucket" {
  bucket = var.bucket_name

  website {
    index_document = "index.html"
    error_document = "error.html"
  }
}

resource "aws_s3_bucket_policy" "origin_bucket_policy" {
  bucket = aws_s3_bucket.origin_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "${aws_s3_bucket.origin_bucket.arn}",
          "${aws_s3_bucket.origin_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_lightsail_distribution" "distribution" {
  name = "MyLightsailDistribution"

  origin {
    type = "S3"
    s3_origin_config {
      s3_bucket_name = aws_s3_bucket.origin_bucket.bucket
    }
  }

  cache_behavior {
    path_pattern = "/*"
    behavior = "cache"
  }

  if (var.domain_name != "") {
    domain_name = var.domain_name
    certificate_arn = aws_acm_certificate.certificate.arn
  }
}

resource "aws_acm_certificate" "certificate" {
  domain = var.domain_name
  validation_method = "DNS"

  subject_alternative_names = [var.domain_name]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_acm_certificate_validation" "validation" {
  certificate_arn = aws_acm_certificate.certificate.arn

  validation_record_fqdns = aws_route53_record.validation_record_fqdns
}

resource "aws_route53_zone" "zone" {
  name = var.domain_name
}

resource "aws_route53_record" "validation_record" {
  zone_id = aws_route53_zone.zone.id
  name    = aws_acm_certificate_validation.validation.record_name
  type    = aws_acm_certificate_validation.validation.record_type
  ttl     = 60

  records = [aws_acm_certificate_validation.validation.record_value]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Two variables are defined: `bucket_name` and `domain_name`. The `bucket_name` defaults to `my-lightsail-bucket`, and `domain_name` defaults to an empty string.
- **S3 Bucket**: An S3 bucket is created with a website configuration to serve static files.
- **Bucket Policy**: A policy is attached to the S3 bucket to allow public access to objects.
- **Lightsail Distribution**: A Lightsail distribution is created using the S3 bucket as the origin. It includes a cache behavior for all paths.
- **ACM Certificate**: If a domain name is provided, an ACM certificate is requested and validated using Route 53 records.
- **Route 53 Zone and Record**: If a domain name is provided, a Route 53 zone and record are created to point the domain to the Lightsail distribution.

This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

