### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Default region
}

# IAM Role for the Glacier Vault
resource "aws_iam_role" "glacier_vault_notification_role" {
  name = "glacier-vault-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for the Glacier Vault Notification Role
resource "aws_iam_policy" "glacier_vault_notification_policy" {
  name = "glacier-vault-notification-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketNotification",
          "s3:PutBucketNotification"
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::your-glacier-bucket-name"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "glacier_vault_notification_policy_attachment" {
  role       = aws_iam_role.glacier_vault_notification_role.name
  policy_arn = aws_iam_policy.glacier_vault_notification_policy.arn
}

# S3 Glacier Vault
resource "aws_glacier_vault" "example_vault" {
  name = "example-vault"
}

# S3 Bucket Notification Configuration
resource "aws_s3_bucket_notification_configuration" "example_notification" {
  bucket = aws_glacier_vault.example_vault.arn

  lambda_function_configuration {
    events = ["s3:ObjectCreated:*"]

    lambda_function_arn = aws_lambda_function.example_function.arn
  }
}

# Lambda Function to Handle Notifications
resource "aws_lambda_function" "example_function" {
  filename      = "lambda_function_payload.zip"
  function_name = "example-function"
  handler       = "index.handler"
  runtime       = "python3.8"

  role = aws_iam_role.glacier_vault_notification_role.arn

  source_code_hash = filebase64sha256("lambda_function_payload.zip")
}

# Example Lambda Function Payload (lambda_function_payload.zip)
file "lambda_function_payload.zip" {
  content = <<EOF
import json
import boto3

def lambda_handler(event, context):
    print("Received event:", json.dumps(event, indent=2))
    return {
        'statusCode': 200,
        'body': json.dumps('Hello from Lambda!')
    }
EOF
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the default region `us-west-2`.
- **IAM Roles**: Two IAM roles are created: one for the Glacier vault (`glacier_vault_notification_role`) and another for the Lambda function (`example_function_role`). The Glacier role allows access to the Glacier vault, while the Lambda role allows it to interact with S3 and Lambda services.
- **IAM Policies**: Corresponding policies are attached to these roles to grant the necessary permissions.
- **S3 Glacier Vault**: A Glacier vault named `example-vault` is created.
- **S3 Bucket Notification**: The Glacier vault is configured to send notifications to a Lambda function when objects are created.
- **Lambda Function**: A simple Lambda function is defined to handle the notifications. It logs the received event and returns a success response.

Make sure to replace `"your-glacier-bucket-name"` with the actual name of your Glacier bucket. Also, ensure that the Lambda function code is correctly packaged and uploaded as `lambda_function_payload.zip`.

