  role       = aws_iam_role.glacier_vault_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlacierFullAccess"
}

resource "aws_iam_role_policy_attachment" "sns_topic_policy_attachment" {
  role       = aws_iam_role.glacier_vault_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSNSFullAccess"
}

resource "aws_sns_topic_subscription" "glacier_vault_notification" {
  topic_arn = aws_sns_topic.example.arn
  protocol  = "sqs"
  endpoint = aws_sns_topic_subscription.glacier_vault_notification.queue_url
}

