### Description:
This Terraform script sets up a basic AWS Network Load Balancer (NLB) that is attached to an EC2 instance running on the `t2.micro` instance type. The script includes necessary IAM roles for the NLB and EC2 instances, as well as default configurations for the resources.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# IAM Role for the EC2 Instance
resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Role for the NLB
resource "aws_iam_role" "nlb_role" {
  name = "nlb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Role Policy Attachment for EC2 Instance
resource "aws_iam_role_policy_attachment" "ec2_instance_policy_attachment" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ReadOnlyAccess"
}

# IAM Role Policy Attachment for NLB
resource "aws_iam_role_policy_attachment" "nlb_policy_attachment" {
  role       = aws_iam_role.nlb_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# EC2 Instance
resource "aws_instance" "example" {
  ami           = "ami-0c55b159cbfafe1f0" # Use a specific AMI ID
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"     # Replace with your key pair name

  iam_instance_profile {
    name = aws_iam_role.ec2_instance_role.name
  }

  tags = {
    Name = "example-ec2-instance"
  }
}

# Security Group for EC2 Instance
resource "aws_security_group" "example_sg" {
  name        = "example-sg"
  description = "Allow SSH access"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Attach Security Group to EC2 Instance
resource "aws_instance_sg_association" "example_sg_assoc" {
  instance_id = aws_instance.example.id
  security_group_id = aws_security_group.example_sg.id
}

# Network Load Balancer
resource "aws_lb" "example" {
  name               = "example-nlb"
  internal           = false
  subnets            = ["subnet-12345678", "subnet-23456789"] # Replace with your subnet IDs
  security_groups     = [aws_security_group.example_sg.id]
  load_balancer_type = "network"

  tags = {
    Name = "example-nlb"
  }
}

# Target Group
resource "aws_lb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.default.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = "traffic-port"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-target-group"
  }
}

# Listener
resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_lb_target_group.example.arn
    type             = "forward"
  }
}

# Associate EC2 Instance with Target Group
resource "aws_lb_target_group_attachment" "example" {
  target_group_arn = aws_lb_target_group.example.arn
  target_id       = aws_instance.example.id
  port             = 80
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Roles**: Two IAM roles (`ec2-instance-role` and `nlb-role`) are created to provide necessary permissions for the EC2 instance and the NLB, respectively.
- **EC2 Instance**: An `t2.micro` instance is launched with SSH access enabled. It uses the `ec2-instance-role` for IAM instance profile.
- **Security Group**: A security group allows SSH access to the EC2 instance.
- **Network Load Balancer (NLB)**: An NLB is created with two subnets and a security group. It listens on port 80 and forwards traffic to the target group.
- **Target Group**: A target group is set up to handle HTTP requests and is associated with the NLB.
- **Listener**: A listener is configured to forward incoming HTTP traffic to the target group.
- **Target Group Attachment**: The EC2 instance is added to the target group.

Make sure to replace placeholders like `your-key-pair-name`, `subnet-12345678`, and `subnet-23456789` with your actual values. Also, ensure that the AMI ID is correct for your region.

