### Description:
The Terraform program will create an AWS Application Load Balancer (ALB) along with necessary security groups, subnets, and listeners. The ALB will be configured to distribute incoming traffic across multiple target groups based on the specified rules.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "ID of the VPC where the ALB will be deployed"
  type        = string
  default     = "vpc-1234567890abcdef0"
}

variable "subnets" {
  description = "List of subnet IDs for the ALB"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-09876543"]
}

variable "security_group_ids" {
  description = "List of security group IDs for the ALB"
  type        = list(string)
  default     = ["sg-12345678", "sg-09876543"]
}

resource "aws_alb" "example_alb" {
  name               = "example-alb"
  internal           = false
  subnets            = var.subnets
  security_groups    = var.security_group_ids
  enable_deletion_protection = true

  tags = {
    Name = "example-alb"
  }
}

resource "aws_alb_listener" "example_listener" {
  load_balancer_arn = aws_alb.example_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_alb_target_group.example_target_group.arn
  }
}

resource "aws_alb_target_group" "example_target_group" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    timeout             = 30
    interval            = 30
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
  }

  tags = {
    Name = "example-target-group"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: 
  - `vpc_id`: The ID of the VPC where the ALB will be deployed.
  - `subnets`: A list of subnet IDs for the ALB.
  - `security_group_ids`: A list of security group IDs for the ALB.
- **ALB Resource**: An `aws_alb` resource is created with the specified properties, including `name`, `internal`, `subnets`, `security_groups`, and `enable_deletion_protection`.
- **Listener Resource**: An `aws_alb_listener` resource is created to listen on port 80 and forward traffic to the `example_target_group`.
- **Target Group Resource**: An `aws_alb_target_group` resource is created with the specified properties, including `name`, `port`, `protocol`, `vpc_id`, and `health_check`.

This configuration ensures that the ALB is properly set up with the necessary components to distribute traffic across target groups.

