### Description:
The Terraform script will create a Network Load Balancer (NLB) in AWS. The NLB will be configured to distribute incoming traffic across multiple target groups, which can be EC2 instances or other services. The script includes IAM roles for the load balancer and target groups, and it uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2" # Specify your desired AWS region
}

# IAM Role for the Network Load Balancer
resource "aws_iam_role" "nlb_role" {
  name = "nlb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for the Target Groups
resource "aws_iam_role" "target_group_role" {
  name = "target_group_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for the Network Load Balancer
resource "aws_iam_policy" "nlb_policy" {
  name = "nlb_policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVpcs",
          "ec2:ModifyInstanceAttribute",
          "ec2:RebootInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# IAM Policy for the Target Groups
resource "aws_iam_policy" "target_group_policy" {
  name = "target_group_policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVpcs",
          "ec2:ModifyInstanceAttribute",
          "ec2:RebootInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM policies to the roles
resource "aws_iam_role_policy_attachment" "nlb_policy_attachment" {
  role       = aws_iam_role.nlb_role.name
  policy_arn = aws_iam_policy.nlb_policy.arn
}

resource "aws_iam_role_policy_attachment" "target_group_policy_attachment" {
  role       = aws_iam_role.target_group_role.name
  policy_arn = aws_iam_policy.target_group_policy.arn
}

# Create a Network Load Balancer
resource "aws_lb" "nlb" {
  name               = "my-nlb"
  subnets            = ["subnet-12345678", "subnet-23456789"] # Replace with your subnet IDs
  security_groups     = ["sg-12345678"]                    # Replace with your security group ID
  internal           = false
  load_balancer_type = "network"

  tags = {
    Name = "MyNetworkLoadBalancer"
  }
}

# Create a Target Group
resource "aws_lb_target_group" "tg" {
  name     = "my-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.default.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = 80
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "MyTargetGroup"
  }
}

# Register targets with the Target Group
resource "aws_lb_target_group_attachment" "tg_attachment" {
  target_group_arn = aws_lb_target_group.tg.arn
  target_id        = aws_instance.instance.id
}

# Output the NLB DNS Name
output "nlb_dns_name" {
  value = aws_lb.nlb.dns_name
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **IAM Roles**: Two IAM roles (`nlb_role` and `target_group_role`) are created to allow the load balancer and target groups to perform necessary actions.
- **IAM Policies**: Two IAM policies (`nlb_policy` and `target_group_policy`) are defined to grant the necessary permissions to the roles.
- **Network Load Balancer**: A Network Load Balancer is created with specified subnets, security groups, and tags.
- **Target Group**: A Target Group is created with a specified port, protocol, VPC ID, and health check settings.
- **Target Group Attachment**: The instance is registered with the Target Group.
- **Output**: The DNS name of the Network Load Balancer is outputted for easy access.

This script assumes you have an existing VPC and security group. You need to replace placeholders like `subnet-12345678`, `sg-12345678`, and `instance.id` with your actual values.

