### Description:
This Terraform program defines a simple AWS Load Balancer that forwards traffic to one or more instances running in a target group. The load balancer is configured to use an Application Load Balancer (ALB), which is suitable for HTTP/HTTPS traffic. It includes IAM roles for the load balancer and target group, and it uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for the Load Balancer
resource "aws_iam_role" "alb_role" {
  name = "alb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for the Target Group
resource "aws_iam_role" "target_group_role" {
  name = "target_group_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for the Load Balancer
resource "aws_iam_policy" "alb_policy" {
  name = "alb_policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVpcs",
          "ec2:ModifyInstanceAttribute",
          "ec2:RebootInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# IAM Policy for the Target Group
resource "aws_iam_policy" "target_group_policy" {
  name = "target_group_policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVpcs",
          "ec2:ModifyInstanceAttribute",
          "ec2:RebootInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach Policies to Roles
resource "aws_iam_role_policy_attachment" "alb_policy_attachment" {
  role       = aws_iam_role.alb_role.name
  policy_arn = aws_iam_policy.alb_policy.arn
}

resource "aws_iam_role_policy_attachment" "target_group_policy_attachment" {
  role       = aws_iam_role.target_group_role.name
  policy_arn = aws_iam_policy.target_group_policy.arn
}

# EC2 Instance
resource "aws_instance" "example_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t2.micro"
  key_name      = "my-key-pair"            # Ensure this key pair exists

  tags = {
    Name = "ExampleInstance"
  }
}

# Target Group
resource "aws_lb_target_group" "example_target_group" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example_vpc.id

  health_check {
    path                = "/"
    interval             = 30
    timeout              = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "ExampleTargetGroup"
  }
}

# Target Group Attachment
resource "aws_lb_target_group_attachment" "example_target_group_attachment" {
  target_group_arn = aws_lb_target_group.example_target_group.arn
  target_id       = aws_instance.example_instance.id
}

# Application Load Balancer
resource "aws_lb" "example_alb" {
  name               = "example-alb"
  internal           = false
  subnets            = [aws_subnet.example_subnet.id]
  security_groups     = [aws_security_group.example_sg.id]
  enable_deletion_protection = true

  listener {
    port     = 80
    protocol = "HTTP"
    default_action {
      type = "forward"
      target_group_arn = aws_lb_target_group.example_target_group.arn
    }
  }

  tags = {
    Name = "ExampleALB"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **IAM Roles**: Two IAM roles (`alb_role` and `target_group_role`) are created to allow the load balancer and target group to access EC2 resources.
- **IAM Policies**: Two IAM policies (`alb_policy` and `target_group_policy`) are defined to grant the necessary permissions to the roles.
- **EC2 Instance**: An example EC2 instance is created with a basic AMI and key pair.
- **Target Group**: A target group is created with a health check and associated with the EC2 instance.
- **Target Group Attachment**: The EC2 instance is attached to the target group.
- **Application Load Balancer**: An Application Load Balancer is created with a listener forwarding traffic to the target group.

This configuration is deployable with Terraform version ~> 1.9.8 and requires the `hashicorp/aws` provider version ~> 5.75. Make sure to replace placeholders like `ami-0c55b159cbfafe1f0`, `my-key-pair`, and `example-vpc-id` with your actual values.

