### Description:
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). The ALB acts as a reverse proxy, distributing incoming requests across multiple targets, such as EC2 instances or other services. The NLB is used for internal communication between services within the same VPC.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the resources will be created."
  type        = string
  default     = "vpc-1234567890abcdef0"
}

variable "subnet_ids" {
  description = "A list of subnet IDs within the VPC."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-09876543"]
}

resource "aws_alb" "example_alb" {
  name               = "example-alb"
  subnets            = var.subnet_ids
  security_groups    = [aws_security_group.example_sg.id]
  internal           = false
  enable_cross_zone_load_balancing = true

  tags = {
    Name = "example-alb"
  }
}

resource "aws_security_group" "example_sg" {
  name        = "example-sg"
  description = "Security group for the ALB"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb_target_group" "example_target_group" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval             = 30
    timeout              = 5
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
  }

  tags = {
    Name = "example-target-group"
  }
}

resource "aws_alb_listener" "example_listener" {
  load_balancer_arn = aws_alb.example_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_alb_target_group.example_target_group.arn
  }
}

resource "aws_network_load_balancer" "example_nlb" {
  name               = "example-nlb"
  subnets            = var.subnet_ids
  security_groups    = [aws_security_group.example_sg.id]
  internal           = true

  tags = {
    Name = "example-nlb"
  }
}

resource "aws_network_load_balancer_target_group" "example_nlb_target_group" {
  name     = "example-nlb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval             = 30
    timeout              = 5
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
  }

  tags = {
    Name = "example-nlb-target-group"
  }
}

resource "aws_network_load_balancer_listener" "example_nlb_listener" {
  load_balancer_arn = aws_network_load_balancer.example_nlb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_network_load_balancer_target_group.example_nlb_target_group.arn
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Two variables, `vpc_id` and `subnet_ids`, are defined with default values. These can be overridden when applying the Terraform configuration.
- **ALB**: An Application Load Balancer is created with a listener on port 80 that forwards traffic to the target group.
- **Security Group**: A security group is created to allow inbound HTTP traffic on port 80.
- **Target Group**: A target group is created for both the ALB and NLB, with health checks enabled.
- **NLB**: A Network Load Balancer is created with a listener on port 80 that forwards traffic to the target group.
- **Network Load Balancer Target Group**: A target group is created for the NLB, with health checks enabled.

This setup ensures that traffic is distributed efficiently between the ALB and NLB, providing redundancy and high availability.

