### Description:
This Terraform program defines a simple AWS Load Balancer with a redirect action. The load balancer will redirect HTTP traffic to HTTPS, ensuring secure connections for incoming requests.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "redirect_code" {
  description = "The HTTP status code to use for the redirect"
  type        = string
  default     = "301"
}

resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  subnets            = ["subnet-12345678", "subnet-23456789"]
  security_groups    = ["sg-12345678"]
  enable_deletion_protection = true

  listener {
    protocol          = "HTTP"
    port              = 80
    default_action {
      type             = "redirect"
      redirect_config {
        protocol          = "HTTPS"
        port              = 443
        host              = "$host"
        path              = "$path"
        query_string       = "$query_string"
        http_redirect_code = var.redirect_code
      }
    }
  }

  listener {
    protocol          = "HTTPS"
    port              = 443
    ssl_policy         = "ELBSecurityPolicy-2016-08"
    certificates {
      certificate_arn = aws_acm_certificate.example.arn
    }
    default_action {
      type             = "forward"
      target_group_arn = aws_lb_target_group.example.arn
    }
  }
}

resource "aws_acm_certificate" "example" {
  domain_name = "example.com"
  validation_method = "DNS"

  validation_record_fqdns {
    name = aws_route53_record.example.name
    zone_id = aws_route53_zone.example.zone_id
  }
}

resource "aws_route53_zone" "example" {
  name = "example.com"
}

resource "aws_route53_record" "example" {
  zone_id = aws_route53_zone.example.zone_id
  name     = "example.com"
  type     = "CNAME"
  ttl      = 300
  records  = [aws_lb.example.dns_name]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **Variables**: A variable `redirect_code` is defined to specify the HTTP status code for the redirect. The default value is `301`.
- **Load Balancer (`aws_lb`)**:
  - Two listeners are defined: one for HTTP on port 80 and another for HTTPS on port 443.
  - The HTTP listener redirects traffic to HTTPS using the `redirect_config` block.
  - The HTTPS listener uses an ACM certificate and forwards traffic to a target group.
- **ACM Certificate (`aws_acm_certificate`)**:
  - An ACM certificate is created for the domain `example.com` using DNS validation.
- **Route 53 Zone (`aws_route53_zone`)**:
  - A Route 53 zone is created for `example.com`.
- **Route 53 Record (`aws_route53_record`)**:
  - A CNAME record is created to point `example.com` to the DNS name of the load balancer.

This configuration ensures that all HTTP traffic is redirected to HTTPS, providing a secure connection for incoming requests.

