### Description:
This Terraform program defines a load balancer with an authentication action using AWS Cognito. The load balancer will route traffic to an application server, ensuring that only authenticated users can access it. The program includes IAM roles for the load balancer and the application server, as well as a default VPC and subnet.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Default VPC and Subnet
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.default.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

# Application Server Security Group
resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Security group for the application server"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Application Server Instance
resource "aws_instance" "app_server" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t2.micro"
  key_name      = "my-key-pair"          # Replace with your key pair name

  security_groups = [aws_security_group.app_sg.id]

  tags = {
    Name = "app-server"
  }
}

# Load Balancer
resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  subnets            = [aws_subnet.public.id]
  security_groups     = [aws_security_group.app_sg.id]
  enable_deletion_protection = true
}

# Listener for HTTP
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.example.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}

# Target Group
resource "aws_lb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.default.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = "traffic-port"
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
    timeout_seconds       = 30
    interval_seconds      = 30
  }
}

# IAM Role for Load Balancer
resource "aws_iam_role" "lb_role" {
  name = "lb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Role for Application Server
resource "aws_iam_role" "app_role" {
  name = "app-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Policy for Load Balancer
resource "aws_iam_policy" "lb_policy" {
  name = "lb-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to Load Balancer Role
resource "aws_iam_role_policy_attachment" "lb_policy_attachment" {
  role       = aws_iam_role.lb_role.name
  policy_arn = aws_iam_policy.lb_policy.arn
}

# IAM Policy for Application Server
resource "aws_iam_policy" "app_policy" {
  name = "app-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-idp:AdminInitiateAuth",
          "cognito-idp:RespondToAuthChallenge"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to Application Server Role
resource "aws_iam_role_policy_attachment" "app_policy_attachment" {
  role       = aws_iam_role.app_role.name
  policy_arn = aws_iam_policy.app_policy.arn
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **Default VPC and Subnet**: A basic VPC and public subnet are created.
- **Application Server Security Group**: A security group allows HTTP traffic and ensures the server is accessible.
- **Application Server Instance**: An EC2 instance is launched with a specified AMI and key pair.
- **Load Balancer**: An Elastic Load Balancer is set up with a listener for HTTP traffic.
- **Target Group**: A target group is associated with the load balancer, routing traffic to the application server.
- **IAM Roles and Policies**: Two IAM roles are created for the load balancer and the application server, each with appropriate policies to allow necessary actions.

