### Description:
This Terraform program defines a simple AWS Load Balancer with a target group. The load balancer will distribute incoming traffic across multiple EC2 instances. It includes a VPC, subnets, security groups, an internet gateway, a route table, an elastic IP address, and an EC2 instance. The target group will register the EC2 instance for load balancing.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "image_id" {
  default = "ami-0c55b159cbfafe1f0"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = "10.0.${count.index + 1}.0/24"
  vpc_id         = aws_vpc.example.id
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_security_group" "example" {
  name        = "allow_http"
  description = "Allow HTTP access"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id
}

resource "aws_route_table" "example" {
  vpc_id = aws_vpc.example.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.example.id
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.example.id
}

resource "aws_eip" "example" {
  vpc = true
}

resource "aws_instance" "example" {
  ami           = var.image_id
  instance_type = var.instance_type
  key_name       = "my-key-pair"
  security_groups = [aws_security_group.example.id]
  subnet_id      = aws_subnet.public[0].id
  associate_public_ip_address = true

  tags = {
    Name = "example-instance"
  }
}

resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups     = [aws_security_group.example.id]
  enable_deletion_protection = false

  listener {
    protocol = "HTTP"
    port     = 80
  }
}

resource "aws_lb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = 80
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
}

resource "aws_lb_target_group_attachment" "example" {
  target_group_arn = aws_lb_target_group.example.arn
  target_id       = aws_instance.example.id
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Variables**: Two variables, `instance_type` and `image_id`, are defined with default values. You can modify these to suit your needs.
- **VPC and Subnets**: A VPC and two public subnets are created.
- **Security Group**: A security group allows HTTP traffic.
- **Internet Gateway and Route Table**: An internet gateway and route table are set up to allow outbound traffic.
- **Elastic IP Address**: An Elastic IP address is allocated for the load balancer.
- **EC2 Instance**: An EC2 instance is launched in one of the public subnets, with HTTP access allowed.
- **Load Balancer**: A load balancer is created with a listener on port 80.
- **Target Group**: A target group is created with a health check and registered with the EC2 instance.
- **Target Group Attachment**: The EC2 instance is attached to the target group.

This configuration is deployable with Terraform version 1.9.8 and requires the `hashicorp/aws` provider version 5.75.5 or later.

