  name = "main-vpc"
  cidr = "10.0.0.0/16"

  azs                  = data.aws_availability_zones.available.names
  public_subnets       = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["*ubuntu-noble-24.04-amd64-server-*"]
  }
}

resource "aws_security_group" "lb-sg" {
  name = "lb-sg"
  vpc_id = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "lb-sg-ingress-rule" {
  from_port   = 80
  to_port     = 80
  ip_protocol = "tcp"
  cidr_ipv4   = "0.0.0.0/0"
  security_group_id = aws_security_group.lb-sg.id
}

resource "aws_vpc_security_group_egress_rule" "lb-sg-egress-rule" {
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
  security_group_id = aws_security_group.lb-sg.id
}


resource "aws_iam_role" "lambda_role" {
  name = "example-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "lambda_policy_attachment" {
  name       = "example-lambda-policy-attachment"
  roles      = [aws_iam_role.lambda_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "archive_file" "lambda-func" {
  type        = "zip"
  source_file = "./supplement/index.js"
  output_path = "./supplement/lambda_func.zip"
}

resource "aws_lambda_function" "example" {
  function_name = "example-lambda"
  role          = aws_iam_role.lambda_role.arn
  handler       = "index.handler"
  runtime       = "nodejs18.x"

  filename         = data.archive_file.lambda-func.output_path
  source_code_hash = data.archive_file.lambda-func.output_base64sha256
}

resource "aws_lambda_permission" "elb_invocation" {
  statement_id  = "AllowExecutionFromALB"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.example.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = aws_lb_target_group.target_group.arn
}

resource "aws_lb" "test" {
  subnets            = module.vpc.public_subnets
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb-sg.id]
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.test.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_lb_target_group" "target_group" {
  target_type = "lambda"
}

resource "aws_lb_target_group_attachment" "ec2_attach" {
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id = aws_lambda_function.example.arn
}

LLM Output #0:
### Description:
This Terraform program defines a Load Balancer with a Lambda Target Group. The Load Balancer will distribute incoming traffic across multiple Lambda functions, providing high availability and scalability. The configuration includes a VPC, subnets, security groups, and a load balancer with a target group attached to it.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_arns" {
  type        = list(string)
  description = "List of ARNs for the Lambda functions to be targeted by the load balancer."
  default     = []
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block      = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index + 1)
  vpc_id         = aws_vpc.example.id
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block      = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index + 3)
  vpc_id         = aws_vpc.example.id

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "public" {
  name        = "public-sg"
  description = "Security group for public subnet"
  vpc_id       = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "private" {
  name        = "private-sg"
  description = "Security group for private subnet"
  vpc_id       = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_security_group.public.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups     = [aws_security_group.public.id]
  enable_deletion_protection = false

  listener {
    protocol            = "HTTP"
    port                = 80
    default_action {
      type             = "forward"
      target_group_arn = aws_lb_target_group.example.arn
    }
  }
}

resource "aws_lb_target_group" "example" {
  name     = "example-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    timeout_seconds     = 30
    interval_seconds    = 30
    healthy_threshold_count = 2
    unhealthy_threshold_count = 2
  }

  target_type = "lambda"

  lambda_target {
    function_name = var.lambda_function_arns[0]
    invocation_type = "RequestResponse"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-east-1`.
- **Variables**: The `lambda_function_arns` variable is used to specify the ARNs of the Lambda functions to be targeted by the load balancer. It defaults to an empty list.
- **VPC and Subnets**: A VPC with two public and two private subnets is created.
- **Security Groups**: Security groups are defined for both public and private subnets, allowing HTTP traffic on port 80.
- **Load Balancer**: An Application Load Balancer (ALB) is created with a listener on port 80 forwarding traffic to the target group.
- **Target Group**: A target group is created with a Lambda target, using the ARNs provided in the `lambda_function_arns` variable. The target group uses HTTP as the protocol and checks the health of the Lambda functions every 30 seconds with a timeout of 30 seconds.

