### Description:
This Terraform program creates a memory-optimized PostgreSQL database instance using AWS RDS. The instance is configured with specific parameters for optimal performance on memory-intensive workloads.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_name" {
  default = "memory_optimized_db"
}

variable "db_username" {
  default = "postgres"
}

variable "db_password" {
  default = "securepassword123"
}

resource "aws_rds_instance" "memory_optimized_postgres" {
  engine              = "postgres"
  engine_version      = "14.6"
  instance_class     = "db.t3.large"  # Memory-optimized instance class
  allocated_storage   = 20
  storage_type       = "gp3"
  db_subnet_group_name = aws_db_subnet_group.memory_optimized_db.name
  vpc_security_group_ids = [aws_security_group.memory_optimized_db.id]
  username           = var.db_username
  password           = var.db_password
  skip_final_snapshot = true

  tags = {
    Name = "memory_optimized_postgres"
  }
}

resource "aws_db_subnet_group" "memory_optimized_db" {
  name       = "memory_optimized_db_subnet_group"
  subnet_ids = [aws_subnet.public_subnet.id]

  tags = {
    Name = "memory_optimized_db_subnet_group"
  }
}

resource "aws_security_group" "memory_optimized_db" {
  name        = "memory_optimized_db_sg"
  description = "Security group for memory-optimized PostgreSQL"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "memory_optimized_db_sg"
  }
}

resource "aws_subnet" "public_subnet" {
  cidr_block          = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  vpc_id             = aws_vpc.main.id

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main_vpc"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: Variables are defined for the database name, username, and password. Default values are provided.
- **RDS Instance**: An `aws_rds_instance` resource is created with the following specifications:
  - Engine: PostgreSQL
  - Engine Version: 14.6
  - Instance Class: `db.t3.large`, which is a memory-optimized instance class.
  - Allocated Storage: 20 GB
  - Storage Type: `gp3`
  - Subnet Group: `memory_optimized_db_subnet_group`
  - VPC Security Group: `memory_optimized_db_sg`
  - Username and Password: Set from variables.
  - Skip Final Snapshot: Set to `true` to avoid creating a final snapshot upon deletion.
- **DB Subnet Group**: A `aws_db_subnet_group` resource is created to manage the subnets where the RDS instance will reside.
- **Security Group**: An `aws_security_group` resource is created to allow inbound traffic on port 5432 (PostgreSQL).
- **Subnet**: A `aws_subnet` resource is created for the public subnet.
- **VPC**: A `aws_vpc` resource is created for the virtual private cloud.

This configuration ensures that the PostgreSQL instance is deployed in a secure and scalable manner, optimized for memory usage.

