### Description:
This Terraform program creates an Amazon RDS instance by restoring it from an S3 bucket. It includes IAM roles for the RDS instance and S3 access, and uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance."
  default     = "my-rds-instance"
}

variable "db_instance_class" {
  description = "The class of the RDS instance."
  default     = "db.t2.micro"
}

variable "db_engine" {
  description = "The database engine to use."
  default     = "mysql"
}

variable "db_engine_version" {
  description = "The version of the database engine to use."
  default     = "5.7"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket containing the backup file."
  default     = "my-backup-bucket"
}

variable "s3_backup_file_key" {
  description = "The key of the backup file in the S3 bucket."
  default     = "backup-file.sql.gz"
}

resource "aws_iam_role" "rds_restore_role" {
  name = "rds-restore-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_restore_policy" {
  role       = aws_iam_role.rds_restore_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSRestoreAccess"
}

resource "aws_s3_bucket_policy" "rds_restore_policy" {
  bucket = aws_s3_bucket.rds_backup_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Resource = "${aws_s3_bucket.rds_backup_bucket.arn}/${
          aws_s3_bucket_object.rds_backup_file.key}"
      }
    ]
  })
}

resource "aws_s3_bucket" "rds_backup_bucket" {
  bucket = var.s3_bucket_name
}

resource "aws_s3_bucket_object" "rds_backup_file" {
  bucket = aws_s3_bucket.rds_backup_bucket.bucket
  key    = var.s3_backup_file_key
  source = "path/to/your/backup-file.sql.gz"
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage  = 20
  db_instance_class = var.db_instance_class
  engine            = var.db_engine
  engine_version    = var.db_engine_version
  instance_identifier = var.db_instance_identifier
  master_username   = "admin"
  master_password   = "password123"
  backup_retention_period = 7
  iam_database_authentication_enabled = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  restore_db_from_s3 {
    s3_bucket_name = aws_s3_bucket.rds_backup_bucket.bucket
    s3_key         = aws_s3_bucket_object.rds_backup_file.key
    db_snapshot_identifier = aws_db_snapshot.rds_snapshot.id
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_snapshot" "rds_snapshot" {
  db_instance_identifier = aws_db_instance.rds_instance.id
  db_snapshot_identifier = "${var.db_instance_identifier}-snapshot"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **Variables**: Variables are defined for the RDS instance identifier, class, engine, engine version, S3 bucket name, and backup file key.
- **IAM Roles**: Two IAM roles are created: one for the RDS instance (`rds_restore_role`) and another for S3 access (`rds_restore_policy`).
- **S3 Bucket and Object**: An S3 bucket is created, and a bucket object is uploaded with the backup file.
- **RDS Instance**: An RDS instance is created by restoring it from the S3 backup file. The `restore_db_from_s3` block specifies the S3 bucket and key, and the `db_snapshot_identifier` is set to a snapshot created from the RDS instance.
- **Lifecycle**: The `create_before_destroy` lifecycle rule ensures that the RDS instance is recreated before the old one is destroyed, which is useful for rolling upgrades.

