  file_system_id = aws_efs_file_system.example.id

  backup_policy {
    rules {
      rule_name = "DailyBackup"
      schedule = "cron(0 0 * * ? *)"
      start_time = "00:00:00"
      retention_days = 30
    }
  }
}
```

