### Description:
This Terraform program creates an Amazon Elastic File System (EFS) and a mount target for it. The EFS will be accessible from EC2 instances in the same VPC. The program includes IAM roles for EFS access and EC2 instances, and uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Default values for variables
variable "efs_name" {
  default = "my-efs"
}

variable "vpc_id" {
  default = "vpc-1234567890abcdef0"  # Replace with your VPC ID
}

variable "subnet_id" {
  default = "subnet-1234567890abcdef1"  # Replace with your subnet ID
}

# IAM role for EFS access
resource "aws_iam_role" "efs_access" {
  name = "efs-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for EFS access
resource "aws_iam_policy" "efs_access_policy" {
  name = "efs-access-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:DescribeMountTargets",
          "elasticfilesystem:CreateMountTarget",
          "elasticfilesystem:DeleteMountTarget",
          "elasticfilesystem:DescribeFileSystems",
          "elasticfilesystem:CreateFileSystem",
          "elasticfilesystem:DeleteFileSystem",
          "elasticfilesystem:CreateTags",
          "elasticfilesystem:DeleteTags"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "efs_access_policy_attachment" {
  role       = aws_iam_role.efs_access.name
  policy_arn = aws_iam_policy.efs_access_policy.arn
}

# Create the EFS file system
resource "aws_efs_file_system" "example" {
  name = var.efs_name

  tags = {
    Name = var.efs_name
  }
}

# Create the mount target
resource "aws_efs_mount_target" "example" {
  file_system_id = aws_efs_file_system.example.id
  subnet_id     = var.subnet_id

  tags = {
    Name = "${var.efs_name}-mount-target"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region.
- **Variables**: Default values are provided for `efs_name`, `vpc_id`, and `subnet_id`. These can be overridden when applying the configuration.
- **IAM Roles**: Two IAM roles are created: one for EFS access (`efs-access-role`) and another for attaching policies (`efs-access-policy`). The policy allows EFS to perform various operations on the file system.
- **EFS File System**: An EFS file system is created with a specified name and tags.
- **Mount Target**: A mount target is created for the EFS file system in the specified subnet, allowing EC2 instances to mount the file system.

This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75. Make sure to replace placeholder values with your actual AWS credentials and network configurations.

