### Description:
This Terraform program creates a Virtual Private Cloud (VPC) in AWS, along with multiple public subnets and a route table that is configured to allow internet access through an Internet Gateway. The program includes IAM roles for managing the VPC and subnets, and it uses default values for variables where applicable.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for managing the VPC
resource "aws_iam_role" "vpc_manager" {
  name = "vpc-manager"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for managing subnets
resource "aws_iam_role" "subnet_manager" {
  name = "subnet-manager"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# VPC Creation
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "Main VPC"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Main Internet Gateway"
  }
}

# Route Table Creation
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "Public Route Table"
  }
}

# Subnet Creation
resource "aws_subnet" "public_1" {
  cidr_block          = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  vpc_id             = aws_vpc.main.id

  tags = {
    Name = "Public Subnet 1"
  }
}

resource "aws_subnet" "public_2" {
  cidr_block          = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  vpc_id             = aws_vpc.main.id

  tags = {
    Name = "Public Subnet 2"
  }
}

# Associate Subnets with Route Table
resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **IAM Roles**: Two IAM roles (`vpc_manager` and `subnet_manager`) are created to manage the VPC and subnets, respectively. These roles allow EC2 instances to assume these roles.
- **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Internet Gateway**: An Internet Gateway is attached to the VPC to provide internet access.
- **Route Table**: A public route table is created with a default route that points to the Internet Gateway.
- **Subnets**: Two public subnets are created in different Availability Zones (`us-west-2a` and `us-west-2b`) within the VPC.
- **Route Table Associations**: Each subnet is associated with the public route table to enable internet access.

This configuration is deployable with Terraform version ~> 1.9.8 and hashicorp/aws ~> 5.75.

