### Description:
This Terraform program sets up a Virtual Private Cloud (VPC) in the AWS region, creating two subnets in different Availability Zones, an Internet Gateway, and a Route Table for internet access. It also defines a Security Group to allow access to MySQL and PostgreSQL databases on their default ports from any IP address. Additionally, it creates a Database Subnet Group that includes both subnets.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  default = [
    "10.0.1.0/24",
    "10.0.2.0/24"
  ]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "public_subnets" {
  count          = length(var.subnet_cidr_blocks)
  cidr_block     = var.subnet_cidr_blocks[count.index]
  vpc_id         = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "PublicSubnet${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "InternetGateway"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public_subnets)
  subnet_id      = aws_subnet.public_subnets[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "database_sg" {
  name        = "DatabaseSG"
  description = "Security group for database access"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseSG"
  }
}

resource "aws_db_subnet_group" "database_sg_group" {
  name       = "DatabaseSubnetGroup"
  subnet_ids = aws_subnet.public_subnets[*].id

  tags = {
    Name = "DatabaseSubnetGroup"
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the desired AWS region (`us-west-2`).
- **Variables**: Two variables are defined: `vpc_cidr_block` and `subnet_cidr_blocks`. Default values are provided for these variables.
- **VPC**: A VPC is created with a specified CIDR block.
- **Subnets**: Two public subnets are created in different Availability Zones, associated with the VPC.
- **Internet Gateway**: An Internet Gateway is attached to the VPC.
- **Route Table**: A public route table is created with a default route to the Internet Gateway.
- **Security Group**: A security group is defined to allow MySQL (port 3306) and PostgreSQL (port 5432) traffic from any IP address.
- **Database Subnet Group**: A database subnet group is created, including both public subnets.

This configuration is deployable with Terraform version ~> 1.9.8 and hashicorp/aws ~> 5.75.

